window.__D("text/torat-chaim/c019",{"p":[[2300540352,"<b>והנה</b> כ\"ז שהתורה ומצות נקראים<sup data-n=\"5394\">168</sup> שמותיו ממש היינו שנעשים בחי' כלים ושמות באצי' עצמו שנק' שמות[יו] של עצמות אור המאציל גם באור [ו]כלי החכ' [דאצי'] וכן בחו\"ג וכה\"ג, עד שכל בחי' אדם העליון דאצי' בפנימיותו שהוא שם הוי' הכללי הנ\"ל נמשך ע\"י [אור ד]תומ\"צ כשנעשה מהם בבחי' כלים ושמות כמו בבחי' שם התואר הנ\"ל כשמתאחד עם שם העצם דאור תומ\"צ, [ו]כמ\"ש [בתורה] ואהי' אצלו [כו'] שעשועים<sup data-n=\"5395\">169</sup> כו' הרי שרש התורה בעצמות השעשועים שקדם לתענוג שבא בחכ' דאצי' ומחכ' למדות ע\"י שם הוי' שנק' שם מ\"ה מלגיו הנ\"ל ([ו]כמו ע\"י מצות צדקה וחסד למטה נעשה יחוד עליון באור [וכלי ה]חסד הנאצל שיאיר בו מפנימיות ועצמות דשם הוי' שבשם אל וכה\"ג, [הרי זהו למעלה הרבה משם הוי' שבאל שהוא אור וכלי חסד דאצי' וכה\"ג ב]שם ע\"ב דחכ'<sup data-n=\"5396\">170</sup> דאצי' ע\"י מצות ת\"ת למטה שעוסק בתורה לשמה נמשך מלמעלה משם ע\"ב דהוי' שבחכ' דאצי' כו'). וכ\"ז הוא בתושב\"כ שהוא בחי' אותיות ושמות העצמ[י'] של עצמות אוא\"ס [ממש] שע\"ז אמר כל הקורא בתורה קורא בשמותיו<sup data-n=\"5397\">171</sup> כו'. ועד\"ז אמרו אי' סופר ואי'<sup data-n=\"5398\">172</sup> כו' שהוא [ב]בחי' האצי' עצמו דשם אמרו דאיהו וחיוהי חד ממש שגילוי אוא\"ס שם בלי הפסק [ובלי אמצעי] רק ע\"י בחי' הקו\"ח שעובר שם<sup data-n=\"5399\">173</sup> באצי' כידוע, אבל בג' עולמות הנפרדים שהן בי\"ע שהן אחר הפסק הפרסא שבין אצי' לבריאה כנודע<sup data-n=\"5400\">174</sup> ושם אין גילוי אוא\"ס עצמו רק ע\"י בחי' המסך [ה]מבדיל שנק' הארה דהארה כמ\"ש באורך נראה אור<sup data-n=\"5401\">175</sup> [ו]כמ\"ש במ\"א. וא\"כ י\"ל איך יוכל להיות בחי' שם וכלי [ל]עצמות א\"ס כמו שם התואר הנ\"ל בעולמות הנפרדים עד שמתאחד עמהם כמו שמתאחד בשמות וכלים דאצי' בשם התואר הנ\"ל, וידוע דהתורה ירדה בד' עולמות אבי\"ע<sup data-n=\"5402\">176</sup> וכתיב הנסתרות להוי'<sup data-n=\"5403\">177</sup> כו' שהוא תומ\"צ דאצי' בשמות וכלים דאצי', אבל הנגלות לנו ולבנינו לשמור ולעשות<sup data-n=\"5404\">178</sup> בפו\"מ ה\"ז בא בעוה\"ז השפל כמו ציצית בצמר גשמי ותפילין בקלף גשמי וכה\"ג ואיך נעשה התפילין וציצית בצמר וקלף<sup data-n=\"5405\">179</sup> הגשמי בחי' כלי ושם לאוא\"ס שבאצי' כמו שמות העליונים דאצי' ממש, ואף בעולם הבריאה ויצי' כמו בגעה\"ע וגעה\"ת אחר שהפרסא מפסיק שם כנ\"ל גם שם לא יוכל להיות כלי ושם [ב]שם התואר במצות ותורה",[["5394","168","<b>ומצות נקראים</b>: יאיב: נק'."],["5395","169","<b>ואהי' אצלו </b>[כו']<b> שעשועים</b>: משלי ח, ל."],["5396","170","<b>ב]שם ע\"ב דחכ'</b>: נסמן לעיל פ' וארא פד, ד."],["5397","171","<b>כל הקורא בתורה קורא בשמותיו</b>: נסמן לעיל פ' שמות ז, ד."],["5398","172","<b>ואי'</b>: איאיב: ליתא."],["5399","173","<b>שם</b>: יאיב: ליתא."],["5400","174","<b>כנודע</b>: יאיב: ליתא."],["5401","175","<b>באורך נראה אור</b>: נסמן לעיל פ' וארא ס, ב."],["5402","176","<b>דהתורה. . אבי\"ע</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקכד. דרמ\"צ קג, ב. מאמרי אדה\"א שמות ח\"א ע' רצא. ויקרא ח\"ב ע' תסו. וש\"נ. דברים ח\"ג ס\"ע תשעט ואילך. מאמרים שנסמנו בריש המאמר. לעיל פ' וארא נח, ג. לקמן פ' תצוה שמב, א."],["5403","177","<b>הנסתרות להוי'</b>: נצבים כט, כח. ראה גם מאמרי אדה\"א דברים ח\"ג ע' תשפ. וש\"נ."],["5404","178","<b>הנגלות. . לשמור ולעשות</b>: נצבים שם [ושם: והנגלות לנו ולבנינו עד עולם לעשות — ראה לקמן פ' בשלח קנה, ג. פקודי תנג, ג. שה\"א פח, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670287\" data-slug=\"torat-chaim\" data-id=\"2300670287\">תו\"ח בראשית ה, ב</a> הערה 11]."],["5405","179","<b>בצמר וקלף</b>: איב: בצמר. ויא: דצומח."]]],[2300540375,"הרוחניות דשם. ואנו רואים להיפך שמן מעשה המצות שלנו בפו\"מ בגשמיות מזה נעש[ים] בחי' הכלים ושמות עליונים העצמי' לשכון בהם גילוי אוא\"ס עצמו באצי' וכמ\"ש ישראל מקדשי שמך<sup data-n=\"5406\">180</sup> כו'<sup data-n=\"5407\">181</sup> <span data-k=\"pg\">282</span> ּ [ש]הוא השמות דהוי' שבכל מצוה כנ\"ל וזה פלא לכאורה וד\"ל. אך הנה לזה הדבר שיוכל להיות גם בעולמות הנפרדים בחי' כלי ושם מיוחד [כ]שם התואר להתאחד עם גילוי אוא\"ס כמו בשמות [ה]עליונים דאצי' כנ\"ל הוא שעשו הנביאי' בנבואתם שבאו אחר קבלת התורה ע\"י משה, והוא במה שנתנבאו בשם צבאות כמו כה א' ה' צבאות<sup data-n=\"5408\">182</sup> וכו' דשם צבאות הוא ג\"כ מז' שמות שאי[נ]ן נמחקין רק דשם זה נעשה בבחי' שם התואר ביחוד שם וכלי גמור [כ]שאר השמות דאצי' ע\"י הנביאים דוקא.\n[ה] <b>וי\"ל</b> תחלה בשרש ענין הנביאים דהנה א' משה קיבל תורה מסיני<sup data-n=\"5409\">183</sup> ומסרה ליהושע ויהושע לזקנים וזקנים לנביאים, ולכאו' מה שייכות לנביאים עם קבלת התורה שהרי [אין הנביא רשאי לחדש דבר<sup data-n=\"5410\">184</sup> כו' בלי תוספות ובלי גרעון על תורת משה, וא\"כ מהו התועלת מנבואתם]<sup data-n=\"5411\">185</sup> בדבר ה' בנבואה האלק[י]ת וברוה\"ק וכו' ו[ל]מה גדלה מעלתם מכל הצדיקים ובעלי תורה עד שהעובר ע\"ד הנביא<sup data-n=\"5412\">186</sup> כעובר על מ\"ש בתורה [כו'], ואם מפני טוב תוכחת מוסר ש[ל]הם ורוב אזהרתם לקיים את התורה ומצות [כו'], דבר זה הרבה צדיקים יכולים להוכיח את העם [והי' מהם]<sup data-n=\"5413\">187</sup> הרבה [בכל דור] שהוכיחו את העם ולמה נבדל מעלת הנביאים במה שנק' נביא ה' כו'. אך הנה ע\"ד הפשוט שהנביאים לא הי' עיקר נבואתם רק לקיים את התומ\"צ [ש]לא יסור מן הדרך<sup data-n=\"5414\">188</sup> ימין ושמאל כמבואר בכל דברי הנביאים משמואל הנביא עד חגי זכרי' ומלאכי<sup data-n=\"5415\">189</sup> וכו' נביאים אחרונים<sup data-n=\"5416\">190</sup>. אמנם תוכחה שלהם מפני שהי' [בגילוי דבר ה' ממש בכלי הפה שלהם עשה רושם גדול בישראל גם מה בהיותם בגופים חומריים שיהי'] בהם גילוי אוא\"ס בבחי' כלי ושם ממש כמו כלים ושמות דאצי' שבתורה בבחי' שם התואר. דהנה פי' נביא לשון דבור כמו בורא ניב שפתים<sup data-n=\"5417\">191</sup> [ו]כאשר בא דבר ה' שבאצי' בפה הנביא ה\"ז בחי' גילוי ובקיעת האור מאצי' לבי\"ע עד עוה\"ז השפל בפה הנביא, וכידוע דשרש הנביאים בבחי' נו\"ה<sup data-n=\"5418\">192</sup> שמביאים גילוי [אור] השפע מלמעלה למטה כמו ישעי' בנו\"ה דבריאה<sup data-n=\"5419\">193</sup> ויחזקאל בנו\"ה דיצי'<sup data-n=\"5420\">194</sup> וכו'. וע\"כ אין בחי'<sup data-n=\"5421\">195</sup> זה",[["5406","180","<b>ישראל מקדשי שמך</b>: תפלת העמידה לשויו\"ט."],["5407","181","<b>כו'</b>: יאיב: כנ\"ל."],["5408","182","<b>כה א' ה' צבאות</b>: שמואל-א טו, ב."],["5409","183","<b>משה קיבל תורה מסיני</b>: אבות רפ\"א."],["5410","184","<b>אין הנביא. . דבר</b>: שבת קד, א. ראה רמב\"ם הל' יסוה\"ת רפ\"ט. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191197\" data-slug=\"likkutei-sichot\" data-id=\"1300191197\">לקו\"ש שופטים (כרך יט) ע' 184</a>."],["5411","185","[אין. . מנבואתם]: בתו\"ח כאן: הנביאים נבאו."],["5412","186","<b>שהעובר ע\"ד הנביא</b>: ראה גם סה\"מ להרמב\"ם מ\"ע קעב. הל' יסוה\"ת שם, ה\"ב. ה\"ג. וראה להלן קטו, א. לעיל צז, ד."],["5413","187","[והי' מהם]: בתו\"ח כאן: וה\"ז — והיו זה ( )."],["5414","188","<b>הדרך</b>: יאיב: הדבר."],["5415","189","<b>ומלאכי</b>: יאיב: ליתא."],["5416","190","<b>חגי. . נביאים אחרונים</b>: סוטה מח, ב."],["5417","191","<b>נביא. . בורא ניב שפתים</b>: נסמן לעיל פ' וארא נט, א."],["5418","192","<b>הנביאים בבחי' נו\"ה</b>: ראה פרדס (שעה\"כ) שכ\"ג מערכת אספקלריא. אגה\"ק סי\"ט. שה\"א צד, א בהערה 8."],["5419","193","<b>ישעי' בנו\"ה דבריאה</b>: ראה לקוטי הש\"ס להאריז\"ל יבמות מט, ב ד\"ה מנשה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381118\" data-slug=\"likkutei-torah\" data-id=\"4001381118\">לקו\"ת</a> להאריז\"ל ישעי' פ\"ו. לעיל צז, ד (בשם הע\"ח). סידור שער הק\"ש עט, א. דרושים שבהערה הבאה."],["5420","194","<b>ויחזקאל בנו\"ה דיצי'</b>: ראה זהר הרקיע יתרו פב, א (ע' נג). מאמרי אדה\"א נ\"ך ע' קמא. וש\"נ. הנחות תקע\"ז ע' כב. שעה\"י קמה, ב. שע\"ת קח, ב. שה\"א לד, א. פו, א. לעיל צז, ד. לקמן פ' בשלח קמח, ד. קצד, ג."],["5421","195","<b>בחי'</b>: יאיב: כח."]]],[2300540396,"בשאר צדיקים גדולים רק בנביאים שאין בחי' הפרסא מפסקת ביניהם כלל ויכולים לפעול ולעשות בחי' שם וכלי כמו שם התואר וכלי<sup data-n=\"5422\">196</sup> לגילוי אוא\"ס בג' עולמות הנפרדים בי\"ע להיות גם [שם] בחי' גילוי אוא\"ס בכלי ושם ביחוד האמיתי דאור וכלי כמו שם התואר [כ]נ\"ל וד\"ל. והיינו [ענין] שם צבאות שעיקר נבואתם הי' בשם צבאות כמו ישעי' שראה הוי' צבאות<sup data-n=\"5423\">197</sup> יושב על כסא כו', וענין [שם] זה דצבאות הוא שם שנעשה<sup data-n=\"5424\">198</sup> שם וכלי מיוחד לגילוי אוא\"ס בבי\"ע אעפ\"י שהן עולמות הנפרדי' ונק' צבאות [ממש] ואמנם ע\"י בחי' גילוי אוא\"ס בצבאות נעשה גם שם [ב]בחי' כלי ושם [כ]שמות דאלקי' ואד' כו' וכמאמר אות הוא בצבא<sup data-n=\"5425\">200</sup> דילי'<sup data-n=\"5426\">199</sup> [כו']. וז\"ש קדוש ה' צבאות שצבאות הוא ה' ממש משום דשם זה דצבאות הוא בבחי' הכלי ושם בפ\"ע בבי\"ע כ[מו] שמות דאצי' ממש, דהגם שיש הרבה שמות למעלה באצי' שמיוחדים בתכלית היחוד דאיהו וחיוהי וגרמוהי חד ממש כנ\"ל, אך הן הנה למעלה ולא נמשך מהן למטה שיהי' גילוי אוא\"ס למטה בבי\"ע כמו באותן שמות וכלים דאצי' בבחי' שם וכלי כאחד מהן [ממש, ולזה הי' כל הנבואה של הנביאים שיהי' בבי\"ע ג\"כ בחי' כלי ושם ביחוד גמור באוא\"ס באחד] מן השמות דאצי' והוא בחי' שם<sup data-n=\"5427\">201</sup> דצבאות שרוב נבואתם הי' ע\"י שם דצבאות, והוא ע\"י דבר ה' שהאיר <span data-k=\"pg\">קמא</span> ּ בפי הנביא שהמשיך מאצי' לבי\"ע להיות בבי\"ע כלי ושם לאוא\"ס כמו באצי' ממש אעפ\"י שהפרסא מפסיק בין אצי' לבריאה כנ\"ל, אבל בזה הי' נבדל מעלת הנבואה שהי' בוקע האור מאצי' לבי\"ע כמו שהוא בל[י] הפסק מסך כו'. וזהו עיקר ענין שם דצבאות שנעשה בשם וכלי לעצמו ע\"י הנביאים ודוקא בתוכחה שלהם לישראל דהיינו [שהזהירו] רק לקיים את התורה בלבד והוא מ\"ש בתורה כבר בלי התחדשות כלל יקיימו בפו\"מ וכו' וד\"ל<sup data-n=\"5428\">202</sup>, וכאשר יקיימו התורה<sup data-n=\"5429\">203</sup> בפו\"מ לא תהי' התורה שמות בפ\"ע כשמות וכלים דאצי', ולא יהיו [בנ\"י] נפרדים מן התורה והתורה לא תהי' נפרדת מהם, אלא אדרבה יהיו בנ\"י בקיום תומ\"צ [בפו\"מ] כמו שהן נשמות בגופים אע\"פ שהן בעוה\"ז הגשמי<sup data-n=\"5430\">204</sup> יהיו ג\"כ בבחי' כלי ושם לאוא\"ס שבתורה, וזהו שם דצבאות שנעשה שם וכלי בבי\"ע. וזהו עיקר התוכחה של הנביאים אעפ\"י שהוא רק לקיום התורה בלבד, דכל עיקר פעולתם אינם רק לקיים את התורה שכבר קבלו שיהי' גילוי אוא\"ס שבתורה גם בכנס\"י למטה בעולם הפירוד כמו [בעולם] היחוד ממש ואין כח זה רק לנביאים [בלבד] מטעם הנ\"ל וד\"ל.",[["5422","196","<b>כמו שם התואר וכלי</b>: יאיב: ליתא."],["5423","197","<b>ישעי' שראה הוי' צבאות</b>: נסמן לעיל פ' וארא פו, ב."],["5424","198","<b>שם שנעשה</b>: יאיב: ליתא."],["5425","200","<b>בצבא דילי'</b>: אויא: בחיילות דילי' [ראה זהר בראשית בהקדמה ו, סע\"א]. יב: בצבאות שלו [ראה גם מאמרי אדה\"א בראשית ע' שלה. שמות שם. נ\"ך ע' רנא. תו\"ח ויצא קסד, ג]."],["5426","199","<b>אות הוא בצבא דילי'</b>: ראה חגיגה טז, רע\"א [לגי' הע\"י]. מאמרי אדה\"א שמות ח\"א ע' רפה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381022\" data-slug=\"likkutei-torah\" data-id=\"4001381022\">לקו\"ת האזינו עד, רע\"ד</a> ובהנסמן במ\"מ לשם. סה\"מ מלוקט ח\"א ע' שעט. וש\"נ."],["5427","201","<b>שם</b>: יאיב: ליתא. או: כבפנים."],["5428","202","<b>וכו' וד\"ל</b>: יאיב: ליתא."],["5429","203","<b>התורה</b>: יאיב: ליתא."],["5430","204","<b>בעוה\"ז הגשמי</b>: יאיב: בעולם הפירוד."]]],[2300540416,"<b>והנה</b> עדיין אין זה מתיישב לנכון, דאם עיקר הטעם הוא רק מצד שענין הנבואה [הוא] שנמשך מאצי' לבריאה כמו שהוא באצי' כו', א\"כ למה אין מדריגת נבואתם רק בנו\"ה דבריאה ונו\"ה דיצי', ומאחר שביכולתם לעשות כלי לשם צבאות<sup data-n=\"5431\">205</sup> דבריאה שוה<sup data-n=\"5432\">206</sup> כא' השמות דאצי', מזה מוכרח שצ\"ל שרש הנביאים באצי' עצמן<sup data-n=\"5433\">207</sup>, וראי' ממה שאומר הנבואה בשם ה' ממש וידוע דשם הוי' הוא באצי'<sup data-n=\"5434\">208</sup> ממש. אלא צ\"ל מטעם אחר והוא לפי שתוכחת מוסר שלהם עשה רושם גדול גם ב[ק\"נ ד]עשי' כמו בלב כ\"א מישראל וגם בגוים לאתהפכא<sup data-n=\"5435\">209</sup> חשוכא לנהורא ממש שהרי היו מתנבאים על כל<sup data-n=\"5436\">210</sup> הגוים ואומות בדבר ה' ממש, וידוע שבחי' לאתהפכא<sup data-n=\"5437\">211</sup> חשוכא לנהורא למטה ממש הנה זה בא מכח העליון ביותר והוא מבחי' סוכ\"ע שהוא אוא\"ס שבאצי' בבחי' מקיף כללי שמקיף לד' עולמות [ד]אבי\"ע [כו'] ושם נאמר גם חשך לא יחשיך ממך<sup data-n=\"5438\">212</sup> וקמי' כחשיכה כאורה כו' ג\"כ בשוה ממש וכמשל הידוע מן העיגול הסובב שאין בו מעלה ומטה<sup data-n=\"5439\">213</sup> [ו]כמ\"ש ומתחת זרועות עולם<sup data-n=\"5440\">214</sup> כו'. וזה הי' ענין הנבואה שהי' דבר ה' בפי הנביא בזה העולם החומרי להפוך חשך דק\"נ לאור<sup data-n=\"5441\">215</sup> משום דזה האור נמשך מאוא\"ס<sup data-n=\"5442\">216</sup> דקמי' כחשיכה [כאורה] כו', ולזה יכולים לעשות כלי ושם ביחוד גמור באוא\"ס גם בעולם הפירוד כמו בעולם היחוד והוא שם דצבאות הנ\"ל וד\"ל. ומ\"מ שרש נבואת[ם] אינו רק בנו\"ה דבריאה ודיצי' כו', אבל בבי\"ע ממשיכים מ[עצמות] אוא\"ס להיות למטה כמו למעלה ממש מטעם זה<sup data-n=\"5443\">217</sup> וד\"ל.\n<b>ובזה</b> יובן מ\"ש במה שמצינו שהעובר ע\"ד הנביא יותר קשה<sup data-n=\"5444\">218</sup> מעובר על מ\"ש בתורה, וזה פלא דאיך אפשר שהדבר שדיבר הנביא בשם ה' יותר עליון מדבר ה' ע\"י משה אחר שאין נביא כו'. אך הענין הוא דהעובר על דברי הנביא שעיקר ענינו [הוא] לעשות כלי ושם דצבאות בכאו\"א מישראל כמו שנשמתו בגופו [כנ\"ל] וא\"כ אם עבר ע\"ד הנביא הי'<sup data-n=\"5445\">219</sup> נפגם נשמתו מהיות בחי' כלי ושם לגילוי אוא\"ס כמו למעלה באצי' ושוב אין לו תיקון כלל <span data-k=\"pg\">284</span> ּ מאחר שפגם בעצמו, אבל העובר על מ\"ש בתורה הגם ש[ה]פגם הוא למעלה באורות ושמות עליונים כמו בל\"ב חוטין דציצית כאשר עבר ע\"ז פגם בל\"ב נתיבות חכ'<sup data-n=\"5446\">220</sup> ופגם [ב]מ\"ע דסוכה לא נמשך המקיפים דסכך וכה\"ג אך לא פגם",[["5431","205","<b>לשם צבאות</b>: יאיב: ושם דצבאות."],["5432","206","<b>שוה</b>: יאיב: שיהי'."],["5433","207","<b>שצ\"ל. . עצמן</b>: יאיב: ששרש הנבואה באצי' עצמו."],["5434","208","<b>דשם הוי' הוא באצי'</b>: ראה זהר (אד\"ר) נשא קכט, א. ת\"ז בהקדמה (יז, א). לקמן שס, א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830208\" data-slug=\"or-hatorah-hb\" data-id=\"8158830208\">אוה\"ת במדבר ע' רח</a>."],["5435","209","<b>לאתהפכא</b>: יאיב: (ו)להפוך."],["5436","210","<b>כל</b>: יאיב: ליתא."],["5437","211","<b>שבבחי' לאתהפכא</b>: יאיב: שזה הכח הגדול לאהפכא."],["5438","212","<b>גם חשך לא יחשיך ממך</b>: תהלים קלט, יב."],["5439","213","<b>העיגול. . מעלה ומטה</b>: נסמן לעיל לח, ד."],["5440","214","<b>ומתחת זרועות עולם</b>: ראה גם לעיל פ' וארא נה, ד. וש\"נ."],["5441","215","<b>חשך דק\"נ לאור</b>: אויאיב: חשוכא (או: ניתוסף: דק\"נ) לנהורא."],["5442","216","<b>מאוא\"ס</b>: יאיב: מעצמות א\"ס שבאצי'."],["5443","217","<b>זה</b>: יאיב: הנ\"ל."],["5444","218","<b>קשה</b>: יב: חמור. אויא: כבפנים."],["5445","219","<b>הי'</b>: יאיב: הרי."],["5446","220","<b>בל\"ב חוטין דציצית. . בל\"ב נתיבות חכ'</b>: נסמן לעיל נו, ב."]]],[2300540436,"בכלי עצמו עדיין [ויש לו תיקון] רק שפגם באו\"כ עליונים, משא\"כ העובר ע\"ד הנביא פגם בעצמו שאין לו תיקון מטעם הנ\"ל וד\"ל.\n<b>ובכל</b> הנ\"ל יובן ענין של<sup data-n=\"5447\">221</sup> בעצם היום הזה יצאו כל צבאות הוי' [צבאות] בחיריק תחת הצדי\"ק וחטף תחת הבי\"ת שמורה ענין טפל לעיקר כנ\"ל, כי בתושב\"כ שהוא בחי' שמות עליונים דאצי' עצמו באו\"כ שכל התורה שמותיו כו' והן שמות דהוי' ואד' ואלקים כולן<sup data-n=\"5448\">222</sup> שכולן בבחי' שם הוי' הפנימי' [ש]מתאחדי' בעצם האור דא\"ס [בכלל ובפרט] כנ\"ל ע\"כ לא נזכר שם זה דצבאות בתשב\"כ בבחי' שם וכלי בפ\"ע, כי שם צבאות הוא בבחי' מל' דאצי'<sup data-n=\"5449\">223</sup> כשהוא מסתתר בעולם הבריאה שנק' צבאות הוי' ושם הוא נעשה [ב]בחי' כלי ושם בפ\"ע כאחד השמות דאצי' בבחי' [שם] התואר, רק נזכר בתורה בבחי' טפל [לשם הוי'] והוא צבאות הוי' ולא שהוי' הוא צבאות ממש כמו קדוש ה' צבאות. אך ע\"י הנביאים שהם עשו [לשם] צבאות לבחי' כלי ושם בפ\"ע מטעם הנ\"ל ע\"כ נז' בנביאים שם דצבאות בבחי' שם וכלי ממש כמו כה אמר ה' צבאות בבחי' שם התואר כנ\"ל (ואז לא<sup data-n=\"5450\">224</sup> יוכל להיות ע\"י משה בחי' כלי ושם דצבאות כא' השמות, אך משה שרש נבואתו<sup data-n=\"5451\">225</sup> בפנימי' אבא שרש האצי' הרי שם דצבאות שהוא בבריאה כאין יחשב ורק [כשבא] שם זה דצבאות [למטה בבי\"ע] נעשה בבחי' שם וכלי בפ\"ע [ד]מה שבאצי' הי' טפל ובטל נעשה שם<sup data-n=\"5452\">226</sup> וכלי בפ\"ע בבריאה (ודוגמא לדבר [ענין] א' זעירא דויקרא<sup data-n=\"5453\">227</sup> דלא ידיעא בשם וכלי<sup data-n=\"5454\">228</sup> כלל כמ\"ש ויקרא אל משה<sup data-n=\"5455\">229</sup> ובד\"ה הוא א' רבתי דאדם<sup data-n=\"5456\">230</sup> [כו'), וכמ\"ש בזהר ע\"פ שחורה אני דאזעירת גרמה<sup data-n=\"5457\">231</sup> ונעשית נקודה חדא באצי' ובירידה בבי\"ע נעשה בבחי' פרצוף] (וזהו שאמר בעצם היום הזה יצאו כל כו'<sup data-n=\"5458\">232</sup> אע\"פ שיצאו בלילה<sup data-n=\"5459\">233</sup> כמ\"ש ליל שמורים הוא הלילה הזה לשון זכר<sup data-n=\"5460\">234</sup> [משום דזהו דומה] כמו לע\"ל דכתי' ולילה כיום יאיר<sup data-n=\"5461\">235</sup> ע\"ד<sup data-n=\"5462\">236</sup> שנק' לילה הזה עצם היום הזה דכולו<sup data-n=\"5463\">237</sup> טוב [כו'] מטעם דגם חשך כו' כנ\"ל). ועוד יש לפרש בפי' צבאות הוי' טפל [ובטל] בערב רב שנתבררו מרפ\"ח<sup data-n=\"5464\">238</sup> [כו'] שנפלו [ב]חטא עה\"ד בנהר נילוס<sup data-n=\"5465\">239</sup>. וזהו [צבאות לשון אסיפה וקיבוץ כמו ויצבאו על מדין<sup data-n=\"5466\">240</sup> ולאחר הבירור שלהם נעשה בבחי' כלי לשם ה'. וזהו שנק'] צבאות בחיריק ע\"ד<sup data-n=\"5467\">241</sup> הביטול וההתכללות ומספר ר\"ב שעלו מרפ\"ח<sup data-n=\"5468\">242</sup> נשאר",[["5447","221","<b>של</b>: יאיב: מ\"ש."],["5448","222","<b>כולן</b>: יאיב: כו'."],["5449","223","<b>צבאות. . מל' דאצי'</b>: ראה אוה\"ת תרומה ע' א'שע שמציין לרע\"מ אמור צג, א."],["5450","224","<b>ואז לא</b>: יאיב: ולא שלא."],["5451","225","<b>משה שרש נבואתו</b>: ראה גם לעיל צח, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061261\" data-slug=\"likkutei-sichot\" data-id=\"1300061261\">לקו\"ש שמות (כרך ו) ע' 251</a> ואילך."],["5452","226","<b>שם</b>: יאיב: יש."],["5453","227","<b>א' זעירא דויקרא</b>: זהר ויחי רלט, א. מצורע נג, ב."],["5454","228","<b>וכלי</b>: יאיב: ליתא."],["5455","229","<b>ויקרא אל משה</b>: ויקרא א, א."],["5456","230","<b>ובד\"ה הוא א' רבתי דאדם</b>: בתחלתו."],["5457","231","<b>שחורה אני דאזעירת גרמה</b>: שה\"ש א, ה. ראה זהר בלק קצא, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תמז."],["5458","232","<b>כו'</b>: יא: צבאות. יב: צבאות הוי' כו'."],["5459","233","<b>אע\"פ שיצאו בלילה</b>: ראה גם פ' ראה טז, א. קרבן העדה לירושלמי פסחים פ\"י, ה\"ה (ד\"ה וכי יצאו). מנחת בכורים לתוספתא פסחים פ\"י, ה\"ו (ד\"ה וכי כבר)."],["5460","234","<b>ליל שמורים הוא. . לשון זכר</b>: בא יב, מ [בדילוג]. נסמן לעיל פח, ב."],["5461","235","<b>ולילה כיום יאיר</b>: תהלים קלט, יב."],["5462","236","<b>ע\"ד</b>: יאיב: עד."],["5463","237","<b>הזה דכולו</b>: יאיב: כולו."],["5464","238","<b>מרפ\"ח</b>: נסמן לעיל לו, ג."],["5465","239","<b>מרפ\"ח. . בנהר נילוס</b>: ראה גם לעיל פ' שמות לט, ג. וש\"נ."],["5466","240","<b>ויצבאו על מדין</b>: מטות לא, ז."],["5467","241","<b>ע\"ד</b>: יאיב: ע\"ש."],["5468","242","<b>ר\"ב שעלו מרפ\"ח</b>: ראה כנפי יונה ח\"ג סנ\"ו. מג\"ע אופן נח. שם עה\"ת (מהדורא תניינא ברוקלין תשל\"ז) ס\"פ מקץ (ע' קפו ד\"ה גם). מאמרים שנסמנו בריש המאמר. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' נג (כידוע בספרים). ח\"ב ע' תתפה. לקמן פ' בשלח קלו, ד."]]],[2300540456,"פ\"ו שהוא גימט'<sup data-n=\"5469\">244</sup> שם אלקים<sup data-n=\"5470\">243</sup> שצריך בירור בגל[י]ות, ועל מספר ר\"ב דערב רב שעלו עם משה נק' צבאות הוי' [כ]דוגמא דלע\"ל דנהרו אליו כל הגוים<sup data-n=\"5471\">245</sup> [כו']. אבל בנ\"י<sup data-n=\"5472\">246</sup> שעלו עם משה עצמו<sup data-n=\"5473\">247</sup> שחלק ה' עמו<sup data-n=\"5474\">248</sup> כמ\"ש כי חלק ה' עמו<sup data-n=\"5475\">249</sup> כו' עליהם אמר אח\"כ ויהי בעצם היום הזה הוציא הוי' עצמו את בנ\"י [בעצמם כו'] על צבאותם<sup data-n=\"5476\">250</sup> למעלה מבחי' צבאות הוי', ששם זה דצבאות אינו אלא למטה בבי\"ע כנ\"ל וד\"ל. [כמ\"ש מי הוא זה מלך הכבוד<sup data-n=\"5477\">251</sup> שיורד מאצי' לבי\"ע להיות מלך על עם נפרד ה' צבאות הוא מלך כו'.] וז\"ש ויעש דוד שם<sup data-n=\"5478\">252</sup> שהוא שם דצבאות שבא לברר לרפ\"ח כו', ולע\"ל [א'] יתעלה שם זה למעלה מעלה [ו]כמ\"ש אבן מאסו הבונים<sup data-n=\"5479\">253</sup> [כו'] א' ב\"ן<sup data-n=\"5480\">254</sup> [כו'] והוא האבן הראשה<sup data-n=\"5481\">255</sup> [כו'] דזרובבל [כו'], וזהו שזכרי' ניבא [רק] בשם הוי' צבאות מפני שהי' נבואתו<sup data-n=\"5482\">256</sup> במשיח וגם בכל נב[ו]אות שלו כה א' ה' צבאות (עיין בו עד סי' ט\"ו<sup data-n=\"5483\">257</sup> ) בעז\"ה<sup data-n=\"5484\">258</sup>.",[["5469","244","<b>גימט'</b>: יאיב: ליתא."],["5470","243","<b>פ\"ו. . שם אלקים</b>: ראה בהערה שלפנ\"ז. ע\"ח (שער המוחין) ש\"כ, פ\"א."],["5471","245","<b>דנהרו אליו כל הגוים</b>: ישעי' ב, ב."],["5472","246","<b>בנ\"י</b>: יא: כנס\"י."],["5473","247","<b>שעלו עם משה עצמו</b>: או: עצמן. יאיב: עצמן הן."],["5474","248","<b>שחלק ה' עמו</b>: או: שחלק הוי' (עמו) עצמו הן. יאיב: ליתא."],["5475","249","<b>כי חלק ה' עמו</b>: האזינו לב, ט."],["5476","250","<b>ויהי בעצם. . על צבאותם</b>: בא יב, נא."],["5477","251","<b>מי הוא זה מלך הכבוד</b>: תהלים כד, י."],["5478","252","<b>ויעש דוד שם</b>: שמואל-ב ח, יג."],["5479","253","<b>אבן מאסו הבונים</b>: תהלים קיח, כב."],["5480","254","<b>אבן. . א' ב\"ן</b>: ראה מאו\"א מערכת אבן, ס\"ד. שעהיחוה\"א פ\"ז (פד, ב) ובליקוט פירושים לשם. סידור שער התפלה כא, סע\"ג. מאמרי אדה\"א דברים ח\"ב ע' תמא. וש\"נ. ראה הערה הבאה."],["5481","255","<b>האבן הראשה</b>: זכרי' ד, ז. אויאיב: אבן. ראה לקמן פ' בשלח קפג, ג. רלג, ד. ויקהל תב, ד. מאמרי אדה\"א שמות ח\"א ע' צב."],["5482","256","<b>שהי' נבואתו</b>: יאיב: שהוא מדבר."],["5483","257","<b>ט\"ו</b>: אויב: ט."],["5484","258","<b>בעז\"ה</b>: אויב: וד\"ל. יא: ליתא."]]],[2300540064,"<b>ב\"ה תורות מה ששמעתי אדמו\"ר שליט\"א פ\"ק ליבאוויץ </b>\nבחג הפסח תקפ\"ה לפ\"ק\n<span data-k=\"pg\">קמב</span> ּ<b>והי'</b> כי יביאך<sup data-n=\"5485\">1</sup> אל ארץ<sup data-n=\"5486\">2</sup> כו' ז' ימים תאכל מצות<sup data-n=\"5487\">3</sup> כו' עד מצות יאכל<sup data-n=\"5488\">4</sup> כו', להבין שרש ענין פסח ומצה<sup data-n=\"5489\">5</sup>, הנה ידוע בס' הקבלה בשרש ענין המצה שהוא בחי' קטנות דאבא<sup data-n=\"5490\">6</sup>, וי\"ל דאם הכוונה בבחי'<sup data-n=\"5491\">7</sup> קטנות זו דאור אבא הוא בחי' נה\"י שלו הרי זהו כמו בחי' נה\"י דאבא שמלובשים באימא שזהו ענין המועדים שנק' מקראי קדש<sup data-n=\"5492\">8</sup> וה\"ז ג\"כ ענין יו\"ט דפסח וא\"כ מהו ענין המצה. אלא הענין הוא דבחי' קטנות זו היא למטה גם מנה\"י שהרי אומרים ה\"א לחמ\"א עני\"א ד\"י<sup data-n=\"5493\">9</sup> בחי' נקו' תח\"י כו', אך יש בו יתרון מעלה הרבה שמלובש בזה מעצמות ומהות דאור אבא",[["5485","1","<b>והי' כי יביאך</b>: חלקו הראשון של המאמר מיוסד על ביאורי הזהר תזריע עב, א ואילך ומקבילו במאמרי אדה\"ז תקס\"ה ח\"א ע' תכג. וראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקלד ואילך וע' תקלו ואילך. ד\"ה להבין שרש ענין פסח ומצה, יודפס בעז\"ה בפלח הרמון ויקרא. וחלקו השני [קכ, א] מיוסד על ד\"ה והגדת לבנך שנדפס בסידור סדר הגדה (רצו, ג ואילך). והנחת הר\"מ בן כ\"ק אדה\"ז במאמרי אדה\"ז תקס\"ה ח\"א ע' תלה ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380122\" data-slug=\"likkutei-torah\" data-id=\"4001380122\">לקו\"ת צו יא, סע\"ג</a> ואילך. ומע' קכה, ד מיוסד על ד\"ה עבדים היינו שנדפס בסידור שם רצג, ג. ונו\"א במאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקיג. ראה עוד ע\"ד המאמר, וכן ע\"ד התחלת המאמר שברוב הכת\"י הוא ”לה\"ע שרש פסח ומצה\", להלן ברשימות הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["5486","2","<b>והי' כי יביאך אל ארץ</b>: בא יג, ה [בדילוג]."],["5487","3","<b>ז' ימים תאכל מצות</b>: בא שם, ו."],["5488","4","<b>מצות יאכל</b>: שם יג, ז."],["5489","5","<b>להבין שרש ענין פסח ומצה</b>: כ\"ה ההתחלה ברוב הכת\"י — ראה להלן ברשימת הכת\"י."],["5490","6","<b>המצה. . קטנות דאבא</b>: נסמן לעיל צד, ד."],["5491","7","<b>בבחי'</b>: ידיט: בפי'."],["5492","8","<b>המועדים שנק' מקראי קדש</b>: אמור כג, ב. ד. לז. סידור שער המועדים ריז, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380124\" data-slug=\"likkutei-torah\" data-id=\"4001380124\">לקו\"ת צו יב, א</a>. ידיט: מקרא קדש — בא יב, טז. אמור כג, ז ואילך."],["5493","9","<b>ה\"א לחמ\"א עני\"א ד\"י</b>: נסמן לעיל קא, ב."]]],[2300540102,"מבחי' ג\"ר שבו שאינו מלובש באור אימא כלל [וכלל]. וביאור הענין, הנה ידוע בכללות ענין ההפרש בין מוחין דאבא למוחי' דאימא<sup data-n=\"5494\">10</sup> שזהו בחי' רו\"ש שהמה ב' הפכים כאש ומים ממש, שההתפעלו' ברשפי אש [התשוקה] הנולד בלב מבינה שנק' אימא<sup data-n=\"5495\">11</sup> שהיא ההרגשה<sup data-n=\"5496\">12</sup> והקליטה במוח בינה בהסבר הדבר הוא בחי' רצוא וצריך שיהי' בחי' ביטול התשוקה וביטול ההשגה בתחלה כענין מה פשפשת<sup data-n=\"5497\">13</sup> כו', אז יומשך בחי' אור אבא שהוא [בחי'] ראיית השכל שהוא למעלה הרבה מן ההשגה והבנה כידוע בענין אינו דומה שמיעה לראי'<sup data-n=\"5498\">14</sup> כו', כי כשרוא[ה] פני המלך מתבטל בביטול עצמי שלמעלה מן השגה וטעם לגמרי והוא בחי' שוב כמאמר אם רץ לבך שוב<sup data-n=\"5499\">15</sup> כו', שאחר הרצוא ע\"י [ה]השגה שוב [ב]בחי' ביטול דראי' דחכ', והוא ענין תשו\"ע תשוב ה'<sup data-n=\"5500\">16</sup> דבחי' רצוא דבינה ליכלל באור אבא בבחי' שוב שזהו היפוך בחי' הרצוא עצמו לבחי' שוב דהיינו שתשוב רשפי אש התשוקה שבלב ומוח בינה להיות בבחי' ביטול דחכ' כו', ובזה נתקן בחי' גבורות דאימא ונמתקו בחסדים דאבא ויוכל לבא בה השפעת אור אבא (עד\"מ [ב]תשוקת הנוק' לגבי דכורא קודם היחוד וכאשר מקבלת השפע אתבסמת נוק'<sup data-n=\"5501\">17</sup> ונופל התשוקה<sup data-n=\"5502\">18</sup> (וגם בשעה שצריך המקבל לקבל השפע מוכרח שיעצור בעצמו רשפי אש התשוקה כי אם יהי' בהתגברות תשוקתו<sup data-n=\"5503\">19</sup> ברשפי אש ביותר לא יוכל להתקבל בו השפע של המשפיע), וז\"ש ההופכי הצור אגם מים<sup data-n=\"5504\">20</sup> כו' דמ\"ן דנוק' שהי' בבחי' גבו' דאש נהפך למי החסדי' כו'. אבל אם אין תיקון ומיתוק הגבו' דאש דרצוא להתהפך לשוב אלא הי' הכל בבחי' רצוא הי'<sup data-n=\"5505\">21</sup> מסתעף מזה ב' דברים א' שאין האור השפע דחסדי' דנה\"י דאבא מתקבל בבינה כלל, וממילא יסתעף שיסתלק אור התפעלות ההשגה דבינה לבא<sup data-n=\"5506\">22</sup> הנ\"ל ויפול הנופל בבחי' גבורות קשות דאש זרה היפוך המנגד לגבו' דקדושה (והיינו פר\"ש חגיכ\"ם<sup data-n=\"5507\">23</sup> שהחג הוא התלהבות<sup data-n=\"5508\">24</sup> השמחה [ב]רצוא דהשגה דבינה וכשאין נמתקין",[["5494","10","<b>ההפרש בין מוחין דאבא למוחי' דאימא</b>: ראה ביאוה\"ז תזריע עב, א. מאמרי אדה\"ז תקס\"ה ח\"א ע' תכג."],["5495","11","<b>מבינה שנק' אימא</b>: ראה זהר (אד\"ז) האזינו רצ, א. ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ה. מאמרי אדה\"א בראשית ע' א. וש\"נ."],["5496","12","<b>ההרגשה</b>: ידיט: ההשגה."],["5497","13","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["5498","14","<b>אינו דומה שמיעה לראי'</b>: נסמן לעיל פ' שמות כב, ב."],["5499","15","<b>אם רץ לבך שוב</b>: נסמן לקמן פ' בשלח קסד, ג."],["5500","16","<b>תשו\"ע תשוב ה'</b>: ראה זהר (רע\"מ) נשא קכב, א."],["5501","17","<b>אתבסמת נוק'</b>: ראה זהר לך צד, א."],["5502","18","<b>התשוקה</b>: הט: התשוקה)."],["5503","19","<b>התשוקה. . תשוקתו</b>: ידיט: תשוקתו. . התשוקה."],["5504","20","<b>ההופכי הצור אגם מים</b>: תהלים קיד, ח. ראה גם שה\"א ק, ב."],["5505","21","<b>הי'</b>: ידיט: ליתא."],["5506","22","<b>דבינה לבא</b>: ת\"ז בהקדמה (יז, א)."],["5507","23","<b>פר\"ש חגיכ\"ם</b>: נסמן לקמן קכ, ג."],["5508","24","<b>שהחג הוא התלהבות</b>: נסמן לעיל קג, ב."]]],[2300540140,"בבחי' השוב דביטול [ד]אבא נמשך יניקה<sup data-n=\"5509\">25</sup> לחיצונים כמ\"ש במ\"א) (וכן אנו רואים בחוש בכל מי שטעם טעם בעבודת ה' במוח ולב ברשפי אש התשוקה שנק' שלהבת י\"ה<sup data-n=\"5510\">26</sup> ממש שאם לא יבא לכלל ביטול דבחי' שוב בשפלות עצמו עד שיבוטל התלהבות שלו כמו וירא העם וינועו<sup data-n=\"5511\">27</sup> כו', אזי יפול מיד בגסות והגבהת הלב ובהמשכת חום תאוות רעות כו' וד\"ל). וכמו\"כ מן המשפיע אל המקבל צ\"ל בבחי' קרירות וביטול היפוך התפעלו' רשפי אש, כמו שאנו רואים בכל משפיע שכל או מוסר לתלמיד שכאשר ידבר בהתפעלות <span data-k=\"pg\">286</span> ּ רשפי אש בקול רם לא יוכל להתקבל לנכון רק כשמדבר בנחת [דוקא] כמ\"ש חכ\"ם באחו\"ר ישבחנ\"ה<sup data-n=\"5512\">28</sup> בבחי' אחוריים<sup data-n=\"5513\">29</sup> יבא למקבל בבחי' תיקון ושלימות הקבלה, וכן אמר דברי חכמים בנחת נשמעים<sup data-n=\"5514\">30</sup> בנחת דוקא נשמעים ומתקבל[ים] למקבל. ואע\"פ שדברים היוצאים מן הלב<sup data-n=\"5515\">31</sup> דוקא נכנסים בלב המקבל, היינו להיות התפעלות הלב אבל להתקבל במוח בינה דבר חכ' דוקא בנחת נשמעים, וגם מוסר ברך יקבל יותר מבקשה ולפעמים בקשה יותר כדי לעשות בו כלי כו' (ובמ\"ת שהי' בו קולות וברקים<sup data-n=\"5516\">32</sup>, זה הי' לעשות בהם בחי' הביטול להיות כלי קיבול). והנה כ\"ז הוא בחי' נה\"י דאבא שנמשך בבחי' יחוד דאו\"א שהוא בכל יו\"ט שאין ההשפעה רק מבחי' נה\"י דאבא בשביל מוחין דאימא שנק' מקרא קדש שזהו ע\"י ביטול הרצוא [ל]שוב כנ\"ל, אבל ענין בחי' קטנות דאבא שהוא בחי' מצה הגם שבא בקטנות הרבה יותר, אבל זהו ממהו\"ע דאבא כנ\"ל.\n<b>והענין</b> הוא כידוע שהמשל בזה הוא ממ\"ש אין התינוק יודע לקרות<sup data-n=\"5517\">33</sup> אבא ואימא עד שיטעום טעם דגן דייקא, וידוע ענין מה שהתינוק יודע לקרות אבא כו' ידיעה זו אינה אצלו בדרך ידיע[ת] שכל וטעם כלל שהרי אינו משכיל ומבין בדעתו איך שהוא אביו בתולדה, וגם איך שזנו ומפרנסו ומלבישו כו' וכה\"ג, רק שעכ\"ז קוראו אבא בלא טעם ודעת כלל שממילא ומעצמו קוראו בל' זה מפני שהוא בא מצד טבע התולדה בעצם שלמעלה מן הטעם לגמרי, עד [ש]גם כשיגדל בשנים וקוראו אבא מצד השכל וטעם שמבין איך שהוא אביו בתולדה כו' אין זה עיקר בקריאה זאת רק טפל, כי העיקר הוא מצד עצם טבע הבן שנמשך אחר אביו ואמו המולידים אותו וע\"כ שוה אצלו קריאה זו בקטנות[ו] כמו בגדלותו ממש להיות שקריאה זו בלשונו ה[י]א רק ההכרה והרגשה שמכיר ומרגיש בעצמו מטבעו<sup data-n=\"5518\">34</sup> שהוא אביו כו' וע\"כ הוא נמשך אחריו דוקא ולא לאחר זולתו שלא יקראנו",[["5509","25","<b>דבינה. . יניקה</b>: ראה גם סידור שם ר, ב ואילך."],["5510","26","<b>שלהבת י\"ה</b>: שה\"ש ח, ו."],["5511","27","<b>וירא העם וינועו</b>: יתרו כ, טו."],["5512","28","<b>חכ\"ם באחו\"ר ישבחנ\"ה</b>: משלי כט, יא [ושם: וחכם — ראה לקמן קכד, ד. מאמרי אדה\"א דברים ח\"ד ע' א'רפ. וש\"נ]."],["5513","29","<b>ישבחנה בבחי' אחוריים</b>: ידיט: בבחי' אחוריים ישבחנה."],["5514","30","<b>דברי חכמים בנחת נשמעים</b>: קהלת ט, יז."],["5515","31","<b>שדברים היוצאים מן הלב</b>: ראה של\"ה שער האותיות אות כ (סט, א). שה\"א פה, א הערה 2."],["5516","32","<b>ובמ\"ת. . קולות וברקים</b>: יתרו יט, טז. ראה מאמרי אדה\"ז תקס\"ט ע' קמה. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370315\" data-slug=\"torah-or\" data-id=\"3901370315\">תו\"א יתרו ע, ד</a> (ובמ\"מ לשם הערה בטול). מאמרי אדה\"א דברים ח\"א ע' קמג. ח\"ד ע' א'תקכא ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470342\" data-slug=\"or-hatorah-hb\" data-id=\"8316470342\">אוה\"ת יתרו ע' תתטו</a> (ד\"ה כי תשא). לקמן פ' בשלח רכז, א."],["5517","33","<b>אין התינוק יודע לקרות</b>: ראה גם לעיל צה, ב. וש\"נ."],["5518","34","<b>בעצמו מטבעו</b>: ידיט: מעצמו וטבעו."]]],[2300540177,"אבא כו', כי כל דבר נמשך לשרשו<sup data-n=\"5519\">35</sup> ומקורו דווקא מצד עצם הדבר כמו שהוא ממש ומה ש[י]שכיל ויבין בזה מצד הידיעה בשכל שהוא אביו המולידו אינו רק כמוסיף על עצם הדבר (שיבוטל כשלא ייטיב עמדו וכה\"ג), אבל מה שהוא מצד העצם בלתי הרכבה בטעם ושכל לא יבוטל לעולם שכל עצם אינו משתנה<sup data-n=\"5520\">36</sup> [כלל כידוע)]. ונמצא מה שהוא יודע ומכיר את אביו לקרות[ו] אבא ונמשך אחריו אע\"פ שאינו רק בחי' קריאה בעלמא הרי בזה מלובש כל בחי' עצמ[ו]' השפע דאביו שיש בטבע התולדה שהולידו מכחו וראשית אונו<sup data-n=\"5521\">37</sup> כו' שלמעלה הרבה מן השכל ו[ה]טעם שמשכיל ומבין בזה עצמו אחר שיגדל כו', רק שבא בהתלבשות והעלם ביותר בקריאה והמשכה שנמשך אחריו וקוראו אבא שהוא בבחי' הכרה בלבד, אבל בזה מלובש מעצם הדבר ממש כמו שהוא כח עצם התולדה שמעצמות אביו כו'. ואין זה כמו שפע שכל מרב לתלמיד וכעשיר לעני כו' וכה\"ג, שנק' שפע דעילה לעלול שאינו בא מעצמות המשפיע רק ע\"י צמצום עצמותו ממש כידוע שהוא בחי' נה\"י שבו כו' [שאין העלאה דמקבל מגיע רק לחיצוני' שפע זו דמשפיע ולא לעצמות ומהות המשפיע כלל. משא\"כ קריאה והמשכה זאת דתינוק לאביו ואמו שמלובש בזה מעצמות דאביו ואמו<sup data-n=\"5522\">38</sup> ] דווקא אע\"פ שאינו בא מצד השכל וטעם כלל ולא בהתפעלות הלב רק קריאה והכרה לבד וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למשכיל בענין שרש המצה שנק' בחי' קטנות דאור אבא שהוא מה שאו' אבינו כו' וכמ\"ש כי אתה אבינו<sup data-n=\"5523\">39</sup> וכה\"ג, וכמו שהי' [בישראל בהיותם] במצרים שלא הי' בהם <span data-k=\"pg\">קמג</span> ּ רק בחי' ההכרה שהכירו את בוראם כי הוא אבינו כו' כתינוק שנמשך אחר אביו מפני ההכרה לבד ע\"כ קוראו אבא ולא לזולתו וכמ\"ש זכרתי לך חסד נעורייך<sup data-n=\"5524\">40</sup> דוקא לכתך אחרי במדבר<sup data-n=\"5525\">41</sup> בלא טעם ושכל כלל ולכן נא'<sup data-n=\"5526\">42</sup> כי נער ישראל ואוהבהו<sup data-n=\"5527\">43</sup> כו'. וכמו שאין התינוק יודע לקרות או\"א עד שיטעום [טעם] כו', כך הוא ענין המצה שאכלו אבותינו במצרים כמ\"ש ה\"א לחמ\"א עני\"א ד\"י [אכל\"ו] כו' עני מן הדעת<sup data-n=\"5528\">44</sup> כמו שאין במצה שום טעם כלל כידוע. אך יש בזה דוקא התלבשות מעצמות כח התולדה דאב כנ\"ל ולהכיר את בוראו לקרות אבא<sup data-n=\"5529\">46</sup> מצד שהוא<sup data-n=\"5530\">45</sup> שרש ומקור תולדות נש\"י מפנימית אור אבא דאצי' כמ\"ש כי אתה אבינו כו' וכמ\"ש בנים אתם לה' אלקיכם<sup data-n=\"5531\">47</sup> כו' ואו' בני בכורי ישראל<sup data-n=\"5532\">48</sup> [כו'], כמו הבן שנולד מטפה שבמוח האב<sup data-n=\"5533\">49</sup> שהוא",[["5519","35","<b>כל דבר נמשך לשרשו</b>: נסמן לעיל צה, ב."],["5520","36","<b>שכל עצם אינו משתנה</b>: נסמן לעיל פ' וארא עח, ב."],["5521","37","<b>מכחו וראשית אונו</b>: ע\"פ ויחי מט, ג־ תצא כא, יז [בבן בכור]."],["5522","38","<b>שאין. . ואמו</b>: בתו\"ח כאן: שעי\"ז העלאת דמקבל בזה בעצמות דאו\"א."],["5523","39","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["5524","40","<b>זכרתי לך חסד נעורייך</b>: ירמי' ב, ב."],["5525","41","<b>במדבר</b>: ידיט: כו'."],["5526","42","<b>ולכן נא'</b>: ידיט: וכן א'."],["5527","43","<b>כי נער ישראל ואוהבהו</b>: הושע יא, א."],["5528","44","<b>עני מן הדעת</b>: ראה כתובות סח, א. נדרים מא, א."],["5529","46","<b>ולהכיר. . אבא</b>: גחיא-ביגיד: ליתא. וראה בסמוך הערה 50."],["5530","45","<b>כנ\"ל. . שהוא</b>: בוזטיאיבטויחיטכ: שהולידו מכחו וראשית אונו כנ\"ל במשל שזהו. אטזיז: כבפנים. דא-בה: חסר. וראה לקמן הערה 50."],["5531","47","<b>בנים. . אלקיכם</b>: פ' ראה יד, א."],["5532","48","<b>בני בכורי ישראל</b>: שמות ד, כב."],["5533","49","<b>הבן שנולד מטפה שבמוח האב</b>: ראה ת\"ז תי\"ח (לה, א). ראשית חכמה (שער הקדושה) ש\"ד, פ\"א (קכח, רע\"א). תניא פ\"ב. מכתב ב' סיון תשכ\"ד נדפס בכפר חב\"ד גליון 834 ע' 69."]]],[2300540214,"מעצמותו ממש, וע\"כ יש בטבע כ\"א מישראל לימשך אחר ה' שהולידו מכחו וראשית אונו כנ\"ל במשל שזהו<sup data-n=\"5534\">50</sup> לקרותו<sup data-n=\"5535\">51</sup> אבא כו' בלי שום טעם והתבוננות בהשגה כלל מצד שהוא<sup data-n=\"5536\">52</sup> למעלה מכל אשר ישיג בהשגה והתבוננות איך שהוא ית' מקורא דכולא<sup data-n=\"5537\">53</sup> כו', שאין זה מצד עצם אלקות רק בחי' אור השפעתו שבא בסדר השתלשלו' עו\"ע דחו\"ב ומדות<sup data-n=\"5538\">54</sup> כו' שהוא רק מבחי' נה\"י דאו\"א [בזו\"נ] כידוע בשרש ענין מע\"ב. וזהו שהמצה נק' קטנות דאבא שיש בה בהעלם והתלבשות מעצמות ומהות דאבא שהוא בחי' ג\"ר שבו כנ\"ל וד\"ל (וכל אשר יבא לבחי' השגה אלקית בגדלות המוחין אינו רק כמוסיף על העצם בבחי' הרכבה שיבוטל מאיזה סיבה אבל<sup data-n=\"5539\">55</sup> העצם אינו משתנה כלל כנ\"ל וד\"ל).\n<b>וזהו</b> הטעם שנק' המצה בזהר בשם מיכלא דמהימנותא<sup data-n=\"5540\">56</sup> דוקא, כי הנה המצה אין בה טעם מורגש כלל וגם אינה באה בניפוח והגבהה כלל מצד שאין בה שאור המחמ[י]ץ כידוע. וכך הוא ענין האמונה שה[י]א בלא טעם ושכל [כלל] ובלא התפעלות מורגשת בלב כלל רק מצד האמונה [שהוא] כמו אומן [את] היונק<sup data-n=\"5541\">57</sup>, שהתינוק נמשך אחר האומ[נת] שלו בלא טו\"ד כלל וכמ\"ש במ\"א בפי' אמונה מלשון אומן<sup data-n=\"5542\">58</sup> וכמ\"ש ויהי אומן את הדסה<sup data-n=\"5543\">59</sup> כו'. וז\"ש וארשתיך לי באמונה<sup data-n=\"5544\">60</sup> שזה הי' ביצ\"מ שיצאו בבחי' האמונה לבד כמ\"ש ויאמן העם<sup data-n=\"5545\">61</sup> כו' שהי' בהם ירושה מאבותיהם<sup data-n=\"5546\">62</sup> והוא אברהם<sup data-n=\"5547\">63</sup> אבינו ע\"ה שהי' המאמין הראשון<sup data-n=\"5548\">64</sup> כו'. וע\"כ נק' המצה מיכלא דמהימנותא מאכל שזן ומפרנס לחזק כח האמונה שה[י]א כמו טבעי' בנפש כאו\"א מישראל להתמשך אחר[י] ה' למעלה מן הטו\"ד [ובלא] התפעלות הלב כלל כמצה זו שאין בה טעם ולא התנשאות והגבהה כלל וע\"כ נק' לחם עוני כו'. וזהו ה\"א לחמא עניא די אכלו כו' בחי' נקוד[ה] ת\"י שה[י]א בחי' קטנות דנה\"י דאבא שיש בה בהעלם מעצמות דאור אבא שלמעלה גם מהמשכות דאבא באימא מנה\"י שבו כנ\"ל, וא\"כ המצה בשרשה למעלה ממוחין דאימא (וז\"ש חכם מה הוא אומר<sup data-n=\"5549\">65</sup> מה העדות והחוקים<sup data-n=\"5550\">66</sup> כו' כמשי\"ת). ולפ\"ז הרי יובן שהמצה למעלה הוא בעצם <span data-k=\"pg\">288</span> ּ כ\"ח מ\"ה דחכמה<sup data-n=\"5551\">67</sup> [שלמעלה משפע דחכ'] בבינה מאין ליש שהוא רק בחי' רו\"ש הנ\"ל, דהנה מבואר למעלה בענין רו\"ש שהרצוא במדות שבלב באה רק מצד השכל בהתפעלות במוח בינה וגם הוא [נ]תבטל לגבי בחי' הראי' דחכ' שהוא בחי' שוב כנ\"ל, אמנם כ\"ז אינו מגיע לבחי' העצמות ממש, משא\"כ הבן בהגיעו אל אביו שנמשך אחריו מצד עצם התולדה",[["5534","50","<b>שהולידו. . שזהו</b>: בוזטיאיבידטויחיטכ: ולהכיר את בוראו. אגחיא-ביגטזיז: כבפנים. וראה הערה 45-46. 52."],["5535","51","<b>שזהו לקרותו</b>: ביח: ולקרות. גוחיא-ביג: ולקרותו."],["5536","52","<b>שהוא</b>: יד: שהולידו מכחו וראשית אונו כנ\"ל במשל שזהו. וראה לעיל הערה 45."],["5537","53","<b>מקורא דכולא</b>: זהר בראשית לג, א."],["5538","54","<b>ומדות</b>: בכ: במדות. ח: ליתא. יאיב: למדות."],["5539","55","<b>השגה אלקית. . אבל</b>: ז: ליתא."],["5540","56","<b>המצה. . מיכלא דמהימנותא</b>: נסמן לעיל צב, א."],["5541","57","<b>אומן [את] היונק</b>: בהעלותך יא, יב."],["5542","58","<b>אמונה מלשון אומן</b>: ראה גם מאמרי אדה\"א קונטרסים ע' כח. וש\"נ. לקמן פ' תשא שפא, ב."],["5543","59","<b>ויהי אומן את הדסה</b>: אסתר ב, ז."],["5544","60","<b>וארשתיך לי באמונה</b>: הושע ב, כב."],["5545","61","<b>ויאמן העם</b>: שמות ד, לא. ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' שפא. מאמרי אדה\"א שמות ח\"ב ע' תמח."],["5546","62","<b>ירושה מאבותיהם</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא</a> פי\"ח ופל\"ג. מאמרי אדה\"א נ\"ך ע' כח. וש\"נ. שה\"א ו, א ובהערה 13."],["5547","63","<b>ירושה. . אברהם</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670513\" data-slug=\"torat-chaim\" data-id=\"2300670513\">תו\"ח וירא קו, ד</a>. מאמרי אדה\"א נ\"ך שם. לקמן פ' תצוה שיח, ג."],["5548","64","<b>אברהם. . המאמין הראשון</b>: ראה שמו\"ר פכ\"ג, ה. שהש\"ר פ\"ד, ח ג."],["5549","65","<b>חכם מה הוא אומר</b>: נוסח ההגדה."],["5550","66","<b>מה העדות והחוקים</b>: ואתחנן ו, כ."],["5551","67","<b>כ\"ח מ\"ה דחכמה</b>: זהר (רע\"מ) צו כח, א. לד, א."]]],[2300540246,"כנ\"ל וכמו בחי' האמונה אעפ\"י שאין בה התפעלות רצוא שמצד השגה האלקי' כלל ואין בזה התנשאות והגבהת הלב כלל עכ\"ז נמשך בכל נפשו [ממ]ש מצד ההכרה בעצם כלל<sup data-n=\"5552\">68</sup> כנ\"ל. וזהו ענין המצה שאין בה טעם והגבהה כ[נ\"]ל להיות[ה] למעלה הרבה מבחי' הטעם והשגה שהוא בחי' מוחין דאימא שהוא בחי'<sup data-n=\"5553\">69</sup> הרצוא הנ\"ל וד\"ל.\n<b>(וגם</b> למעלה מבחי' אין דחכמה שנמשך לבינה בדרך עו\"ע ביו\"ט וגם בשבת שהוא בחי' מוחין דאבא<sup data-n=\"5554\">70</sup> עצמו שנק' קדש שאין כ\"ז רק בחיצוני' שפע [הנמשך] מעצמות המאציל בדרך עו\"ע, ולפי\"ז הרי יש יתרון מעלה ליו\"ט דפסח גם על [ה]שבת כידוע בטעם שנק' פסח מל' דילוג<sup data-n=\"5555\">71</sup> כמ\"ש ופס\"ח ה' ע\"ל הפת\"ח<sup data-n=\"5556\">72</sup> כמשי\"ת), ולפי\"ז הרי מובן עכ\"פ שאין במצה מבחי' מוחין דאימא כלל רק מבחי' עצמות ומהות דאור אבא דוקא כנ\"ל וד\"ל. והנה מזה הטעם יובן מה שנאסר החמץ בפסח כמ\"ש כל מחמצת<sup data-n=\"5557\">73</sup> לא תאכלו<sup data-n=\"5558\">74</sup> להיות שעיקר ענין יצ\"מ הי' בבחי' האמונה שהיא ההכרה וההמשכה מצד העצם כנ\"ל שהוא מבחי' המשכה דעצמות אור אבא מבלי העלאה דרצוא כלל, אדרבה בחי' העלאה דרצוא היא בחי' המנגד לביטול [זה] העצ[מי] דאמונה והכרה בלא טעם והתפעלות מורגשת רק כתינוק שקורא אבא כנ\"ל, לפי שהתפעלות זו דרצוא הוא בחי' יש מי שמשיג ויש מי שמתפעל ועולה בבחי' העלאה למעלה שהוא ענין ההתנשאות והגבהה בגסות היפוך הביטול ושפלות דבחי' שוב דקטנות דאבא כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן ג\"כ ענין הטעם שנק' פסח ע\"ש שפסח ה' על הפתח כו' שהוא ענין הדילוג הגדול מגבוה לנמוך כמו ענין מדלג על ההרים<sup data-n=\"5559\">75</sup> כו' כידוע, דהנה כנס\"י היו בזמן הגלות דמצרים בבחי' הקטנות מאד כתינוק הנולד באמו<sup data-n=\"5560\">76</sup> שהי' בעיבור במעי אמו ראשו בין ברכיו<sup data-n=\"5561\">77</sup> עיניו סתומים<sup data-n=\"5562\">78</sup> כו' ומשנולד נפתחו עיניו כו' וכמ\"ש ואראך מתבוססת בדמיך<sup data-n=\"5563\">79</sup> כו', והוא ענין בחי' קטנות דאמונה פשוטה והכרה עצמי' הנ\"ל, שלא הי' בהם כח להשיג השגות אלקות בבחי' מוחין דאימא ולהתפעל במדות שבלב שנק' רצוא שנמשך מחמת התבוננות כו', רק אמונה פשוטה והכרה עצמי' שבלא טו\"ד. וע\"כ לא הי' אפשר שיומשך בהם האור [ה]אלקי העליון בסדר ההשתלשלו' עו\"ע כמו מחכ' לבינה ומדות כו' אחר שלא הי' בהם העלאה דבינה [ל]בא מצד",[["5552","68","<b>כלל</b>: ידיט: ליתא."],["5553","69","<b>שהוא בחי'</b>: ידיט: כשהיא בבחי'."],["5554","70","<b>בשבת. . מוחין דאבא</b>: ראה שע\"ת צח, ב בשם הע\"ח. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מד."],["5555","71","<b>פסח מל' דילוג</b>: נסמן לעיל פז, א."],["5556","72","<b>ופס\"ח ה' ע\"ל הפת\"ח</b>: בא יב, כג."],["5557","73","<b>כל מחמצת</b>: בא יב, כ."],["5558","74","<b>לא תאכלו</b>: ידטו: כו'."],["5559","75","<b>מדלג על ההרים</b>: ראה בסמוך בפנים."],["5560","76","<b>באמו</b>: ביד: ביומו."],["5561","77","<b>ראשו בין ברכיו</b>: נדה ל, ב."],["5562","78","<b>עיניו סתומים</b>: נסמן לעיל פ' וארא סו, ד."],["5563","79","<b>ואראך מתבוססת בדמיך</b>: יחזקאל טז, ו."]]],[2300540277,"בחי' הקטנות שלהם, א[ך] אדרבה היא הנותנת שנמשך אליהם האור מבחי' מהו\"ע א\"ס ב\"ה שבפנימי' ועצמות דאור אבא דאצי' מבלי שהקדים לזה העלאה דאור אימא כלל כפי סדר ההשתלשלו', אלא למעלה מסדר ההשתלשלות ירד ונמשך למטה מטה בהתלבשות והעלם בבחי' קטנות דאמונה והכרה זאת כתינוק שיודע לקרות אבא שאביו מחזיר לו<sup data-n=\"5564\">80</sup> פניו אליו ממילא כו'. וזהו מדלג על ההרים שהן <span data-k=\"pg\">קמד</span> ּ המדות<sup data-n=\"5565\">81</sup> ומוחין דאימא (וגם על מדות דחכמה [וכתר] שבחכ' כנ\"ל) מצד שהוא למעלה מבחי' רצוא דבינה כו', ודילוג זה הי' מצד עצמות המשפיע ג\"כ שלא ע\"י העלאה מלמטה כלל, ולא עוד אלא שהי' [זה] בבחי' אור תגבורת התשוקה [ב]משפיע ברב חסד ואה\"ר יתירה שע\"כ הי' בדרך דילוג דוקא כאדם שרואה את בנו הקטן האהוב לו מאד שהוא מתבוסס בדמיו [ב]ארץ למטה באין משגיח עליו שמתעורר ברוב [עוז] חמלה רבה ויתירה לדלג על ההרים למטה מטה להצילו כו'. וזהו קול דודי הנה זה בא מדלג<sup data-n=\"5566\">82</sup> על ההרים שהן הרים עליונים דהיינו מדות שבח\"ע מפני שהוא מצד כח התעוררות העצמי' בכח ועוז גדול דחסד עליון שנק' דילוג כו'. ועוד הוא ענין הדילוג לבא למטה מטה בהתלבשות ובהעלם גדול בבחי' קטנות דמוחין שבכנס\"י כמו שהי' אז בבחי' אמונה פשוטה לבד כו'. ונמצא הדילוג [הזה] הוא ב' ענינים, א' שדילוגו למעלה מעלה על ההרים כו' למעלה מן ההשתלשלו' דע\"ס, והב' דילוגו למטה מטה ביותר, והכל א' וד\"ל.\n<b>וזהו</b> ענין המצה שמצוה לאכול בפסח דוקא כדי שיהי' לזכרון לדילוג זה ולהלבשה זאת דרב חסד עליון דעצמות המאציל כמו שהי' למעלה ממש, ובאמת ענין הפסח וענין המצה המה ב' דברים, ענין הפסח הוא [ענין] הדילוג והקפיצה מלמעלה מעלה על כל סדר ההשתלשלו' דע\"ס כנ\"ל שהוא ההמשכה מעצמות דאור אבא דוקא כנ\"ל, והמצה הוא ענין הלבשה שלו שמתלבש בבחי' הקטנות המוחין ביותר שהיא האמונה וההכרה כתינוק המכיר לאביו שהוא לחם עוני [דמצה] הנ\"ל שלמעלה<sup data-n=\"5567\">83</sup> מן הדעת ושכל [כנ\"ל]. אמנם עכ\"ז הנה<sup data-n=\"5568\">84</sup> שניהם ענין א' הוא משום דהא בהא תליא דוקא שכאשר באה ההתעוררות החזקה מצד עצמות עוז אה\"ר שבחסד<sup data-n=\"5569\">85</sup> העליון שהוא גורם הדילוג הנ\"ל שנק' פסח ממילא בא לבחי' הלבשה זאת דקטנות דמצה שהוא המקום שירד לשם ולשם הוא מדלג ממקומו הגבוה וכמ\"ש במ\"א בענין מה שבשה\"ש לא נז' להיכן מדלג רק או' מדלג על",[["5564","80","<b>לו</b>: ידיט: ליתא."],["5565","81","<b>ההרים שהן המדות</b>: נסמן לעיל פ' שמות יד, ד הערה 642."],["5566","82","<b>קול דודי. . מדלג</b>: שה\"ש ב, ח."],["5567","83","<b>שלמעלה</b>: ידיט: שלמטה."],["5568","84","<b>הנה</b>: שם: ליתא."],["5569","85","<b>שבחסד</b>: שם: ורב חסד."]]],[2300540305,"ההרים [מקפץ] כו' ובתו' מפרש<sup data-n=\"5570\">86</sup> להיכן דילוגו כמ\"ש ופסח ה' על הפתח שהוא בחי' המל'<sup data-n=\"5571\">87</sup> שרש כנס\"י<sup data-n=\"5572\">88</sup> למטה לשכון ולדבוק בהם כו'. ונמצא דפסח ומצה שניהם ענין א' שהוא הדילוג מגבוה לנמוך רק שהפסח הוא הדילוג ממקומו והמצה הוא בחי' ירידתו והלבשתו למטה מטה כנ\"ל וד\"ל. וזהו שא' בהגדה מצה זו שאנו אוכלים כו' ע\"ש שלא הספיק כו' עד שנגלה עליהם מלך כו' שזהו ענין ירידתו למטה בהתלבשות בבחי' הקטנות דאבא, ופסח זה<sup data-n=\"5573\">89</sup> כו' ע\"ש שפסח כו', וע\"כ א' על מצות ומרורים יאכלוהו<sup data-n=\"5574\">90</sup> שהוא המצה שצריך לאכול למצוה<sup data-n=\"5575\">91</sup> בליל א' דפסח דוקא משום דהא בהא תליא כנ\"ל וד\"ל (ובמ\"א מבואר שב' מיני מצות היו<sup data-n=\"5576\">92</sup> א' שאכלו עם הפסח קודם חצות והב' מצה שלא הספיק להחמיץ כו' שהוא אחר חצות שלא שייך לפסח שאז עבר זמן אכילת פסח כידוע וא\"כ אין מצה זו שאנו אוכלים ע\"ש כו' שלא כו' שייך כלל לפסח דלא כדלעיל. אך בגוף הענין באמת הכל א' שהרי בחצות לילה <span data-k=\"pg\">290</span> ּ דוקא עבר ה' לנגוף את מצרים ופסח ה' על הפתח כו' ואז נא' וישא העם את בצקו<sup data-n=\"5577\">93</sup> טרם יחמץ כו' ויאפו את הבצק עוגות מצות<sup data-n=\"5578\">94</sup> כו' וא\"כ שפיר קאמר דפסח זה ע\"ש שפסח [כ]ו' מצה זו כו' ע\"ש שלא הספיק כו' שבשעה א' היו וד\"ל).\n<b>והנה</b> [ב]כל הנ\"ל יובן ג\"כ ענין מצות הספי' מיד אחר מצות המצה בליל א' דפסח מטעם הנ\"ל, ותחלה י\"ל מה שבחג השבועות אחר מצות הספי' נצטוינו בשתי הלחם דכתיב בה [כי] חמץ תאפינה<sup data-n=\"5579\">95</sup> דוקא, והרי לפי המובן מכל הנ\"ל בענין המצה מפני שהיא בבחי' הקטנות דנה\"י דאבא נאסר החמץ שהוא בבחי' טעם מורגש דבינה ומדות כו', הלא גם שתי הלחם אינו רק בבחי' נו\"ה דאבא<sup data-n=\"5580\">96</sup> כמ\"ש בס' הקבלה והוא ענין מ\"ת שנמשך לכנס\"י מבחי' נו\"ה דח\"ע והן ב' תו[רות]<sup data-n=\"5581\">97</sup> שבכ[תב] ושבע\"פ שזהו ג\"כ בבחי' הקטנות כו'. אך הנה ידוע בשרש טעם ענין הספירה ז' שבועות דוקא שהן לנגד ז' מדות<sup data-n=\"5582\">98</sup> דקליפה לתקנם ולחברם<sup data-n=\"5583\">99</sup> לאהפכא חשוכא לנהורא<sup data-n=\"5584\">100</sup> כו', והוא ענין עומר שעורים<sup data-n=\"5585\">101</sup> מאכל בהמה<sup data-n=\"5586\">102</sup> כו' שנהפכו למדות דקדושה שהן ז' פעמים ז' ש[ל]זה מצוה למימני יומי ומצוה למימני שבוע[י]<sup data-n=\"5587\">103</sup> כו', כי כל מדה וספירה כלולה מז' המדות כמו מדת החסד שהוא שבוע הא' כלולה מחו\"ג ותנהי\"מ שבחסד וכן מדת הגבורה בשבוע הב' כו', וע\"כ א' ז' שבועות תספר לך<sup data-n=\"5588\">104</sup> בכלל ומ\"ט ימים [הן] בפרט עכ\"ז<sup data-n=\"5589\">105</sup> ובכל יום [ויום] מתברר מספי' ומד' זו דשבוע זו בפרט כידוע. וענין הבירור הוא לפי שידוע",[["5570","86","<b>שבשה\"ש לא נז'. . ובתו' מפרש</b>: ראה לעיל צ, ג."],["5571","87","<b>הפתח. . המל'</b>: ראה לעיל צא, א. וש\"נ."],["5572","88","<b>המל' שרש כנס\"י</b>: ראה זהר בלק קצז, א."],["5573","89","<b>ופסח זה</b>: רמב\"ם הל' חו\"מ פ\"ח, ה\"ד. וראה לעיל צד, ד הערה 388."],["5574","90","<b>על מצות ומרורים יאכלוהו</b>: בהעלותך ט, יא. וראה הגדה עם לקוטי טעמים ומנהגים בפיסקא כורך ד\"ה על מצות (לו, ב). לקמן קכא, ד."],["5575","91","<b>למצוה</b>: ידיט: מצה."],["5576","92","<b>שב' מיני מצות היו</b>: ראה מאמרי אדה\"ז תקס\"ט ע' מא. שה\"א י, ב ובהערה 18."],["5577","93","<b>וישא העם את בצקו</b>: בא יב, לד."],["5578","94","<b>ויאפו. . עגות מצות</b>: בא שם, לט [בדילוג]."],["5579","95","<b>חמץ תאפינה</b>: אמור כג, יז."],["5580","96","<b>שתי הלחם. . נו\"ה דאבא</b>: ראה גם פע\"ח (שער חה\"ש) שכ\"ג, פ\"א. מאמרי אדה\"ז תקס\"ה כאן (ע' תלא). סידור שער חג השבועות שי, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380355\" data-slug=\"likkutei-torah\" data-id=\"4001380355\">לקו\"ת במדבר יא, ד</a>. ביאוה\"ז כאן (עד, סע\"א)."],["5581","97","<b>שתי הלחם. . ב' תו[רות]</b>: ראה השמטות לזח\"א רס, א."],["5582","98","<b>ז' שבועות. . ז' מדות</b>: ראה פע\"ח (שער חה\"ש) שכ\"ג, פ\"א. מאמרי אדה\"ז תקס\"ח ח\"א ע' קכז ואילך. ע' רכה ואילך. ע' רלב וע' רמא. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370402\" data-slug=\"torah-or\" data-id=\"3901370402\">תו\"א ויקהל פט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380371\" data-slug=\"likkutei-torah\" data-id=\"4001380371\">לקו\"ת במדבר טו, ד</a>."],["5583","99","<b>ולחברם</b>: ידיט: ולבררם."],["5584","100","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["5585","101","<b>עומר שעורים</b>: מנחות סח, ב. תו\"כ ויקרא ב, יד."],["5586","102","<b>שעורים מאכל בהמה</b>: ראה פסחים ג, ב. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תרמג."],["5587","103","<b>מצוה למימני יומי. . שבוע[י]</b>: מנחות סו, א."],["5588","104","<b>ז' שבועות תספר לך</b>: פ' ראה טז, ט."],["5589","105","<b>עכ\"ז</b>: ידיט: ליתא."]]],[2300540330,"שהי' השבירה בז\"מ דס\"ג<sup data-n=\"5590\">106</sup> דתהו עד שנאחזים החיצונים ב[חיצוניו' ו]אחוריים דז\"מ דקדושה כמו [אהבה] רעה שמסתעפת ומקבלת יניקה מחיצונים ופסולת דאהבה האלקי' דקדושה כענין אברהם אוהבי<sup data-n=\"5591\">107</sup> כו' שיצא ממנו ישמעאל<sup data-n=\"5592\">108</sup> תאו[ות]<sup data-n=\"5593\">109</sup> רע[ות] שנמשך כמים בחי' חסד דקליפה<sup data-n=\"5594\">110</sup>, וכמו\"כ מפחד ויראה דיצחק דקדושה יצא ממנו עשו<sup data-n=\"5595\">111</sup> בחי' פסולת וחיצוני' דגבו' דקדושה סוספיתא דדהבא<sup data-n=\"5596\">112</sup> כו' שנק' גבו'<sup data-n=\"5597\">113</sup> דקליפה שהוא להב וחום [ו]אש זרה דתאוה רעה<sup data-n=\"5598\">114</sup> ורציחה<sup data-n=\"5599\">115</sup> שא' [עליו] על חרבך תחי'<sup data-n=\"5600\">116</sup> וכמא'<sup data-n=\"5601\">117</sup> רישא דעשו<sup data-n=\"5602\">118</sup> כו' כידוע, וכה\"ג בכל המדות, ואין תיקון ובירור שלהם רק בז\"מ דקדושה כ\"מ<sup data-n=\"5603\">119</sup> שהן בשרשן בבחי' הגבו' עליונות דבחי' ס\"ג דבינה כו' דאין מיתוק הרע אלא בשרש[ו]<sup data-n=\"5604\">120</sup> דוקא כידוע. וז\"ש והניף את העומר לרצונכם<sup data-n=\"5605\">121</sup> דוקא כמ\"ש במ\"א שהוא ענין [התהפכות] הז\"מ רעות מן הקצה אל הקצה דוקא ולא לאכפייא לבד כו' וכמים המרים שנהפכו למתיקות מצד עצמן כו' (כענין דם נעכר ונעשה חלב<sup data-n=\"5606\">122</sup> כמ\"ש במ\"א באריכות), ולזאת אין ההתהפכות שלהם רק בבחי' התפעלות רשפי אש התשוקה בבחי' רצוא דרץ לבך הנ\"ל שהוא בחי' רשפי אש התשוקה האלקי' שנק' שלהבת י\"ה<sup data-n=\"5607\">123</sup> דוקא שבא מחמת התפעלות ההשגה [ה]אלקי' דוקא עד שיתגבר<sup data-n=\"5608\">124</sup> ביותר בבחי' כלות הנפש במורגש בלב בשר דוקא כמו כלה שארי ולבבי<sup data-n=\"5609\">125</sup> כו' לבי ובשרי ירננו<sup data-n=\"5610\">126</sup> וכה\"ג שבזה דוקא מתברר ומתהפך החום הטבעי הרע שבלב מן הקצה כו' כידוע ומבואר במ\"א. ואין זה רק ע\"י עוצם [ה]התפעלות בהתבוננות בשמחה בבחי' רצוא לעלות ולידבק בה' א[חד] ואין זר אתו כו' כענין מי לי בשמים<sup data-n=\"5611\">127</sup> כו' והוא ענין אם הבנים דבינה<sup data-n=\"5612\">128</sup> מקור התהוות [ה]ז\"מ דקדושה <span data-k=\"pg\">קמה</span> ּ אוי\"ר כו' שהוא<sup data-n=\"5613\">129</sup> ענין נש\"ב כמ\"ש בזהר ע\"פ נודע בשערים<sup data-n=\"5614\">130</sup> כו' באינון תרעין עילאין<sup data-n=\"5615\">131</sup> דבינה [ב]כל חד וחד לפום שיעורא דילי' בכל[י] השגתו שמשער בלבי' דוקא. וזהו עיקר ענין מ\"ט ימים דספירה וחג השבועות שער החמשים<sup data-n=\"5616\">132</sup> כו', וזהו שאו' היום יום א'<sup data-n=\"5617\">133</sup> כו' בחי' חסד שבחסד שנמשך מבינה עילאה להפוך ולברר לחסד דק\"נ כו' שהוא בכלל בחי' המשכת מוחי' דאימא בז\"מ דקדושה שבזאת ניתקנו הז\"מ רע[ות] דק\"נ מחשך לאור כידוע וד\"ל.",[["5590","106","<b>השבירה בז\"מ דס\"ג</b>: נסמן לעיל פ' וארא פה, ג הערה 850."],["5591","107","<b>אברהם אוהבי</b>: ישעי' מא, ח."],["5592","108","<b>אברהם. . שיצא ממנו ישמעאל</b>: ראה פסחים נו, א. מאמרי אדה\"א דברים ח\"ג ע' א'קטו ואילך. שע\"ת פה, ג ובהנסמן במ\"מ לשם. לקמן קכז, ד."],["5593","109","<b>ישמעאל. . תאו[ות]</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקצד (נוסחא שני'). מאמרי אדה\"א נ\"ך ע' ח. וש\"נ."],["5594","110","<b>ישמעאל. . חסד דקליפה</b>: נסמן לעיל פ' שמות לא, א."],["5595","111","<b>דיצחק. . יצא ממנו </b>[ידיט: ליתא]<b> עשו</b>: נסמן בהערה 108."],["5596","112","<b>סוספיתא דדהבא</b>: ראה זהר פקודי רכד, ב. מאמרי אדה\"ז תקס\"ב ח\"א ע' לג."],["5597","113","<b>עשו. . גבו'</b>: ראה גם לקמן פ' בשלח קלו, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שדמ. וש\"נ."],["5598","114","<b>דתאוה רעה</b>: ידיט: דתאות והכעס."],["5599","115","<b>עשו. . ורציחה</b>: ראה ספרי ברכה לג, ב."],["5600","116","<b>על חרבך תחי'</b>: תולדות כז, מ [ושם: ועל — ראה ספרי שם. מאמרי אדה\"א בראשית ע' רנא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670458\" data-slug=\"torat-chaim\" data-id=\"2300670458\">תו\"ח לך פח, ב</a> הערה 9]."],["5601","117","<b>וכמא'</b>: ידיט: וכמ\"ש."],["5602","118","<b>רישא דעשו</b>: ראה ת\"י ויחי נ, יג. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תרסב. קונטרסים ע' שלג."],["5603","119","<b>כ\"מ</b>: ידיט: כמו."],["5604","120","<b>דאין מיתוק הרע אלא בשרש[ו]</b>: נסמן לעיל פ' שמות מג, ב הערה 19."],["5605","121","<b>והניף את העומר לרצונכם</b>: אמור כג, יא [בדילוג]. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380229\" data-slug=\"likkutei-torah\" data-id=\"4001380229\">לקו\"ת אמור לה, ד</a>. מאמרי אדה\"א במדבר ח\"ב ע' שפט. ע' תמו. ע' תסד וע' תצו."],["5606","122","<b>דם נעכר ונעשה חלב</b>: נסמן לעיל פ' וארא נא, א."],["5607","123","<b>שלהבת י\"ה</b>: שה\"ש ח, ו."],["5608","124","<b>שיתגבר</b>: יד: שתגבר. יט: שתתגבר."],["5609","125","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["5610","126","<b>לבי ובשרי ירננו</b>: תהלים פד, ג."],["5611","127","<b>מי לי בשמים</b>: תהלים עג, כה."],["5612","128","<b>אם הבנים דבינה</b>: נסמן לעיל פ' שמות יז, א."],["5613","129","<b>שהוא</b>: ידיט: שהן."],["5614","130","<b>נודע בשערים</b>: ראה זהר וירא קג, ב. תניא בהקדמה."],["5615","131","<b>תרעין עילאין</b>: ראה לעיל פ' וארא עט, ב הערה 457."],["5616","132","<b>וחג השבועות שער החמשים</b>: ראה מאמרי אדה\"ז תקס\"ו ע' ריג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370309\" data-slug=\"torah-or\" data-id=\"3901370309\">תו\"א יתרו סט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380351\" data-slug=\"likkutei-torah\" data-id=\"4001380351\">לקו\"ת במדבר י, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380356\" data-slug=\"likkutei-torah\" data-id=\"4001380356\">יב, א</a>. לעיל קיא, ד."],["5617","133","<b>היום יום א'</b>: נוסח ספירת העומר. ראה גם לעיל קיא, ד."]]],[2300540353,"<b>והנה</b> באמת י\"ל למה מתחיל מנין הימים דימי הספירה בליל ב' דפסח ולא בליל א' דפסח שאז יצאו ממצרים שהן נש\"ט דקליפה כידוע, אך הענין הוא כי בליל א' דפסח שיצאו ממצרים בבחי' הקטנות בתכלית שהוא בחי' האמונה והכרה לבד כנ\"ל ואעפ\"י שיש בזה בהעלם מבחי' עצמות אור אבא כו', אבל הוא בא בהלבשה בבחי' הקטנות מאד וע\"כ לא הי' בהם אז כח להפוך הזמ\"ר דק\"נ עדיין כי לא הי' בהם כח התפעלות השמחה בהתבוננות בגדולת ה' בבחי' רץ לבך כו' כנ\"ל, אך מיד אחר שאכלו המצה שנק' מיכלא דמהימנותא כנ\"ל שנתחזק בנפשם כח האמונה הפשוטה והכרה עצמי' הנ\"ל לפי שהי' בזה הלבשת עצמ[ו]' אור אבא כנ\"ל, ע\"כ ציוה מיד להתחיל לספור ז' שבועות<sup data-n=\"5618\">*134</sup> בליל הב' כדי שיוכל להיות עי\"ז גילוי דעצמות אור אבא במ\"ת שנק' בחי' גדלות המוחין דאבא, והוא ע\"י שספרו ז' שבועות מקודם ע\"כ יכלו לקבל מבחי' [גדלות] המוחין דאור עצמות אבא ובלא מצות הספירה לא הי' בא גילוי אור עצמות החכ' במ\"ת, וגם לא היו יכולים לקבל כלל. ואם לא מצות המצה ביום א' דפסח לא הי' מועיל מצות הספירה ז' שבועות לענין מ\"ת בחג השבועות, ושניהם כא' דוקא מצה ואח\"כ ספירה הוא שגרם גילוי אור העצמ[ו]' להתקבל בכנס\"י במ\"ת, וכך נקבע לדורות סדר הזה דוקא מצה ואח\"כ ספירה ואח\"כ מ\"ת דהא בהא תליא דוקא וד\"ל.\n<b>ולהבין</b> ביאור הדברים הנה מבואר למעלה בבחי' רו\"ש שצריך להיות בחי' ביטול התפעלות דרצוא בהתלהבות התשוקה להיות חוזר ושב למטה כמ\"ש אם רץ לבך שוב לאחד<sup data-n=\"5619\">134</sup> כו', והיינו מפני תגבורת כח הביטול העצמי דחכ' שהוא בבחי' אין ממש כמו עד\"מ כשרואה את<sup data-n=\"5620\">135</sup> המלך שמתבטל כל עצמותו בביטול שלמעלה מן הטעם. ונמצא מה שנתפעל מצד הטעם והשגה נתבטל לגמרי, ובעבודה הנ\"ל<sup data-n=\"5621\">136</sup> הוא מה שכל התפעלות המורגשת בהשגה יבא [ל]בחי' ביטול לגמרי כאשר בא לידי<sup data-n=\"5622\">137</sup> ראי' עין השכל דחכמה כענין מה פשפשת כו', ונק' ביטול היש כו'<sup data-n=\"5623\">138</sup> דהשגה לאין דחכמה שעי\"ז נמשך גילוי אין ומ\"ה העצמי דחכמה, וזהו דוקא אחר שבאה ההשגה בהתרחבות ההסבר ונתבטל להיות רק בבחי' תמצית ההשגה [ה]נק' עומק המושג,",[["5618","*134","<b>ציוה. . לספור ז' שבועות</b>: ראה גם לקמן קכא, ג. וש\"נ."],["5619","134","<b>לאחד</b>: ידיט: לאחור."],["5620","135","<b>את</b>: שם: פני. ראה גם בסמוך בפנים ובהערה 139."],["5621","136","<b>ובעבודה הנ\"ל</b>: שם: ובעבודת ה'."],["5622","137","<b>לידי</b>: ידיט: לבחי'."],["5623","138","<b>כו'</b>: שם: ליתא."]]],[2300540376,"וג\"ז נעשה רק בחי' כלי לקבל גילוי אור דחכמה שהוא בחי' ראי' דחכמה כשרואה את<sup data-n=\"5624\">139</sup> פני המלך כו', וכל מה<sup data-n=\"5625\">140</sup> שההשגה [היא] ברוחב יותר ובאה לביטול לאין שהוא היפוך הרצוא כנ\"ל יותר יומשך שפע אור החכ' שהוא ביטול העצמי מאין העצמי לבינה (כעמוד שבג\"ע<sup data-n=\"5626\">141</sup> שמתבטלים מהשגתם הראשונה, יבואו להשתחוות לפני ה'<sup data-n=\"5627\">142</sup> בבחי' ביטול העצמי דראי' דחכ' וכמו יראה כל <span data-k=\"pg\">292</span> ּ זכורך<sup data-n=\"5628\">143</sup> כו'). וכל שאין ההשגה ברוחב כ\"כ אין ביטולה גורם ירידת אור גילוי החכמה כ\"כ (כמשל תלמיד שהוא חכם גדול ביותר, יותר [י]בוטל מרוחב השגתו בקבלתו מרבו לקבל שפע רב יותר וכמ\"ש יהיב חכ' לחכימין<sup data-n=\"5629\">144</sup> דוקא וכן בכל חכם לב דוקא נתתי חכ'<sup data-n=\"5630\">145</sup> שהוא ביטול היש ביותר גורם ירידת אין דח\"ע יותר). ונמצא מה שכל[י] יסוד דבינה נעשה רחב יותר לקבל מאין דחכמה הוא רק לפ\"ע הביטול ועלי' דרוחב ההשגה מיש לאין יותר, והוא ענין יחוד דנה\"י דאבא בנה\"י דאימא אחר עלי' מוחין דאימא כו' שנמשך השפע מחכ' לבינה [בגילוי] בלתי העלם וצמצום כלל וכמ\"ש במ\"א בענין הבן בחכמה וחכ\"ם בבינה<sup data-n=\"5631\">146</sup> [דהיינו] ע\"ב דס\"ג [ד]בינה בביטול[ה] לקבל מיסוד אבא [כו' ו]הוא שער הנו\"ן בינה שבו יחוד או\"א בפנימיות שהוא במ\"ת דוקא (ועד\"ז יש יחוד או\"א בחיצוניות לצורך שפע העולמות כמו בשבת שביטול היש לאין דחכמה בליל שבת גורם ירידת האין דחכ' בבינה כו'). והיינו מ\"ש דאו\"א זיווגייהו תדיר<sup data-n=\"5632\">147</sup> [שהוא] לצורך העולמות ע\"י המשכת אין דחכ' בבינה ע\"י ביטול היש דבינה בחכמה כו'. וזהו ענין הספירה שקודם מ\"ת שהוא בהתפעלו' דרצוא שמחמת ההשגה דבינה ואמנם באה לכלל ביטול והתכללות דוקא כדי להמשיך בחי' אור אבא ע\"י היפך הרצוא שהוא עלי' המוחין דאימא, וכל שיש יותר התפעלו' הרחבת השגה ובאה לביטול יותר יומשך אור אבא וגובר על הגבו' דאימא להפכם לבחי' חסדים דאבא שהוא להיות בבחי' שוב דחכ' בחי' ביטול העצמי הנ\"ל שהוא עיקר היחוד הפנימי' דאו\"א להפוך הרצוא עצמו לשוב כו' אבל כשאין בחי' הרצוא [ב]השגה דבינה כ\"כ אין אור חסדים דאבא מאיר כ\"כ כו'. וזהו ענין גדלות המוחין או קטנות המוחי' דאבא שאם הביטול דהשגה באה מן הרוחב יותר אז יומשך גדלות המוחי' דחכ' ביותר ומתגבר להפוך היש דבינה לאין וכשאין העלא' דבינה [ב]בחי' רצוא כ\"כ לא נמשך מאור אבא רק בבחי' קטנות המוחי' [כו']. וזהו ענין מ\"ת שהוא בחי' האר[ת] גדלות המוחין דאור אבא ע\"י הספי' ז' שבועות בבחי' העלא' דנש\"ב מיש לאין בביטול הרצוא שעי\"ז יגבר יותר המשכ' גילוי אור דגדלות המוחין דאבא כנ\"ל וד\"ל.",[["5624","139","<b>כשרואה את</b>: שם: כרואה."],["5625","140","<b>מה</b>: שם: ליתא."],["5626","141","<b>כעמוד שבג\"ע</b>: ראה בהנסמן לעיל פ' שמות ו, ד הערה 295."],["5627","142","<b>יבואו להשתחוות לפני ה'</b>: ע\"פ ישעי' סו, כג."],["5628","143","<b>יראה כל זכורך</b>: משפטים כג, יז. תשא לד, כג. ראה טז, טז."],["5629","144","<b>יהיב חכ' לחכימין</b>: נסמן לעיל פ' וארא פג, ב."],["5630","145","<b>בכל. . נתתי חכ'</b>: נסמן לעיל שם."],["5631","146","<b>הבן בחכמה וחכ\"ם בבינה</b>: ס\"י פ\"א, מ\"ד. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תרפח."],["5632","147","<b>דאו\"א זיווגייהו תדיר</b>: ראה זהר (אד\"ז) האזינו רצ, ב. ע\"ח שער הכללים פי\"ג. מאמרי אדה\"א בראשית ע' שנו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670060\" data-slug=\"torat-chaim\" data-id=\"2300670060\">תו\"ח נח מו, ג</a> הערה 25. לקמן פ' יתרו עדר, ג."]]],[2300540397,"<b>והנה</b> כ\"ז הוא [כ]פי סדר ההשתלשלו' דע\"ס כח\"ב [חו\"ב] ומדות כו' שע\"י בחי' עו\"ע שא\"ז<sup data-n=\"5633\">148</sup> ע\"י העלא' וביטול התחתון לעליון כמו מהעלאו' מוחי' דאימא בביטול היש לאין דחכ' נמשך המשכת החכ' בבינה וכן מכתר לחכמה כידוע, וז\"ש דאו\"א זיווגייהו תדיר כו' ביחוד פנימי' כמו במ\"ת ויחוד חיצוני' כנ\"ל [וד\"ל]. אבל בליל א' דפסח הי' בחי' הדילוג שהוא בא מעצמות [א]א\"ס ב\"ה מלמעלה מעלה מסדר ההשתל' דע\"ס דאצי' כנ\"ל שאז אין ההמשכה מלמעלה נמשך ע\"פ העלא' מלמטה כלל כנ\"ל, והוא ענין המצה שנק' מיכלא דמהימנותא כו' שאעפ\"י שהוא בבחי' קטנות דאבא לבד כנ\"ל שהוא האמונה ו[ה]הכרה לבד אבל הרי יש בה בהעלם והתלבשות מבחי' העצמ[ו]' דאבא [כמו עד\"מ בעצם כח התולדה דאב לבנו כנ\"ל באורך. וע\"כ אין במצה טעם להיות שאין בה] מבחי' הארת מוחי' דאימא כלל כימי הספירה רק בבחי' שפלות וביטול פשוט ועצמי, אמנם [בזה דוקא מלובש בהעלם כל בחי' כח העצמיות ממש עד שמכחה ומחמתה דוקא יבא כל בחי' גדלות] המוחי' דאבא במ\"ת ע\"י העלאה דמוחי' דאימא שבא בסדר ההשתלשלו' <span data-k=\"pg\">קמו</span> ּ מאין ליש כנ\"ל, ואם לא בחי' הדילוג הזה שבמצה שבא בהלבשה בבחי' הקטנות לא הי' יכול להיות גילוי אור הגדלות דאבא במ\"ת כלל וכמ\"ש וארשתיך לי באמונה כו' שהאמונה שביצ\"מ נק' אירוסין שמזה יבא כח ענין הנישואין<sup data-n=\"5634\">149</sup> בחופה במ\"ת דכתיב ביום חתונתו זה מ\"ת<sup data-n=\"5635\">150</sup> כידוע, ולכך מתחיל ימי הספירה מיד אחר מצות המצה בליל א' דפסח דוקא לפי שהלבשה זו שבבחי' הקטנות דוקא הוא הכח ומקור לגילוי אור דגדלות דמ\"ת.\n<b>(ושרש</b> הענין הוא כמ\"ש במ\"א (בפ' כי תשא<sup data-n=\"5636\">151</sup> ) שיש ב' מדרגות באמונה א' מה שנק' אמונה מלשון אומן ע\"ש הגידול כאומן את היונק שזהו מצד הירושה מאבות שנק' אומנים<sup data-n=\"5637\">152</sup> כו', והב' האמונה שקיבלו ע\"י משה שנק' רע\"מ<sup data-n=\"5638\">153</sup> והוא מ\"ש ורעה אמונה<sup data-n=\"5639\">154</sup> שהוא מ\"ש איהו אמת ואיהי אמונה<sup data-n=\"5640\">155</sup> דהיינו שכנס\"י בחי' כלי<sup data-n=\"5641\">156</sup> קיבול להכיל לאמיתי' אור עצמו' א\"ס ב\"ה כמו שהוא [ממש] שלמעלה מהשתלשלו' דסובב [ו]ממלא שזהו איהו אמת כמו אמתך אלקי<sup data-n=\"5642\">157</sup> כו'. משא\"כ אמונה דאבות הי' בשם הוי' בבחי' סובב כו' וכמ\"ש והאמין בה'<sup data-n=\"5643\">158</sup> כו' וכנס\"י שנגדלים באמונה זו נק' לימודי הוי'<sup data-n=\"5644\">159</sup> כו' (כמ\"ש שם באורך). והנה ע\"י המצה נעשו בחי' כלי בית קיבול להכיל לאמיתי' מהו\"ע א\"ס ב\"ה שלמעלה ממקור ההשתלשלו' דקו\"ח ([ו]זהו ענין המצה [בה\"ה] שהוא מילוי דה\"[ה]<sup data-n=\"5645\">160</sup> שזהו בחי' מל' דא\"ס קודם",[["5633","148","<b>שא\"ז</b>: ביד: שאז."],["5634","149","<b>וארשתיך לי באמונה. . אירוסין. . הנישואין</b>: הושע ב, כב. ראה לעיל קי, א. וש\"נ."],["5635","150","<b>ביום חתונתו זה מ\"ת</b>: שה\"ש ג, יא. ראה תענית כו, ב. מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["5636","151","<b>בפ' כי תשא</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' תרכא ואילך. וראה הנסמן לעיל צב, א הערה 247."],["5637","152","<b>מאבות שנק' אומנים</b>: ראה גם מאמרי אדה\"א שמות שם. וש\"נ. נ\"ך ע' כט. לקמן פ' בשלח קנו, א. תצוה שלח, ג. תשא שפא, ב."],["5638","153","<b>משה שנק' רע\"מ</b>: נסמן לעיל פ' וארא עז, ב."],["5639","154","<b>ורעה אמונה</b>: תהלים לז, ג."],["5640","155","<b>איהו אמת ואיהי אמונה</b>: נסמן לעיל פ' שמות י, ד."],["5641","156","<b>כלי</b>: ביד: בית."],["5642","157","<b>אמתך אלקי</b>: תהלים עא, כב."],["5643","158","<b>והאמין בה'</b>: לך טו, ו."],["5644","159","<b>לימודי הוי'</b>: ישעי' נד, יג."],["5645","160","<b>המצה. . דה\"[ה]</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' מ. וש\"נ. שם ע' רצג. הנחות תקע\"ז ע' כו."]]],[2300540417,"הצמצום שנגלה עליהם מלך<sup data-n=\"5646\">161</sup> כו'), וכמו שיהי' לע\"ל שיתגלה אמיתי' עצמותו<sup data-n=\"5647\">162</sup> וכמ\"ש כולם ידעו אותי<sup data-n=\"5648\">163</sup> ממש בהכרה גמורה מה שעתה הוא בבחי' אמונה לבד וע\"כ כולם בשוה ידעו אותי ממש<sup data-n=\"5649\">164</sup> מקטנם<sup data-n=\"5650\">165</sup> ולא<sup data-n=\"5651\">166</sup> ילמדו איש את רעהו<sup data-n=\"5652\">167</sup> כו', משא\"כ עתה נק' לימודי הוי' כו'. ולפי שזה האור נמשך מלמעלה מן ההשתלשלו' דחו\"ב מאין ליש כו' ומשה גואל ראשון ואחרון<sup data-n=\"5653\">168</sup> כידוע. ובזה יובן שבחי' המצה הגם שבא בה בהתלבשות והעלם מעצמות דאור אבא אבל הוא בא ממהו\"ע א\"ס ב\"ה שיתגלה לע[\"ל] וע\"כ גדול כחה ביותר עד שמחמתה יכול להיות בחי' היחוד פנימי דאוא\"ס<sup data-n=\"5654\">169</sup> בבחי' המשכת גדלות המוחי' דאבא במ\"ת כי יש בכלל מאתים מנה<sup data-n=\"5655\">170</sup> כו', וז\"ש למען תזכור כו' גם לימוהמ\"ש ועוה\"ב<sup data-n=\"5656\">171</sup> וד\"ל). וזהו ענין הסדר דמצה וספירה ומ\"ת דע\"י המצה תחילה יוכלל<sup data-n=\"5657\">172</sup> לבחי' העלא' והמשכה דרו\"ש להיות גילוי אור פנימי' הח\"ע במ\"ת מטעם הנ\"ל וד\"ל.\n<b>ומעתה</b> יובן [ג\"כ] מה ששתי הלחם בשבועות נאמר בהן חמץ תאפינה דוקא ואעפ\"י שגם הם בבחי' הקטנות דנה\"י<sup data-n=\"5658\">173</sup> דאבא שלזה נאסר החמץ בפסח כנ\"ל, דהנה ענין החמץ הוא [ב]בחי' טעם מורגש בהגבהה והתנשאות כנ\"ל שזהו בבחי' התפעלות דרץ לבך כו' בהתבוננות והשגה בטעם מורגש כו', ובימי הספירה הרי באה בחי' התפעלות הרצוא דבינה לבחי' ביטול לאין דחכמה שמתהפך לבחי' שוב דוקא כנ\"ל ע\"י התגברות המשכות דביטול העצמ[ו]' דחכמה כו' עד מ\"ת כו' שהוא גילוי אור דגדלות אבא שמתגבר ביותר על מוחי' דאימא להפוך גם בחי' היש לאין עד שאין מקום ליניקת החיצונים דגבו' קשות דנוגה לקבל מבחי' בינה מקור המדות (וע\"כ א' ישראל שעמדו<sup data-n=\"5659\">174</sup> על הר סיני<sup data-n=\"5660\">175</sup> פסקה מהן זוהמא של נחה\"ק כו'), <span data-k=\"pg\">294</span> ּ ולזאת יוכל להיות עליות גם לחמץ ושאור שהוא הגסות דק\"נ שגם הם באים בבחי' הביטול לאלקות, ואדרבה בחמץ ושאור כשיהופך לאין האלקי בא עי\"[ז] גילוי אור גדלות אבא ביותר מטעם הנ\"ל שכל שיש יותר ביטול היש לאין יותר יומשך הארת אין כו'. וזהו ענין שתי הלחם שהוא ב' לחמים דתודה<sup data-n=\"5661\">176</sup> שבהם גילוי אור דגדלות המוחי' דאבא מבחי' פנימי' רע<sup data-n=\"5662\">177</sup> שגובר על בחי' הגבו' דיש דבינה ביותר להפכם לאין, וע\"כ נצטוו שיאפו לשתי הלחם מחמץ דוקא כמ\"ש חמץ תאפינה מפני שהן בבחי' גדלות דמוחין דאבא ששם גם החמץ עולה בבחי' אין וניתוסף ע\"י<sup data-n=\"5663\">178</sup> הארת גדלות המוחי' דאבא, לפי<sup data-n=\"5664\">179</sup> שבהתהפכות",[["5646","161","<b>שנגלה עליהם מלך</b>: הגש\"פ פיסקא מצה זו."],["5647","162","<b>עצמותו</b>: ב: העצמו'."],["5648","163","<b>כולם ידעו אותי</b>: ירמי' לא, לג."],["5649","164","<b>ממש</b>: ביד: ליתא."],["5650","165","<b>מקטנם</b>: ראה לעיל פ' שמות לח, ג הערה 47."],["5651","166","<b>ולא</b>: ביד: כו' שלא."],["5652","167","<b>ולא ילמדו איש את רעהו</b>: התחלת הכתוב כולם ידעו אותי [בדילוג]."],["5653","168","<b>ומשה גואל ראשון ואחרון </b>[ב: וגואל אחרון]: ראה שמו\"ר פ\"ב, ד. מאמרי אדה\"א ויקרא ח\"א ע' שנט. נ\"ך ע' תרד ובהנסמן בהנ\"ל."],["5654","169","<b>דאוא\"ס</b>: ביד: דאו\"א."],["5655","170","<b>יש בכלל מאתים מנה</b>: בבא קמא עד, א."],["5656","171","<b>למען תזכור. . לימוהמ\"ש ועוה\"ב</b>: נסמן לעיל קיא, ד."],["5657","172","<b>יוכלל</b>: ביד: יוכלו לבא."],["5658","173","<b>דנה\"י</b>: שם: דנו\"ה."],["5659","174","<b>ישראל שעמדו</b>: שבת קמו, רע\"א."],["5660","175","<b>על הר סיני</b>: ביד: במ\"ת."],["5661","176","<b>דתודה</b>: ו: דתורה. וראה לעיל הערה 97."],["5662","177","<b>רע</b>: ביד: ח\"ע."],["5663","178","<b>ע\"י</b>: יד: על ידו."],["5664","179","<b>לפי</b>: ביד: מפני."]]],[2300540437,"הרצוא לשוב דוקא אז יאיר אור דגדלות המוחי' דאבא ביותר כו' כנ\"ל וד\"ל. משא\"כ המצה נאסר בה החמץ מפני שאין בה גילוי גדלות המוחי' דאבא רק בהעלם והלבשה לבד (ומה גם [שבא] ממקום ומדרגה גבוה מאד נעלה שהוא מבחי' העצמות ממש כנ\"ל שא\"א שיעלה שם בחי' היש אף לאחר ביטולו לאין, להיותו למעלה [מעלה] מבחי' אין האמיתי דעצמות א\"ס ב\"ה שאינו שורה רק בבחי' השפלות וקטנות ביותר דוקא והוא המצה שנק' לחם עוני [דוקא] דעומ\"ר אינו שורה [רק] בעומ\"ת<sup data-n=\"5665\">180</sup> כמ\"ש כי רם ה'<sup data-n=\"5666\">181</sup> ושפל יראה כידוע, ואמנם מזה דוקא בא בחי' גילוי אור דאבא להפוך היש לאין כנ\"ל וד\"ל). ובזה מתורץ הקושיא דלעיל דאע\"פ שגם ב' הלחם הוא רק בנו\"ה דאבא אבל הוא [מ]בחי' גדלות המוחין דאבא שבא בגילוי אור בלא צמצום והעלם ולבוש כלל ע\"כ א' חמץ תאפינה דוקא, משא\"כ המצה שהיא בבחי' קטנות דיסוד אבא בהעלם ביותר נאסר בה החמץ בתכלית כדי שלא יקבלו החיצונים יניקה מפסולת הגבו' שנק' גבו' קשות כידוע וד\"ל.\n<b>והנה</b> אחר כ\"ז י\"ל שרש ענין [ה]ד' כוסות דיין דאפי' עני שבישראל מחוייב בד' כוסות<sup data-n=\"5667\">182</sup> כו', ולכאורה יפלא דלפי כל הנ\"ל הרי אין במצה מבחי' הרצוא דמוחי' דאימא כלל אדרבה לזה נאסר החמץ כו' לפי שאין בה שום התפעלו' והשגה מורגש בטעם כו', וא\"כ למה מצוה ביין בד' כוסות שהיין הוא המשמח כו' שהוא [ב]בחי' התפעלות הרצוא דבינה כידוע בכוס יין<sup data-n=\"5668\">183</sup> דקידוש שהוא בבחי' מוחין דאימא כנ\"ל. אך הנה יש להקדים ענין א' והוא מה שהמלאכי' א'<sup data-n=\"5669\">184</sup> תנה הודך על השמים<sup data-n=\"5670\">185</sup> שהוא הוד דתורה והשיב ה'<sup data-n=\"5671\">186</sup> [להם] כלום גזל יש<sup data-n=\"5672\">188</sup> ביניכם<sup data-n=\"5673\">187</sup>, דהנה באמת גם המלאכי' ראוים לקבל התורה כי עיקר ענין התורה הוא בחי' גדלות אור החכמה דאורייתא מח\"ע נפקת<sup data-n=\"5674\">189</sup> להיות בחי' שוב שאחרי היפוך הרצוא לשוב כנ\"ל שזהו כל התורה לאכללא שמאלא בימינא<sup data-n=\"5675\">190</sup> שהוא גבו' דרצוא דאימא להתהפך לחסדים דימין דאבא כו', וגם המלאכים נא' בהם והחיות רו\"ש<sup data-n=\"5676\">191</sup> שאחרי הרצוא שלהם בתחילה הם שבים בביטול דבחי' אין דחכמה לפי שבאים בקירוב יותר בהשתחוואות לפני ה', עד שהרצוא שלהם נהפך לשוב כמו בעמדם תרפינה כנפיהם<sup data-n=\"5677\">192</sup> כשבאים בקירוב יותר בעמידה יפלו מהשגתם [בהתפעלות] דרצוא שבאוי\"ר שבכנפיהם כו' (והיינו לפני<sup data-n=\"5678\">193</sup> אל נהירו דחכ'<sup data-n=\"5679\">194</sup> דנהיר עלייהו בקירוב). וזהו <span data-k=\"pg\">קמז</span> ּ וצבא השמים לך",[["5665","180","<b>דעומ\"ר. . בעומ\"ת</b>: נסמן לעיל פ' וארא פג, ב."],["5666","181","<b>כי רם ה'</b>: תהלים קלח, ו."],["5667","182","<b>עני. . בד' כוסות</b>: ראה פסחים צט, ב [במשנה]."],["5668","183","<b>יין</b>: ביד: ליתא."],["5669","184","<b>שהמלאכים א'</b>: שבת פח, ב."],["5670","185","<b>תנה הודך על השמים</b>: תהלים ח, ב."],["5671","186","<b>והשיב ה'</b>: ראה זהר שמות ג, א. ביאוה\"ז בראשית (א, ד). כאן (עד, ג). מאמרי אדה\"א שמות ח\"א ע' קעד. דברים ח\"ד ע' א'תעב."],["5672","188","<b>ביניכם</b>: ביד: בכם כו'."],["5673","187","<b>כלום גזל יש ביניכם</b>: ראה זהר שם. שבת פט, א. דרושים שבהערה שלפנ\"ז. וש\"נ. מאמרי אדה\"א במדבר ח\"ה ע' א'תרמג."],["5674","189","<b>דאורייתא מח\"ע נפקת</b>: נסמן לעיל פ' שמות יא, א."],["5675","190","<b>התורה לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תמב."],["5676","191","<b>והחיות רו\"ש</b>: יחזקאל א, יד."],["5677","192","<b>בעמדם תרפינה כנפיהם</b>: יחזקאל א, כד. כה. ראה גם לקמן פ' בשלח קסד, ג. ויקהל תח, ג."],["5678","193","<b>לפני</b>: ביט: מפנימי'. יד: מפני."],["5679","194","<b>אל נהירו דחכ'</b>: נסמן לעיל צח, ד."]]],[2300540457,"משתחוים<sup data-n=\"5680\">195</sup> שאעפ\"י שמתחלה מרחוק הוי' נראה להם<sup data-n=\"5681\">196</sup> לפ\"ע כלי השגתם ואו' שירה בהתפעלות דרצוא לבד אבל כשבאים בקירוב יותר הן משתחוים בבחי' שוב שהוא ביטול העצמי דאין ממש כנ\"ל, וז\"ש והחיות רו\"ש וד\"ל. וא\"כ היו המלאכים ראוים לקבלת התורה ולז\"א תנה הודך על השמים בחי' הוד דאבא שגנוז בתורה (כי המלאכים מקבלים מבחי' גבו'<sup data-n=\"5682\">197</sup> דקו השמאל בג\"ה<sup data-n=\"5683\">198</sup> ולא יוכלו לקבל מנצח דאבא שבקו הימין כו'), והשיבום כלום גזל יש ביניכם כו', לפי שעיקר ענין התומ\"צ הוא כאשר באים למטה בהתלבשות בדברים גשמיים בעה\"ד טו\"ר לברר ולהפוך חשוכא לנהורא<sup data-n=\"5684\">199</sup> כו' ולהבדיל בין טמא לטהור<sup data-n=\"5685\">200</sup> כו', ובמ\"ע נתאווה להיות לו דירה בתחתונים<sup data-n=\"5686\">201</sup> דוקא לא בעליונים לכך ניתנה<sup data-n=\"5687\">202</sup> התורה רק לישראל דוקא ולא למלאכים אע\"פ שיש בהם ג\"כ בחי' רו\"ש כנ\"ל וד\"ל.\n<b>וביאור</b> הדברים. הנה מבואר למעלה בשרש בחי' שוב שהוא המשכ[ות] דמוחי' דאבא היינו בחי' או\"י שהוא בחי' ירידת האור למטה מטה לבא בהתלבשות בכלים מכלים שונים דוקא היפוך בחי' העלי' והסתלקות דאו\"ח דבחי' גבו' דאימא כו', לפי שטבע בחי' או\"י לירד ולימשך מגבוה לנמוך ביותר כטבע המים שיורדים מגבוה לנמוך<sup data-n=\"5688\">203</sup> דוקא לבא בכלים מכלים שונים<sup data-n=\"5689\">204</sup> רבים, וכל שיש כלים רבים יותר יותר יומשך למטה, דהיינו כל ש[ה]כלים נמוכים ביותר שם דוקא מתפשט ונמשך האור ושפע להתלבש שכל הגבוה גבוה יותר מתפשט אורו למטה מטה יותר<sup data-n=\"5690\">205</sup> בהגבלה [והגשמה] ביותר [ו]לא בעליון הרוחני, ע\"ד דוגמא מאור שכל עמוק ביותר שמאיר אורו העצמי דוקא בכלים ולבושים היותר נמוכים כמו משלים וחידות כמשלי שלמה, שמפני עומק החכמה לא יוכל להתלבש רק במשלים המגשימים ומגבילים את האור כידוע. וזהו שהתורה נק' משל הקדמוני<sup data-n=\"5691\">206</sup> מצד רוממות מעלת החכמה הק[דומה] שא\"א לבא למטה כ\"א בלבושים גשמיים כצמר דציצית וקלף דתפילין וכה\"ג בכל עניני הל\"ת בסו\"מ גשמי כו', שכך הוא טבע דבחי' או\"י דח\"ע [ד]פנימי' אבא שיורד מגבוה לנמוך ביותר דוקא ולא בכלים העליונים הרוחניים כ\"א בכלים גשמיים דוקא. וראי' לזה ממה שאנו רואים שמהות ועצם דאור החכמה שהוא בבחי' אין ממש לא יוכל לבא אמיתי[ת] אור[ה] גם בשכל והשגה דבינה הרוחני', שהרי השכל והשגה נק' לבוש מסתיר לאמיתי[ת] אור נקוד' דחכ' כי לא יוכל לקבל אור נקוד' זו דאין דחכ' בשכל ולא במדות אוי\"ר הרוחני' כ\"א בכלי לבוש",[["5680","195","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["5681","196","<b>מרחוק ה' נראה להם</b>: ע\"פ ירמי' לא, ב."],["5682","197","<b>מבחי' גבו'</b>: ביד: מגבורה."],["5683","198","<b>דקו השמאל בג\"ה</b>: נסמן לעיל פ' וארא פד, ד."],["5684","199","<b>ולהפוך חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["5685","200","<b>ולהבדיל בין טמא לטהור</b>: ע\"פ שמיני יא, מז."],["5686","201","<b>ובמ\"ע </b>[ביד: ובמצות עשה]<b> נתאוה. . דירה בתחתונים</b>: נסמן לעיל ע, ג."],["5687","202","<b>ניתנה</b>: ביד: לא נתן."],["5688","203","<b>כטבע המים. . לנמוך</b>: ראה תענית ז, א."],["5689","204","<b>מכלים שונים</b>: ביד: ליתא. וכנראה נשתרבב מלעיל שו\"ה ירידת."],["5690","205","<b>שכל הגבוה. . מטה יותר</b>: נסמן לעיל כא, ב."],["5691","206","<b>שהתורה נק' משל הקדמוני</b>: נסמן לעיל פ' שמות ח, ב."]]],[2300540476,"המעשה דוקא שהוא בחי' נה\"י בכלל, כמו שנראה בחוש שאין חכם כבעל הנסיון<sup data-n=\"5692\">207</sup> בפועל המעשה שם דוקא מתלבש נקוד' אמיתי' החכ' כמו שהיא ולא בהבנה והשגה ומדות כו'.\n[ו]<b>כך</b> בעבודת ה' אין גילוי נקודת [ד]חכ' שהוא בחי' הביטול העצמי דבחי' אין האלקי שלמעלה מ[ן] הטעם רק בכלי הלב הגשמי לאחר שנסתלק התפעלות אוי\"ר שמצד השכל, כמ\"ש בר\"מ בעין השכל שבלבא דוקא אתחזי<sup data-n=\"5693\">208</sup> וכמו ולבי ראה הרבה חכמה<sup data-n=\"5694\">209</sup> כו' וכן [ו]ב[לב] כל חכם לב<sup data-n=\"5695\">210</sup> דוקא כו' (הוא בחי' יסוד אבא שמוסתר באימא ובוקע ויוצא בחזה הלב שהוא יסוד ז\"א), וגם כלי הלב רוחני ולא ניכר ונגבל נקוד' אין דחכ' כו'<sup data-n=\"5696\">211</sup> כ\"א <span data-k=\"pg\">296</span> ּ בכלי אותיות המו\"ד להיותם בחי' אותיות וכלים מגבילים יותר מאוי\"ר שכליים וטבעיים כו', ויותר ממו\"ד האור דחכ' נגבל ו[מ]תלבש כל אמית[תו] באותיות הכתב שנק' אותיות המעשה דנתב\"ס<sup data-n=\"5697\">212</sup> דוקא, והן אותיות דתושב\"כ ותושבע\"פ שבהן מלובש פנימי' ועצמיו' דאור אבא דוקא כידוע והן ענין שתי הלחם כו', שמפני עוצם מעלת אור הח\"ע לא ישכון כ\"א בכלים התחתונים ביותר דוקא שהן כלי המעשה כמו המצות בגשמיות דוקא שהן כלים מכלים שונים להגבלת פנימיות אור אבא להיותם בדברים גשמיים [דוקא] (וראי' לזה ממ\"ש סוף דבר כו' ואת מצותיו שמור כו'<sup data-n=\"5698\">214</sup> כי זה כל האדם<sup data-n=\"5699\">213</sup> שהוא בחי' מ\"ה דח\"ע, וכ[ן] א' ויאמר לאדם הן יראת ה' היא חכ'<sup data-n=\"5700\">215</sup> כו', ו[כן] א' תכלית חכ' תשובה ומע\"ט<sup data-n=\"5701\">216</sup> שזהו תכלית עומק החכמה לאמיתי' עצמותה ממש שבלתי אפשר להתלבש למעלה כנ\"ל וכמ\"ש שכל טוב לכל עושיהם<sup data-n=\"5702\">217</sup> דוקא ולא א' ללומדיהם ב[דיבור מ]טעם הנ\"ל, וע\"כ א' שכל שמעשיו מרובים מחכ'<sup data-n=\"5703\">218</sup> חכמתו מתקיימת וא' לא המדרש עיקר<sup data-n=\"5704\">219</sup> אלא המעשה דוקא וגם מה שתלמוד גדול<sup data-n=\"5705\">220</sup> אינו אלא מפני שמביא לידי מעשה כו', וראי' ברורה יותר ממכתב אלקי' על הלוחות האחרונ[ות]<sup data-n=\"5706\">221</sup> שהי' בהם מעלה יתירה מיו\"ד הדברות<sup data-n=\"5707\">222</sup> מטעם הנ\"ל וד\"ל). וזהו שנתאווה הקב\"ה להיות לו דירה בתחתונים דוקא ולא בכלים העליונים<sup data-n=\"5708\">223</sup> הרוחניי' [לפי שפנימי' אור אבא ששם גילוי עצמות אוא\"ס ב\"ה עיקר השראתו ודירתו הוא בכלים התחתונים דוקא ולא בכלים העליונים הרוחניי'] מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> שא' ל' דירה בתחתונים<sup data-n=\"5709\">224</sup> שהדירה הוא הקביעות דוקא כאדם הדר בביתו בקביעות בתמידות ולא בדרך מעבר",[["5692","207","<b>שאין חכם כבעל הנסיון</b>: נסמן לעיל י, ד."],["5693","208","<b>בעין השכל. . אתחזי</b>: נסמן לעיל פ' וארא עט, ג."],["5694","209","<b>ולבי ראה הרבה חכמה</b>: קהלת א, טז."],["5695","210","<b>[ו]ב[לב] כל חכם לב</b>: תשא לא, ו."],["5696","211","<b>כו'</b>: ביד: בו כ\"כ."],["5697","212","<b>דנתב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["5698","214","<b>כו'</b>: ביד: ליתא."],["5699","213","<b>סוף דבר. . האדם</b>: קהלת יב, יג."],["5700","215","<b>ויאמר לאדם. . חכ'</b>: איוב כח, כח."],["5701","216","<b>תכלית חכ' תשובה ומע\"ט</b>: ברכות יז, א."],["5702","217","<b>שכל טוב לכל עושיהם</b>: תהלים קיא, י. ראה ברכות יז, א [הגי' המובא עה\"ג שם]. יל\"ש תהלים שם (רמז תתע)."],["5703","218","<b>שכל שמעשיו מרובים מחכ'</b>: אבות פ\"ג, מ\"ט (וגי' אדה\"ז בסידורו מ\"י)."],["5704","219","<b>לא המדרש עיקר</b>: אבות פ\"ג, מי\"ז (כגי' אדה\"ז בסידורו)."],["5705","220","<b>שתלמוד גדול</b>: קידושין מ, ב."],["5706","221","<b>ממכתב אלקי' על הלוחות האחרונ[ות]</b>: עקב י, ד."],["5707","222","<b>ממכתב אלקי'. . מעלה יתירה מיו\"ד הדברות</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תסה. ויקרא ח\"א ע' נא."],["5708","223","<b>בכלים העליונים</b>: ביד: בעליונים."],["5709","224","<b>דירה בתחתונים</b>: ראה גם ביאוה\"ז כאן (עב, ג). מאמרי אדה\"ז תקס\"ה כאן (ע' תלד). ע' תפט. פרשיות התורה ח\"ב ע' תקלו וע' תקמב ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' צא."]]],[2300540494,"בעלמא שנק' דירת עראי כאורח וכעובר ממקום למקום שלן או יושב בפונדקי שעה או שתים כו', להיות שגם שיש גילוי אור א\"ס ב\"ה גם בעולמות העליונים כמו גילוי שכינה במרכבה עליונה דמלאכים דבריאה ויצי' כו' אין זה רק דרך מעבר בעלמא לפי שעה לבד ולא בדרך קביעות [דירה] כלל, לפי שגם שיש בה[ם] בחי' הארה דחכ' בבחי' ביטול דשוב כנ\"ל שבזה ישכון גילוי אוא\"ס ב\"ה דוקא כנ\"ל אבל אינו מתגלה אלא לפי שעה בדרך מעבר בעלמא (כמו בשעה שאו' קדוש וברוך לבד כו' לעתים קבועים כו'), לפי שלא יוכל האור דחכמה להתיישב בקביעות כ\"א בכלים היותר חיצוני' [כ]מצות בפו\"מ והמלאכי' הם עליונים יותר מצד דקות חומר הצורה שלהם כידוע שהוא רוחני יותר מרוחני' דד\"י [ו]דצח\"מ דעוה\"ז השפל כו' (וגם לאבות שהיו מרכבה<sup data-n=\"5710\">225</sup> עליונה יותר לבחי' חג\"ת דאצי' לא [נ]גלה שם הוי' דח\"ע דתו' בעובדות שלהם במס\"נ הגם שהוא<sup data-n=\"5711\">226</sup> ממש ענין המצות שלנו ברוחני' כידוע בענין המקלות דיעקב שהן כמו תפילין<sup data-n=\"5712\">227</sup> שלנו בגשמיות ובחפירות<sup data-n=\"5713\">228</sup> שלהם<sup data-n=\"5714\">229</sup> בארות דאברהם וגמ\"ח שלו עד שא' עליהם<sup data-n=\"5715\">230</sup> עקב אשר שמע אברהם<sup data-n=\"5716\">231</sup> בקולי וישמור משמרתי מצותי כו', ועכ\"ז א' ושמי הוי'<sup data-n=\"5717\">232</sup> [ממש] לא נודעתי להם והכל מטעם הנ\"ל וד\"ל). וזהו שהשיב להם כלום גזל יש בכם כו' דעיקר ענין התו\"מ בא לברר לעה\"ד טו\"ר בפו\"מ והעיקר בסו\"מ בשס\"ה ל\"ת שהוא בי\"ה<sup data-n=\"5718\">233</sup> דשם הוי' שלמעלה מו\"ה דמ\"ע כמ\"ש במ\"א באריכות (בפ' פקודי)<sup data-n=\"5719\">234</sup>.\n<b>ובכ\"ז</b> יובן מ\"ש בזהר ע\"פ מה אדיר שמך<sup data-n=\"5720\">235</sup> כי<sup data-n=\"5721\">236</sup> אדיר לשון תוקף וחיזוק<sup data-n=\"5722\">237</sup> גדול דתביר גזיזא דבר[ד]א<sup data-n=\"5723\">238</sup> כו'. וביאור הענין הוא להיות שא' במ\"ת ואתא מרבבות קדש<sup data-n=\"5724\">239</sup> <span data-k=\"pg\">קמח</span> ּ שהן המלאכים העליונים שנק' רבבות קדש כמ\"ש רכב אלקים<sup data-n=\"5725\">240</sup> כו' אד' ב\"ם סינ\"י בקדש והוא בשעה שירד ה' על ה\"ס ליתן התורה לישראל שזהו בחי' גילוי אור פנימי' דאוא\"ס שבח\"ע לבא למטה [מטה] דוקא מטעם הנ\"ל שנתאוה כו' בכלים היותר תחתונים שבעולם העשי', אז הניח [ה'] כל העולמות [העליונים] הרוחני' ועובר עליהם בכח ותוקף גדול שלא יתגלה האור דח\"ע דתורה בהם בגילוי גמור רק במעבר בעלמא. ואע\"פ שבדרך ההשתלשלות עו\"ע הולך האור ועובר בדרך העולמות דבי\"ע כו' כי הן גבוהים יותר עד שירד למטה, עכ\"ז לא האיר עליהם מדי עברו למטה רק מבחי' הארה דהארה דהוד דתורה כמ\"ש בזהר",[["5710","225","<b>לאבות שהיו מרכבה</b>: נסמן לעיל פ' שמות ה, ג."],["5711","226","<b>שהוא</b>: ביד: שהיו."],["5712","227","<b>המקלות. . תפילין</b>: נסמן לעיל פ' וארא סג, ג."],["5713","228","<b>ובחפירות. . בארות דאברהם</b>: ראה גם לקמן פ' יתרו רסא, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשסג וע' תתנב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680127\" data-slug=\"torat-chaim\" data-id=\"2300680127\">תו\"ח וישלח קפט, ג</a> ובהערה 67."],["5714","229","<b>שלהם</b>: ביד: ליתא."],["5715","230","<b>עליהם</b>: יד: עליו."],["5716","231","<b>עקב אשר שמע אברהם</b>: תולדות כו, ה."],["5717","232","<b>ושמי הוי'</b>: נסמן לעיל פ' שמות א, ג הערה 42."],["5718","233","<b>בשס\"ה ל\"ת שהוא בי\"ה</b>: נסמן לעיל קיד, א הערה 152."],["5719","234","<b>באריכות (בפ' פקודי)</b>: לקמן תנב, ד ואילך."],["5720","235","<b>מה אדיר שמך</b>: תהלים ח, ב. י."],["5721","236","<b>כי</b>: ביד: כו'."],["5722","237","<b>וחיזוק</b>: ב: ליתא. ידיט: וחוזק."],["5723","238","<b>דתביר גזיזא דבר[ד]א</b>: במאמרי אדה\"ז תקס\"ה כאן (ע' תלד): בתקוני זהר. ראה זהר תרומה קמ, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תיד. וש\"נ."],["5724","239","<b>ואתא מרבבות קדש</b>: ברכה לג, ב. ראה מאמרי אדה\"א בראשית ע' כב בהערה."],["5725","240","<b>רכב אלקים</b>: תהלים סח, יח."]]],[2300540512,"שם, ולא נגלה עליהם מהו\"ע דח\"ע דתורה מטעם הנ\"ל שרצונו הוא<sup data-n=\"5726\">241</sup> לדור בתחתונים ולא בעליונים. וזהו מ\"ה אדי\"ר שמ\"ך שמות ואותיות דח\"ע דתו' דתבר גזיזא דבר[ד]א פי' כמ\"ש ועל ראשי החיות<sup data-n=\"5727\">242</sup> רקיע כעין הקרח הנורא דאגלידו מיא<sup data-n=\"5728\">243</sup> כו', שבהכרח שיתצמצם אור דח\"ע ונעשה כעין הקרח על השגות ראשי החיות ואם יבקע הקרח או שיפשר יתבטלו במציאות לגמרי כמו הושיט אצבעו הקטנה<sup data-n=\"5729\">244</sup> כו'. וע\"כ בשעה שעבר אור היו\"ד<sup data-n=\"5730\">245</sup> דח\"ע דתורה מדי עברו על ה\"ס תבר גזיזא דבר[ד]א שהוא הקר\"ח הנורא כי נעשה במסך זה ביטול מתוקף אור הגדול דח\"ע כו' שהוא פנימי' גילוי אוא\"ס שבח\"ע, [ו]ממילא נתבטלו המלאכים במציאות גם ממקצת אור וזיו והוד זה דתורה שעבר עליהם ולכך כלתה נפשם להוד זה וא' תנה הודך כו' בקביעות דירה, והשיבם שאין חפצו בהם בקביעות ועבר עליהם למטה דוקא, דהיינו שבקע האור עליהם במחיצה<sup data-n=\"5731\">246</sup> גדולה ובכח חזק, וזהו מה אדי\"ר שמך [כו'] דתב\"ר גזיזא<sup data-n=\"5732\">247</sup> כו' מטעם הנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן ענין הד' כוסות ויתורץ הקושי' דלעיל למה המצו[ה] ביין המשמח שהוא התפעלות [ד]רצוא דבינה שהוא היפך ענין המצה כו'. דהנה שרש המלאכי' מבחי' הגבו' דרצוא, וע\"כ תמיד או' שירה בהתכללות ועלי', ואמנם יש בהן [התכללות] מכמה מדרגות דחו\"ג כמו מלאכים שהן רק [ב]בחי' רצוא והסתלקות כמ\"ש מצמיח חציר לבהמה<sup data-n=\"5733\">248</sup> שהן אלף טורי[ן] דבהמה רבה שתת לון בגמיעא חדא, וזהו יוצר משרתים<sup data-n=\"5734\">249</sup> בכל יום ונכללים ומתבטלים בכ\"י בפי שם ב\"ן דמל' שנק' בהמה רבא כמ\"ש בזהר. ויש מלאכים שנק' עומדים [ב]בחי' שוב תמיד כמו עצי שטים עומדי'<sup data-n=\"5735\">250</sup> וכן [א'] ונתתי לך מהלכים<sup data-n=\"5736\">251</sup> בין העומדים האלה שהן מלאכים שעומדים מוימ\"ב, ויש שכלולים מרו\"ש ויש בזה רבבות אלפי[ם] מדרגות. והנה היין כלול מרו\"ש<sup data-n=\"5737\">252</sup> יחד בעלי' דרצוא בהתפעלות כלות הנפש בבחי' או\"ח וגם בחי' שוב [דחסדים מגולים] דאו\"י כמ\"ש בזהר וכמ\"ש ויין מלכות רב כיד המלך<sup data-n=\"5738\">253</sup> לבא בכלי\"ם מכלי\"ם שונים כו'. וידוע שהאדם כלול מכולם שנא' ופני אדם לארבעתן<sup data-n=\"5739\">254</sup> דכליל כולהו ע\"כ בהכרח שימצא בו מכל מדרגות המלאכים [בבחי' רו\"ש כו'. וע\"כ המצוה בד' כוסות דיין שהן לנגד ד' המדריגות] דמרכבה והאדם כלול מכולם כדי שיעבור גם עליהם מבחי' הארת אור אבא שמלובש",[["5726","241","<b>הוא</b>: ביד: דוקא."],["5727","242","<b>ועל ראשי החיות</b>: נסמן לעיל צז, ד."],["5728","243","<b>דאגלידו מיא</b>: ראה זהר לך עז, א."],["5729","244","<b>הושיט אצבעו הקטנה </b>[ביד: ליתא]: נסמן לעיל פ' שמות ל, ב."],["5730","245","<b>היו\"ד</b>: ביד: הוד."],["5731","246","<b>במחיצה</b>: ביד: במרוצה."],["5732","247","<b>גזיזא</b>: שם: ליתא."],["5733","248","<b>מצמיח חציר לבהמה </b>[ביד: ליתא]: נסמן לעיל צג, א."],["5734","249","<b>יוצר משרתים</b>: נסמן לעיל צג, א."],["5735","250","<b>עצי שטים עומדי'</b>: תרומה כו, טו. ראה זהר תרומה קמז, ב. קסט, א. קע, א."],["5736","251","<b>ונתתי לך מהלכים</b>: זכרי' ג, ז. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרסז. וש\"נ. ש\"א ח, ב הערה 42."],["5737","252","<b>היין כלול מרו\"ש</b>: ראה גם ביאוה\"ז כאן (עד, ד)."],["5738","253","<b>ויין מלכות רב כיד המלך</b>: אסתר א, ז."],["5739","254","<b>ופני אדם לארבעתן</b>: נסמן לעיל פ' שמות כח, א."]]],[2300540530,"במצה בבחי' מעבר בעלמא עכ\"פ שיוכל לעבור גם עליהם כנ\"ל, לפי שבמצרים היו כנס\"י בבחי' הקטנות שלא הי' בהם גילוי אוא\"ס ב\"ה ג\"כ רק בדרך מעבר<sup data-n=\"5740\">255</sup> <span data-k=\"pg\">298</span> ּ בלבד כמ\"ש ואעבור עליך וארא\"ך<sup data-n=\"5741\">256</sup> בהעברה בעלמא רק שזה הי' מבחי' הפנימי' ועצמי' שלו וכמ\"ש בדמייך חיי<sup data-n=\"5742\">257</sup> שיהי' כלים גמורים למ\"ת ולפי שהמצה שרש ומקור למ\"ת כנ\"ל. ומה שלא הי' רק בדרך מעבר כמ\"ש ואעבור עליך היינו לפי שעדיין לא הי'<sup data-n=\"5743\">258</sup> בחי' הרצוא דמדות דבינה עד שספרו הספירה שנעשה עי\"ז בחי' גדלות המוחי' דאבא במ\"ת כשנהפך הרצוא לשוב כנ\"ל, והוא בעמדם בה\"ס דכתיב וירא העם וינועו שאז קיבלו הגילוי דגדלות החכמה בכלים שלהם ממש, אך ביצ\"מ הי' כ\"ז בהעלם ובכח ומקור לכ\"ז הגילוי כנ\"ל בענין הדילוג כו'. וידוע שבמ\"ת ירדה גם המרכבה העליונה למטה כמ\"ש וירד ה'<sup data-n=\"5744\">259</sup> כו' וע\"כ צריך לשתות הד' כוסות דיין שיהי' גם ע\"י<sup data-n=\"5745\">260</sup> המלאכים מבחי' אור אבא שבהעלם בדרך מעבר עכ\"פ כדי שיהי' גילוי אור דח\"ע [דתורה] גם בהן בירידתן במ\"ת, לפי שכל ענין המצות דפסח במצה [ויין] הכל הכנה רב[ה] למ\"ת דוקא לבא מן ההעלם אל הגילוי כנ\"ל בענין קטנות דאבא שבמצה שמביא לידי בחי' גדלות דאבא במ\"ת מטעם המבואר למעלה וד\"ל.\n<b>והנה</b> להבין כל הנ\"ל בתוס' ביאור, יש להקדים תחלה בשרש ענין יו\"ט דפסח שיש [בו] יתרון מעלה על שאר היו\"ט אע\"פ שנק' מקראי קדש<sup data-n=\"5746\">261</sup> והוא ע\"י מצות המצה דוקא. דהנה בכל יו\"ט שנק' מקרא קדש היינו שהוא בבחי' מוחי' דאימא בלבד רק שמקבל מבחי' אור אבא בדרך יחוד דאו\"א שזהו רק תוס' אור חדש ממוחי' דאבא שנק' קדש שבא בשפע דבחי' נה\"י דאבא בנה\"י דאימא ולא ממהו\"ע דאור אבא כלל וכלל<sup data-n=\"5747\">262</sup>, וגם השבת עצמו שנק' קדש כמ\"ש ושמרתם את [ה]שבת<sup data-n=\"5748\">263</sup> כי קדש היא לכם אין זה ממהו\"ע דאבא כו'. וביאור הענין ידוע שגם בחול יש יחוד או\"א וכמ\"ש דאו\"א זיווגייהו תדיר ונק' תרדל\"מ<sup data-n=\"5749\">264</sup> לעלמין כו' רק שהוא חיצוני' השפע, והענין הוא כידוע שהחכ' נק' אין והבינה נק' יש<sup data-n=\"5750\">265</sup> ושפע זו דחו\"ב מאין ליש תמידית היא כמשל מעין הנובע בנהר שא\"א לנהר בלא מעיין כך א\"א להשגת והבנת השכל בלא מקור הנובע [שהוא נביעת הברקת אור החכ' מבחי' אין ליש בתמידות בכל רגע ממש וכאשר נפסק המקור הנובע] את השכל ממילא אין מציאות שכל מושכל בהשגה כלל. וכך יובן בענין יחוד דחו\"ב למעלה שנק' תרדל\"מ כו' שא\"א",[["5740","255","<b>מעבר</b>: בתו\"ח כאן באים עוה\"פ התיבות (דלעיל שבשו\"ה במצה) בעלמא. . בדרך מעבר."],["5741","256","<b>ואעבור עליך וארא\"ך</b>: יחזקאל טז, ו."],["5742","257","<b>בדמייך חיי</b>: יחזקאל שם."],["5743","258","<b>שעדיין לא הי'</b>: ביד: שלא הי' בהם עדיין."],["5744","259","<b>וירד ה'</b>: יתרו יט, כ. ראה גם לקמן פ' תרומה שטו, ב. וש\"נ. ש\"א צא, א."],["5745","260","<b>ע\"י</b>: ביד: על."],["5746","261","<b>יו\"ט שנק' מקרא קדש. . השבת. . קדש</b>: ראה זהר אמור צד, א. סידור שער המועדים ריז, א. שעה\"י קכח, א ובהערה 12."],["5747","262","<b>וכלל</b>: ביד: ליתא."],["5748","263","<b>ושמרתם את השבת</b>: תשא לא, יד."],["5749","264","<b>תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["5750","265","<b>שהחכ' נק' אין והבינה נק' יש</b>: ראה גם לעיל קא, ג. וש\"נ."]]],[2300540548,"למציאות יש דבינה בלא שפע אין דחכמה אפי' רגע א' והלא<sup data-n=\"5751\">266</sup> ענין יחוד דחו\"ב בכל ימי החול בכל יום שנק' [חידוש] מע\"ב, [דבראשית] הוא בחי' אין דחכמה ומע\"ב הוא מה שנמשך לבינה כמ\"ש בראשית [ד]חכמה ברא אלקי'<sup data-n=\"5752\">267</sup> בחי' בינה דאבא א' לאימא<sup data-n=\"5753\">268</sup> כאומן המצווה לעשות כו', וחידוש זה מאי\"ן לי\"ש בחו\"ב הוא מקור כל שפע די' מאמרות בדבור בכל יום ויום [ממש] כמו שאו' מחדש בכל יום מע\"ב<sup data-n=\"5754\">269</sup> כמ\"ש כולם בחכ' עשית בבינה<sup data-n=\"5755\">270</sup> כו' וזהו ברוך אומר ועושה<sup data-n=\"5756\">271</sup> בתמידות דוקא וד\"ל (ואם נפסקה<sup data-n=\"5757\">272</sup> הארת המשכיל בשכל והשגה דבינה ממילא נפסק אור החכמה<sup data-n=\"5758\">273</sup> המח' והדבור וא\"כ ודאי יש הארת אור אבא באימא בכל צירופי אותיות מו\"ד דמע\"ב בכ\"י). אמנם הנה אין הארה זו מחכמה לבינה בכל ימי החול רק מבחי' התחתונה לבד<sup data-n=\"5759\">274</sup> אע\"פ שמ[ת]חדש בכ\"י, והוא רק <span data-k=\"pg\">קמט</span> ּ מבחי' אותיות שבה שנק' חיצוני' ואחוריי' כידוע בכל עו\"ע משפיע ומקבל, והוא רק כמו הברקת אור החכמה כטיפה שנובעת מן המעיין ומשפיע<sup data-n=\"5760\">275</sup> בנהר אבל עיקר החכמה נשאר בהעלם בעצמו ונק' מעיין סתום כו'. אך בשבת מאיר מבחי' העלם דאור אבא בפנימיות שבנה\"י דהיינו מבחי' אין דחכמה כמו שהוא טרם שבא לגילוי בבינה מאין ליש בהשגה כו' והוא הנק' קדש מלה בגרמי'<sup data-n=\"5761\">276</sup> כו', והטעם הוא לפי שבו שבת מכל מלאכתו<sup data-n=\"5762\">277</sup> שהוא בחי' או\"ח דמע\"ב [בכלל] כמשל של הכח מיגיעו חוזר<sup data-n=\"5763\">278</sup> למקור הראשון שהוא העלם אין דחכמה כמו שהיא טרם ירידתה בבינה כו' ונמצא בחי' בינה כלול בחכ'. וביו\"ט הגם שהוא ביומין דחול נק' מקרא קד\"ש העליון דאבא לפי שמאיר בבינה מאין דחכ' הנעלם שנק' קדש ממש ולכך נק' מקרא קד\"ש דזמי[ני]ן מקדש העליון כו' (כמ\"ש בזהר והובא באורך<sup data-n=\"5764\">279</sup> בסידור<sup data-n=\"5765\">280</sup> ). אמנם ג\"ז אע\"פ שהוא למעלה מיחוד חיצוני' דאו\"א בחול בחידוש מע\"ב מ\"מ אינו בא רק בדרך קריאת שם בעלמא מקדש העליון דחכ', ואף גם בשבת עצמו שנק' קדש ממש היינו רק לגבי שפע דאין דחכמה שנמשך לבינה בגילוי ממש כמו בחול נק' העלם אבל [אין] זה מהו\"ע דחכ' כמו שהיא במקורה באין ממש כמ\"ש והחכמה מאין תמצא<sup data-n=\"5766\">281</sup> [מ]אין ממש (עד\"מ מעיינות תהום כמ\"ש במ\"א) שהוא פנימי' הכתר (שנק' כשב\"כ<sup data-n=\"5767\">*282</sup> כמ\"ש בע\"ח הכלל דפנימי' אבא הוא פנימי' ע\"י<sup data-n=\"5768\">282</sup> ממש, משא\"כ חכ'<sup data-n=\"5769\">283</sup> שנק' חכמה שבכתר בא לידי גילוי גם בשבת כמ\"ש וקראת לשבת ענג<sup data-n=\"5770\">284</sup> כו' שהוא בחי' ירידת דאו\"י אחר העלאה דאו\"ח כמשל מים העליונים<sup data-n=\"5771\">285</sup> למקור חוצבם כו' כידוע) והוא בחי' ג\"ר דאבא שאינו נמשך לבינה כלל, וכמו ענין",[["5751","266","<b>א' והלא</b>: ביד: והוא."],["5752","267","<b>בראשית. . ברא אלקי'</b>: בראשית א, א."],["5753","268","<b>דאבא א' לאימא</b>: נסמן לעיל פ' שמות יח, ד."],["5754","269","<b>מחדש בכל יום מע\"ב</b>: ע\"פ ברכת יוצר."],["5755","270","<b>כולם בחכ' עשית בבינה</b>: תהלים קד, כד. זהר תזריע מג, א."],["5756","271","<b>ברוך אומר ועושה</b>: נוסח ברוך שאמר. ראה גם לקמן פ' יתרו רנב, ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתכא."],["5757","272","<b>נפסקה</b>: ביד: יופסק."],["5758","273","<b>החכמה</b>: שם: ליתא."],["5759","274","<b>לבד</b>: ב: שלה לבד. ידיט: שבה לבד."],["5760","275","<b>ומשפיע</b>: ביד: ומתפשט."],["5761","276","<b>קדש מלה בגרמי'</b>: זהר אמור צד, ב. ראה גם לקמן פ' בשלח רי, א. ריז, ב."],["5762","277","<b>שבו שבת מכל מלאכתו</b>: בראשית ב, ג."],["5763","278","<b>של הכח מיגיעו חוזר</b>: ביד: הנח מיגיעת שכלו שחוזר."],["5764","279","<b>באורך</b>: ביד: ביאורו."],["5765","280","<b>בזהר. . בסידור</b>: שבהערה 261."],["5766","281","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["5767","*282","<b>פנימי' הכתר. . כשב\"כ</b>: ראה גם מאמרי אדה\"א בראשית ע' לז."],["5768","282","<b>דפנימי' אבא. . ע\"י</b>: נסמן לעיל פ' שמות כג, א."],["5769","283","<b>חכ'</b>: ביד: ח\"ס."],["5770","284","<b>וקראת לשבת ענג</b>: ישעי' נח, יג."],["5771","285","<b>העליונים</b>: ביד: העולים."]]],[2300540565,"שמן צף ע\"ג היין<sup data-n=\"5772\">286</sup> בלתי יש חיבור ביניהם כלל כמ\"ש במ\"א [וד\"ל].\n<b>ובזה</b> יובן יתרון מעלת יו\"ט דפסח ע\"י המצה על שאר יו\"ט וגם על [ה]שבת שנק' קדש עצמו, דהנה עיקר בחי' יו\"ט הוא הנקרא מקרא קדש והיינו רק מבחי' נה\"י דאבא באימא לבד, אבל בחי' ג\"ר דאבא גם בשבת עצמו הוא בהעלם אעפ\"י שעיקר מצוה<sup data-n=\"5773\">287</sup> בשבת הוא העונג ולא השמחה כמו ביו\"ט<sup data-n=\"5774\">288</sup> לפי שהשמחה הוא בבינה כמ\"ש אם הבנים שמחה<sup data-n=\"5775\">289</sup> וכמ\"ש ושמחת בחגיך<sup data-n=\"5776\">290</sup> כידוע ובשבת הוא העונג שבחכ' שבא בהתלבשות בסעודות השבת בעונג גשמי (אעפ\"י שאינו מגשם כ\"כ כמ\"ש פר\"ש חגיכם ולא פרש שבתכם<sup data-n=\"5777\">291</sup> ), אבל הפנימי' העונג שבג\"ר דאבא מוסתר ונעלם גם בשבת רק ליום שכולו שבת<sup data-n=\"5778\">292</sup> שהוא העוה\"ב שנק' עדן כו'. אך בזה יש יתרון מעלת יו\"ט דפסח על שבת ויו\"ט ע\"י המצה שבה התלבשות מג\"ר דאבא ממש שהוא פנימי' ע\"י כמו לע\"ל ממש, שהרי בכל יו\"ט אין המשכה דאור אבא באימא שיהי' נק' מקרא קדש כ\"א ע\"י מצות דרבנן לבד כמו התפלות<sup data-n=\"5779\">293</sup> וה[ה]לל<sup data-n=\"5780\">294</sup> שהן מדרבנן (וע\"י קידוש דיין שהוא מדאורייתא היינו בשבת<sup data-n=\"5781\">295</sup> דכתי' בי' [זכור את כו'] זכרהו על היין<sup data-n=\"5782\">296</sup> להמשיך מוחין דאבא על היין דאימא כו', אבל בקידוש על היין דיו\"ט הוא מבחי' מוחי' דאימא<sup data-n=\"5783\">297</sup> לבד ומוחי' דאבא הוא בהעלם עד ההלל ומוסף). אבל ביו\"ט <span data-k=\"pg\">300</span> ּ דפסח בא המשכות דמוחי' העצמי' דאבא באימא ע\"י אכילת מצה שהיא דאורייתא [(ו]כידוע [דאורייתא] מח\"ע [ממש] נפקת משא\"כ מצות דרבנן שהוא בחכ' [תתאה] דמל'). אך התלבשות זאת ד[מ]הו\"ע דאבא באה במצה בהעלם וקטנות מאד מאד כנ\"ל והוא רק בקטנות דנה\"י דאבא בחי' מל' דמל' וע\"כ נק' לחם עוני<sup data-n=\"5784\">298</sup> כו', ואע\"פ שידוע שהלחם הוא [בחכ']<sup data-n=\"5785\">299</sup> בג\"ר שבה בהעלם עכ\"פ והוא הטעם מה שאין התינוק יודע לקרות או\"א עד שיטעום טעם לחם דדגן דוקא. אך הלא ידועי' זאת<sup data-n=\"5786\">300</sup> אצלו למעלה מן ההשגה שכלי' רק הכרה בעלמא אבל מלובש בזה ממהו\"ע דאבא דוקא כנ\"ל באריכות שזהו הנק' בחי' קטנות דאבא שהוא רק מל' דאבא, ולזה נק' מיכלא דמהימנותא דוקא שהאמונה היא בבחי' המל' כידוע דאיהו אמת ואיהי אמונה כו'. ופי' מל' דאבא היינו רק בחי' אותיות דחכמה העצמי' (שלמעלה מאותיות דאבא באותיות הדבור דאבא יסד ברתא<sup data-n=\"5787\">301</sup>",[["5772","286","<b>שמן צף ע\"ג היין</b>: ראה שבת ה, ב. מאמרי אדה\"א דברים ח\"א ס\"ע רמה ואילך. הנסמן במ\"מ לשה\"א צב, ב הערה 12. לקמן פ' בשלח קפט, ד. תצוה שמז, ב. שסז, ג."],["5773","287","<b>מצוה</b>: ב: ליתא."],["5774","288","<b>בשבת הוא העונג. . השמחה כמו ביו\"ט</b>: ראה שו\"ע אדה\"ז הל' שבת ר\"ס רמב. הל' יו\"ט סתקכ\"ט. לקו\"ש דברים כרך ד ע' 1090 הערה 31. מאמרי אדה\"א במדבר ח\"ג ע' תתקסד ואילך."],["5775","289","<b>אם הבנים שמחה</b>: נסמן לעיל פ' וארא פה, ג."],["5776","290","<b>ושמחת בחגיך</b>: פ' ראה טז, יד."],["5777","291","<b>פר\"ש חגיכם ולא פרש שבתכם</b>: מלאכי ב, ג. ראה זהר יתרו פח, ב. לקמן קכז, א. פ' ויקהל תיח, ד. תכב, א. סידור סדר סעודת שבת רא, ב. רג, ג. מאמרי אדה\"א דברים ח\"ג ע' א'קיח. וש\"נ. שמות ח\"א ע' קפה. וש\"נ."],["5778","292","<b>ליום שכולו שבת</b>: תמיד בסופה."],["5779","293","<b>התפלות. . מדרבנן</b>: ראה שו\"ע אדה\"ז הל' תפלה סק\"ו, ס\"ב. מאמרי אדה\"א בראשית ע' תקנב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670401\" data-slug=\"torat-chaim\" data-id=\"2300670401\">תו\"ח נח נג, א</a> הערה 3. לקמן פ' משפטים רפ, ד. רפה, ד. מכתב י\"ט אייר תרצ\"ט להר\"י פייגין (נדפס ברשימות לפ' עקב חוב' קנח)."],["5780","294","<b>וה[ה]לל. . מדרבנן</b>: ראה שו\"ע אדה\"ז הל' פסח סתפ\"ח, ס\"ב."],["5781","295","<b>קידוש דיין. . מדאורייתא. . בשבת</b>: ראה תוד\"ה זוכרהו פסחים קו, א. מלחמות ה' ספ\"ג דשבועות. ר\"ן לשבת כג, ב ד\"ה אמר רבא (בתר דבעיא). רש\"י (ריב\"ן) נזיר ד, רע\"א. רוקח הל' שבת סנ\"ב."],["5782","296","<b>זכור את. . זכרהו על היין</b>: יתרו כ, ח. פסחים קו, א. ראה גם לעיל קי, ב. וש\"נ."],["5783","297","<b>בקידוש על היין. . מוחי' דאימא</b>: ראה גם לעיל קי, ב. וש\"נ."],["5784","298","<b>לחם עוני</b>: ביד: לחמא עניא."],["5785","299","<b>שהלחם הוא [בחכ']</b>: נסמן לעיל צג, ב."],["5786","300","<b>ידועי' זאת</b>: ביד: ידיעה זו."],["5787","301","<b>דאבא יסד ברתא</b>: נסמן לעיל פ' שמות מז, ב."]]],[2300540581,"שהרי התינוק יודע לצרף אותיות מעט בדיבור גם טרם שיטעם טעם לחם גם בימי יניקתו וא[ין יכול] לקרות אבא [בהכרה] עד שיטעום טעם דגן כו'), וע\"כ אין במצה טעם מורגש [כלל] כי הטעמים דלחם הוא בטעמים שבחכמה כחיך יטעום אוכל גשמי כך יטעום טעם רוחני' השכל וחכ' כמו טוב טעם ודעת למדני<sup data-n=\"5788\">302</sup> כו' וזהו באו\"כ<sup data-n=\"5789\">303</sup> שבחכ' או חו\"ב שבכת\"ר כו'. אבל שרש המצה בלמעלה מן הטעם שבחכמה כתינוק שגם בטעמו טעם דגן אינו מרגיש הטעם [ד]לחם כלל בהבחנה טובה כגדול, והמצה גם בגדול האוכלה במצות אכילתה בפסח אינו מרגיש בה טעם לחם כמו התינוק כשאוכל לחם ממש שטעם לחם אצלו בבחי' קטנות מאד. וכמו\"כ המצה שאין בה טעם גם בגדול כו' נק' לחם עני שלמטה מן הדעת ושרשה בלמעלה מן הדעת שבחכ' (שיתגלה לע\"ל וע\"כ נא' ולא ילמדו עוד כו'<sup data-n=\"5790\">304</sup> שלמעלה מאולפנא ולימוד דחכ' בבינה ולמעלה גם מפל\"א שנהפ\"ך לאל\"ף<sup data-n=\"5791\">305</sup> שנק' ח\"ס כו' כנ\"ל ע\"כ כולם ידעו אותי פי' שיכירו אותי ממש מה שעכשיו למתב\"כ<sup data-n=\"5792\">306</sup> וז\"ש איהו אמת ואיהי אמונה כנ\"ל וד\"ל). והטעם לכ\"ז הוא מפני שבפסח הי' בחי' הדילוג הגדול ממהו\"ע אוא\"ס [ב\"ה] שבפנימי' ע\"י וא[ב]א כו' כנ\"ל, ולהיות כן הי' מן ההכרח שיתלבש בבחי' הקטנות ביותר דמצה שהיא [ה]אמונה הפשוטה כי זהו הכלל כל הגבוה גבוה ביותר כשיורד למטה מתלבש בלבוש היותר נמוך דוקא כנ\"ל באריכות. וזהו עיקר הטעם למצות המצה שאין בה התנשאות והגבהה דמדות ולא טעם דשכל רק כמו בחי' דומם בעלמא כו', משא\"כ שאר יו\"ט שההתלבשו' הוא בתפלה וההלל בקריאה בדיבור בכוונה שהן יותר גבוהים במדריגה, והוא לפי שהתלבשות [ד]אור אבא באימא בשאר יו\"ט הוא רק מבחי' נה\"י דאבא לבד כנ\"ל בענין מקרא קדש וד\"ל (ומה שאו' הלל והגדה על ד' כוסות הכל הוא רק בענין זה דיצ\"מ [שיצאו] מאפילה לאור גדול<sup data-n=\"5793\">307</sup> בבחי' הקטנות דאמונה כמ\"ש עבדים היינו<sup data-n=\"5794\">308</sup> לפרעה [במצרים] ויוציאנו ה' כו' כמ\"ש בכוונות בסידור).\n<b>ובכל</b> הנ\"ל יובן מ\"ש והי' כי יביאך ה' אל ארץ הכנעני כו' ועבדת את העבודה הזאת עד מצות יאכל את שבעת הימים, וי\"ל מהו יאכל ל' פועל יוצא כו', <span data-k=\"pg\">קנ</span> ּ דהנה מבואר למעלה דליל א' דפסח הי' בחי' הדילוג ממהו\"ע דאוא\"ס ב\"ה",[["5788","302","<b>טוב טעם ודעת למדני</b>: תהלים קיט, סו."],["5789","303","<b>באו\"כ</b>: ביד: בחו\"ב."],["5790","304","<b>כו'</b>: ב: איש את רעהו כו'. וראה לעיל קיח, ג."],["5791","305","<b>מפל\"א שנהפ\"ך לאל\"ף</b>: נסמן לעיל פ' וארא עח, ב."],["5792","306","<b>למתב\"כ</b>: ראה ת\"ז בהקדמה (יז, א)."],["5793","307","<b>מאפילה לאור גדול</b>: פסחים קטז, ב (במשנה). הגש\"פ פיסקא לפיכך."],["5794","308","<b>עבדים היינו</b>: הגש\"פ. ואתחנן ו, כא."]]],[2300540597,"שבעצמות אור אבא בדרך כלל[ות] דוקא ואח\"כ ירד ונמשך מבחי' אור זה ממש בדרך פרטי' בכל ז' הימים להאיר בכל יום ויום מז' הימים, וז' הימים הללו הן בחי' ז\"מ<sup data-n=\"5795\">*309</sup> [דחכ' שהן ז' מדות] דאבא עצמו שהוא בספירה דשבוע הראשונה, כי הגם שמ\"ט ימים הללו שכללותן [הן] ז' שבועות הן נש\"ב דוקא כידוע, אבל בשבוע הא' הן כללות כל השפע דאור אבא באימא שבכל ימי הספי' יום [ה]א' הוא חסד שבחכמה ויום הב' גבו' שבחכמה עד יום הז' מל' דאבא כי בז' הימים דשבוע הא' נכנסי' מוחי' דעצמות אבא באימא בתחלה ואח\"כ נמשך מז' הימים האלה לשאר המדות שבבינה בשארי השבועות (ולא יקשה דא\"כ לא נשאר למספר ימי הספי' דמדות דבינה רק ששה שבועות לבד וחסר בה [מדת] ספי' החסד, הענין הוא דבחי' החסד דשבוע הא' דבינה כלול במדות החסד דאבא בכל פרטי ז' המדות שבה חסד שבחסד גבו' שבחסד כו' כדי להאיר בגילוי בכל המדות דבינה כו' וד\"ל). וזהו מ\"ש מצות יאכל ל' פועל יוצא שיאכילו לז' [ה]ימים הראשונים האלה מצות<sup data-n=\"5796\">**309</sup> מעצמות אור אבא שמהם וע\"י יושפע אור אבא לשאר השבועות דמדות דאימא, לפי שבהם צריך שיכנסו מוחי' העצמי' דאבא תחלה [ואח\"כ] כאשר ניזונים תחלה יהי' נמשך, [ונמשך] מהם למדות דבינה [ב]כל פרטי הימים שבימי הספי' מטעם הנ\"ל [במצה] וד\"ל.\n<b>והנה</b> מעתה י\"ל מה שבפסח מצרים לא נצטוו לאכול מצה ז' ימים רק בביאתם לארץ דוקא, וכמ\"ש והי' כי יביאך אל ארץ כו' ז' ימים תאכלו<sup data-n=\"5797\">309</sup> מצות כו' עד מצות יאכל כו' משמע כי יבואו אל הארץ דוקא מצוה לאכול ז' ימים ו[ב]פסח מצרים לא הי' עיקר המצוה רק יום א'<sup data-n=\"5798\">310</sup> בלבד ומצות מצה ז' [ה]ימים אינו אלא לדורות [לבד] כו'. אך הנה באמת לפי הנ\"ל במצות יאכל [את] ז' הימים שהן ז\"מ דאבא הרי יום א' דפסח הוא בבחי' החסד דאבא כנ\"ל, והרי הטעם הוא בזה כ[ד]י שיומשך בשבוע הא' במדות דאבא תחילה ומהם יומשך למדות דבינה בשאר הימים כנ\"ל, וזהו פלא לכאורה הרי<sup data-n=\"5799\">311</sup> יום הא' אינו בכלל [מנין] ימי הספי' כלל שהרי הספי' מתחיל בליל ב' דפסח שהוא התחלת שבוע הא' ואיך א' ז' ימים תאכל מצות, מצות יאכל את ז' הימים דקאי על יום א' דפסח עד יום הז'. וצ\"ל דעיקר המצוה דמצה הוא בליל יום א' דפסח שלפני הספי' [ד]שבוע הא' דוקא מפני שאז הוא עיקר התלבשות כללי' דמהו\"ע דאבא למטה במצה שהוא בחי' קטנות דאבא כנ\"ל, ומזה דוקא נמשך פרטי התחלקות ההמשכות דבחי' מוחי' דאבא בשבוע הא' מליל ב' דפסח ואילך,",[["5795","*309","<b>וז' הימים. . ז\"מ</b>: ראה גם לקמן פ' פקודי תמד, ד. תנח, ב. לקו\"ת שם ה, ב."],["5796","**309","<b>שיאכילו לז' [ה]ימים. . מצות</b>: ראה לקמן פ' פקודי תמה, א. וש\"נ. תנח, ב."],["5797","309","<b>תאכלו</b>: יד: תאכל. וראה להלן הערה 347."],["5798","310","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380123\" data-slug=\"likkutei-torah\" data-id=\"4001380123\">המצוה רק יום א</a>'</b>: ראה גם לקו\"ת צו יא, רע\"ד."],["5799","311","<b>הרי</b>: ביד: דהלא."]]],[2300540612,"שיום הא' דשבוע זו הוא בחי' חסד שבחכ' ויום הב' גבו' שבחכמה עד מל' דחכ' ביום הז' לספירה דוקא שהוא יום הח' לאכילת מצה בליל א' דפסח, ולפ\"ז יוקשה יותר איך א' ז' ימים תאכל שזהו רק עד יום ו' לספירה דשבוע הא' והל\"ל ח' ימים<sup data-n=\"5800\">312</sup> תאכל כו'. אלא ודאי מכאן מוכח דציווי [זה] דז' ימים לדורות קאי<sup data-n=\"5801\">313</sup>, משום ד[ב]פסח מצרים לא הי' [ה]ציווי דמצה רק על יום א' דפסח, ולדורות ג\"כ אין מצוה וחובה לאכול מצות כל ז' הימים אלא רשות כמו שא' מה שביעי רשות<sup data-n=\"5802\">314</sup> כו', רק לענין המשכות בחי' מוחי' דאבא בכל ימי הספי' הוא שאו' מצות יאכל ז' הימים והן<sup data-n=\"5803\">315</sup> ז' הימים דשבוע הא' דספי' יאכל מאכילת מצה דליל א' דפסח להיות בחי' המשכ[ה] כללית <span data-k=\"pg\">302</span> ּ שמתחלק ממנו לפרטים כנ\"ל וד\"ל.\n<b>ושרש</b> הענין הוא לפי שביום א' דפסח נמשך מבחי' מקיף דחסד הכללי דאבא והוא בחי' רב חסד דע\"י דבי' אחיד אבא<sup data-n=\"5804\">316</sup> שהוא מקור החסדי' שבבחי' מקי[פי'] דוקא והוא ענין ענני כבוד כידוע, וכמ\"ש וענן ה' יומם<sup data-n=\"5805\">317</sup> במ\"ם כפולה כמו יומם יצוה ה' חסדו<sup data-n=\"5806\">318</sup> שהוא בחי' המקיף דחסד הכללי שכולל ז' המקיפים דז\"מ דחכמה הבאים בפרטות בבחי' או\"פ כו'. וזהו ענין יום הא' דפסח [שהוא] יום שיצאו ממצרים וענן ה' עליהם שהוא בחי' מקיף דחסד עליון דאבא הכללי, וע\"ז א' מצות יאכל את ז' הימים שיאכל [לשון] ממילא, שממילא נמשך ממנו בחי' המוחי' דאבא בכל ז' הימים דשבוע הא' דספי' שבא בהתחלקות בז\"מ [דאבא]. אבל מ\"ש תחילה ז' ימים תאכל מצות קאי על ז' ימי דפסח כפשוטו שע\"ז א' תאכל ולא יאכל שהוא מצות מצה ז' ימים לדורות אעפ\"י שבפסח מצרים לא הי' חובה ומצוה רק על<sup data-n=\"5807\">319</sup> יום הא' כנ\"ל וד\"ל. וביאור ענין המקיף הזה דחסד שהוא שרש ענין ענני כבוד כו' הוא האור העליון שא\"א שיבא בגילוי או\"פ בכלי רק מקיף וסובב מבחוץ עליהם להגן ולשמור מן החיצונים, וכמו שהי' ענן ה' שהי' הולך לפניהם דכתי' וה' הולך לפניהם<sup data-n=\"5808\">320</sup> יומם בעמוד ענן כו' וכתיב ויסע עמוד הענן<sup data-n=\"5809\">321</sup> מפניהם ויעמוד מאחריהם לקבל אבנים ובליסטראות דמצרים כו' הרי הי' להם למגן ולמחסה מפני מצרים, וכך הי' בענני כבוד שבמדבר שהי' או\"מ זה מבער הקליפו'<sup data-n=\"5810\">322</sup> דנחה\"ק<sup data-n=\"5811\">323</sup> ועקרב כו' כי זהו בכח המקי[פי'] דוקא (שמסמא עיני החיצונים<sup data-n=\"5812\">324</sup> כי לא יוכלו להסתכל באו\"מ כמ\"ש בענין התכלת<sup data-n=\"5813\">325</sup> שבציצית), וגם כאן במקיף זה דחסד עליון דאבא שביום א' דפסח נשמרו מאליו<sup data-n=\"5814\">326</sup> מיניקת החיצונים וכמ\"ש ליל שמורים הוא לה'<sup data-n=\"5815\">327</sup> כו'. ומזה הטעם לא הי' פסח",[["5800","312","<b>ח' ימים</b>: בתו\"ח נכפלו ב' תיבות אלו."],["5801","313","<b>קאי</b>: ביד: קא'. יט: קאמר."],["5802","314","<b>מה שביעי רשות</b>: פסחים קכ, א. מכילתא ורש\"י בא יב, טו. שו\"ע אדה\"ז הל' פסח סתע\"ה, סל\"ב."],["5803","315","<b>והן</b>: ביד: וה\"ק."],["5804","316","<b>רב חסד. . אבא</b>: ראה ע\"ח (שער או\"א) שי\"ד, פ\"א."],["5805","317","<b>וענן ה' יומם</b>: בהעלותך י, לד [בדילוג]. ראה מאמרי אדה\"א דברים ח\"ג ס\"ע א'לה וריש ע' א'לו. וש\"נ."],["5806","318","<b>יומם יצוה ה' חסדו</b>: תהלים מב, ט."],["5807","319","<b>על</b>: ביד: ליתא."],["5808","320","<b>וה' הולך לפניהם</b>: בשלח יג, כא."],["5809","321","<b>ויסע עמוד הענן</b>: בשלח יד, יט. ראה מכילתא בשלח יד, כ. הנסמן במאמרי אדה\"א קונטרסים ע' תלד."],["5810","322","<b>בענני כבוד. . מבער הקליפו'</b>: מכילתא בשלח יג, כא. ספרי ורש\"י בהעלותך י, לד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181266\" data-slug=\"likkutei-sichot\" data-id=\"1300181266\">לקו\"ש</a> חוקת (כרך יח) ע' 257."],["5811","323","<b>דנחה\"ק</b>: ביד: נחש."],["5812","324","<b>המקי[פי']. . שמסמא עיני החיצונים</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פי\"ג."],["5813","325","<b>שמסמא. . התכלת</b>: נסמן לעיל פ' שמות לא, ג."],["5814","326","<b>מאליו</b>: ביד: ממילא."],["5815","327","<b>ליל שמורים הוא לה'</b>: בא יב, מב."]]],[2300540626,"מצרים נוהג איסור חמץ רק מצד קרבן פסח יום א'<sup data-n=\"5816\">328</sup> לבד ובשאר הימים לולי טעם כי גורשו ממצרים<sup data-n=\"5817\">329</sup> ויאפו את הבצק עוגות מצות<sup data-n=\"5818\">330</sup> היו מותרים בחמץ לבד יום הא' שה[י'] חובה, [ו]מ\"ש כי כל אוכל חמץ<sup data-n=\"5819\">331</sup> ונכרתה הנפש ההיא מיום הא' עד יום הז' היינו לדורות דוקא, לפי שטעם איסור חמץ בפסח ידוע מפני שיש בו מקום ושרש ליניקת החיצונים<sup data-n=\"5820\">332</sup> לקבל מפסולת הגבו' הקשות שנפל מז' מדות דקדושה כו', אבל בפסח מצרים שהי' גילוי שכינה עליהם בליל א' בבחי' מקיף דח\"ע הנ\"ל היו נשמרים ממילא מכל יניקת החיצונים שלא קרבו אליהם כלל כי אין מקום ושרש לחיצוני' שם כלל, רק ביום א' שהיו צריכים להמשכת אור אבא היו מוזהרים בחמץ שלא יוכלו לבא למטה כ\"א בביעור החמץ וכמ\"ש אך ביום הראשון<sup data-n=\"5821\">333</sup> תשביתו שאור כו' ורק מטעם דגורשו ממצרים כו' ולא הספיק להחמיץ כו' [נאסרו גם הם בחמץ כל ז' הימים כמ\"ש בסוף הפ' כי כל אוכל מחמצת<sup data-n=\"5822\">334</sup> כו' דמשמע שאם הי' סיפוק להחמיץ היו אוכלים חמץ כו'], משא\"כ עכשיו דגם שאין חובה במצות מצה בשאר הימים גם עכשיו רק בלילה הראשונה<sup data-n=\"5823\">335</sup> כידוע אבל איסור חמץ נוהג כל ז' הימים לדורות מטעם יניקת החיצונים, אבל בפסח מצרים לא הי' האיסור רק מפני שגורשו כו' ולא הספיק להחמיץ בלבד וד\"ל.\n<b>ועיקר</b> הענין הוא מצד שהי' אז גילוי אור המקיף דח\"ע כנ\"ל ביום הא' שכולל כל <span data-k=\"pg\">קנא</span> ּ הימים הבאים אחריו כנ\"ל ע\"כ גם בשאר הימים לא יוכלו החיצונים לקבל יניקה שם אעפ\"י שבהם בא האור בהתחלקות בבחי' או\"פ (ועכ\"ז גם הם היו צריכים למצות הספירה<sup data-n=\"5824\">336</sup> לברר לז\"מ דק\"נ שמקבלים מאחוריים דז\"מ דבינה דקדושה כדי שיוכלו לעמוד במ\"ת פב\"פ בהזדככות מק\"נ שהי' בהם מעה\"ד כו', ואדרבה ע\"י המשכת מוחי' דאבא בבינה נבררו כנ\"ל). אבל לדורות שלא יש גילוי אור הגדול מקיף הכללי [ה]זה בליל א' להאיר בשאר הימים ע\"כ יכולים גם החיצונים לקבל יניקה מאכילת חמץ בשאר הימים (ואע\"פ שמצות הספירה נוהגת גם עכשיו ויש בשבוע הא' דספי' מאור אבא כנ\"ל, ה\"ז בא רק בגילוי אור בעלמא בבחי' או\"פ ולא בא מכח אור המקיף דיום הא' רק בבחי' [ה]העלם, משא\"כ בפסח מצרים שנכלל[ו] כל שאר הימים ביום הא' שהי' המקיף בגילוי וד\"ל). וזהו והי' כי יביאך אל ארץ כו' ז' ימים תאכל מצות שהוא מצות ז' לדורות ולא בזמן דפסח [מצרים] שכלולים במצה דיום הא' ע\"כ די הי' להם בליל א' לבד כנ\"ל, אך מ\"ש מצות יאכל ממילא את ז' הימים קאי בפסח דמצרים דוקא משום דח\"ע בבחי'",[["5816","328","<b>איסור חמץ. . יום א'</b>: ראה פסחים צו, ב."],["5817","329","<b>כי גורשו ממצרים</b>: בא יב, לט."],["5818","330","<b>ויאפו. . מצות</b>: התחלת הכתוב כי גורשו [בדילוג]."],["5819","331","<b>כי כל אוכל חמץ</b>: בא יב, טו [בדילוג]."],["5820","332","<b>איסור חמץ. . ליניקת החיצונים</b>: ראה פע\"ח (שחה\"מ) שכ\"א, פ\"ב. פ\"ד."],["5821","333","<b>אך ביום הראשון</b>: בא יב, טו."],["5822","334","<b>כי כל אוכל מחמצת</b>: בא יב, יט."],["5823","335","<b>חובה. . מצה. . בלילה הראשונה</b>: נסמן לעיל צד, ד."],["5824","336","<b>גם הם היו צריכים למצות הספירה</b>: ראה זהר אמור צז, ב. ר\"ן סוף פסחים. מאמרי אדה\"א ויקרא ח\"א ע' ריב. וש\"נ. ח\"ב ע' תתפה. לעיל קיא, ד. קיז, ד. לקמן פ' בשלח רמב, א. יתרו רנה, ב."]]],[2300540640,"מקיף דאבא כולל כל הימים וכמ\"ש בזהר [בענין] עננא דאהרן<sup data-n=\"5825\">337</sup> כמ\"ש יומא דאזיל עם כולהו יומין<sup data-n=\"5826\">338</sup> וד\"ל.\n<b>והנה</b> בכ\"ז יתור[צו] כל הקושיות שיש במאמר [ד]הגדה [במ\"ש] מצה זו שאנו אוכלים ע\"ש מה ע\"ש שלא הספיק כו' עד שנגלה עליהם מלך [כו'], דלמה א' בטעם מצה זו שאנו אוכלים הוא לפי שלא הספיק כו' הלא כבר נצטוו על המצה לאכול עם הפסח בעשור [לחודש]<sup data-n=\"5827\">339</sup> כו' וכמ\"ש על מצות<sup data-n=\"5828\">340</sup> כו' וא\"כ [גם] אם לא גורשו והספיק להחמיץ היו מצווין על המצה, וגם מטעם שנצטוו ז' ימים מצות תאכלו<sup data-n=\"5829\">341</sup> בראשון ביו\"ד<sup data-n=\"5830\">343</sup> לחדש כו'<sup data-n=\"5831\">344</sup> בערב תאכלו מצות עד יום [האחד ועשרים<sup data-n=\"5832\">342</sup> ] כו'. אך הנה ע\"פ הנ\"ל יובן שיש ב'<sup data-n=\"5833\">345</sup> מדרגות במצה, א' בליל הא' שהוא המשכות מהו\"ע דאבא הכללי' והעקרי' שהוא חובה וע\"ז נצטוו ביו\"ד לחדש לאכול מצה עם הפסח והוא מ\"ש בערב תאכלו מצות<sup data-n=\"5834\">346</sup> כו'. ומדרגה הב' במצה הוא באכילת מצה בשאר הימים שע\"ז א' ז' ימים תאכלו מצות<sup data-n=\"5835\">347</sup> [שהיא לדורות דוקא כנ\"ל, מטעם השמירה מיניקות החיצוני' כנ\"ל. וע\"ז או' בהגדה מצה זו שאנו אוכלי' ע\"ש מ\"ה פי' מצה זו קאי על] מצות מצה בליל א' שהיא חובה ע\"ש שלא הספיק כו', אך א\"כ אין זה טעם מספיק למצות מצה שאנו אוכלים גם בשאר הימים ולכך שואל ע\"ש מ\"ה [פי' ע\"ש מ\"ה] דחכמה שנתגלה אז האיך אנו אוכלים בדרך מצוה גם בשאר הימים כו', ומפרש הדבר דמשום שלא הספיק כו' מפני שהי' הגילוי [אז] לאבותינו מבחי' מקיף העליון ע\"כ צריכים אנחנו להמשיך בחי' מה זה בפרט בשאר הימים [ב]דרך מצוה, ואז הגם שאבותינו לא היו צריכים להמשכה זו דמ\"ה בפרט בשאר הימים מטעם הנ\"ל, אבל מה שהי' להם האור בגילוי בא אלינו שאין לנו עכשיו אור זה בגילוי בדרך מצוה וחיוב כמ\"ש ז' ימים תאכל[ו] מצות לדורות מטעם השמירה מן החמץ מיניקת החיצונים, אעפ\"י שלאבותינו הי' זה מצד הגילוי ממילא ומאליו כו' עכ\"פ אצלינו לדורות נעשה זה חיוב ואזהרה מן החמץ, כי מה שאצלם הי' מצד הגילוי שלזה לא היו צריכים שימור בשאר הימים צריך לנו אזהרה ושמירה שהרי אין לנו גילוי המקיף הזה <span data-k=\"pg\">304</span> ּ ויכול להיות יניקה לחיצונים [מן החמץ] ע\"כ אנו אוכלים מצה ולא חמץ גם בשאר הימים. [וז\"ש מצה זו שאנו אוכלים גם בשאר הימים] ע\"ש מה דחכמה בפרט באזהרה מן החמץ לפי שלא הספיק לאבותינו כו' נעשה אצלינו בדרך אזהרה ושמירה מן החמץ עכ\"פ מטעם הנ\"ל (אעפ\"י שאין המצוה במצה בשאר הימים גם עכשיו כנ\"ל ממילא אוכלים מצה מפני<sup data-n=\"5836\">348</sup> שצריך לשמור מן החמץ כו'). ומ\"ש שלא הספיק בצקת כו' עד שנגלה",[["5825","337","<b>עננא דאהרן</b>: נסמן בהערה הבאה."],["5826","338","<b>יומא דאזיל עם כולהו יומין</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' א'לה. וש\"נ."],["5827","339","<b>נצטוו. . בעשור [לחודש]</b>: ראה בא יב, ג: דברו. . בעשור. . ויקחו."],["5828","340","<b>על מצות</b>: בהעלותך ט, יא (בפסח שני). בא יב, ח [ושם: ומצות על]. וראה לעיל הערה 90."],["5829","341","<b>ז' ימים מצות תאכלו</b>: בא יב, טו."],["5830","343","<b>ביו\"ד</b>: ביד: בי\"ד."],["5831","344","<b>כו'</b>: ביד: ליתא."],["5832","342","<b>בראשון. . האחד ועשרים</b>: בא יב, יח [בדילוג]."],["5833","345","<b>ב'</b>: תוקן ע\"פ ביד. ובתו\"ח: ה'."],["5834","346","<b>בערב תאכלו מצות</b>: בא יב, יח."],["5835","347","<b>ז' ימים תאכלו מצות</b>: לשון הכתוב אמור כג, ו. בא יב, טו [מצות תאכלו]. יג, ו [תאכל מצות]. וראה לעיל קכא, א ובהערה 309."],["5836","348","<b>מפני</b>: ביד: לפי."]]],[2300540652,"פי' עד\"ז<sup data-n=\"5837\">349</sup> היינו מפני שנגלה עליהם מעצמות א\"ס ב\"ה שבעצמות אור אבא בבחי' הדילוג הגדול הנ\"ל, ע\"כ לא הספיק להיות החמץ במציאות כלל כי נתבטל ממציאות לגמרי מצד עוצם הגילוי דמקיף העליון כנ\"ל בענן ה' יומם כו' שבורחים החיצונים ומתבטלים מפני כו' וע\"כ לא היו צריכים שמירה מן החיצוני' כלל לפי שאין לחמץ שרש יניקה אצלם כלל, אבל עכשיו נעשה לנו ציווי ואזהרה לשמור מן החמץ כנ\"ל ועכ\"ז גם אנו אוכלים ע\"ש שלא הספיק כו' [רק] שצריך שמירה לבד וד\"ל.\n<b>ומעתה</b> י\"ל [לשון] המאמר שנגלה עליהם ממה\"מ הקב\"ה בכבודו ובעצמו<sup data-n=\"5838\">350</sup>, הנה ידוע בס' הקבלה בענין כ\"י בני מלכים הן<sup data-n=\"5839\">351</sup> וכמו במשנה בני מלכים ישנים<sup data-n=\"5840\">352</sup> כו' שזהו בחי' נו\"ה דמל' ומלכי המלכים הוא בחי' [חג\"ת שבמל' ומלך מלכי המלכים הוא בחי'] חב\"ד שבמל', שהן ג' מדרגות דחב\"ד חג\"ת נה\"י שבמל' והקב\"ה הוא כתר שבמל' המתנשא מימות עולם<sup data-n=\"5841\">353</sup> [דמל'] (ובכבודו ובעצמו הן ב' מקיפים דחי' יחידה שלמעלה מנר\"נ שהן בי\"ע), והן ד' מדרגות אצי' בריאה יצירה ועשי' בכלל, ובפרט יש ד' מדרגות דאבי\"ע גם באצי'<sup data-n=\"5842\">354</sup> עצמו, אצי' שבאצי' כתר [ד]אצי', ובריאה [שב]אצי' חב\"ד דאצי', יצי' שבאצי' חג\"ת [דאצי'], עשי' שבאצי' נה\"י דאצי'. ובדרך כללות כל האצי' הוא בבחי' אבא כמ\"ש דאבא מקנן באצי'<sup data-n=\"5843\">355</sup> ואימא בבריאה<sup data-n=\"5844\">356</sup> וז\"א ביצי'<sup data-n=\"5845\">357</sup> ומל' בעשי'<sup data-n=\"5846\">358</sup>. והן ד' אותיות דשם הוי'<sup data-n=\"5847\">359</sup> יו\"ד באצי' ה\"א בבריאה וי\"ו ביצי' ה\"א אחרונה בעשי' כידוע וקוש\"י בכתר<sup data-n=\"5848\">360</sup> דחכ' דאצי'. ונמצא כאשר אומר שנגלה עליהם ממ\"ה<sup data-n=\"5849\">361</sup> כו' הכוונה הוא שנגלה עליהם<sup data-n=\"5850\">362</sup> בחי' אוא\"ס דכתר דחכ' שזהו פנימי' אבא שכולל כל האצי' והוא הקב\"ה כו' וזהו בכלל, ובפרט נק' אצי' שבאצי' (אך א\"כ לא יתפרש מלך בלשון יחיד דוקא מאחר שהוא חב\"ד כו', ובזהר א' עמ\"ש קרי\"ת מל\"ך ר\"ב<sup data-n=\"5851\">363</sup> דמלכא בהיכלי' טמיר וגניז מלך ר\"ב אקרי, יתיב בין עבדוהי מלך זוטא<sup data-n=\"5852\">364</sup> אקרי (והיינו המלך [הקדוש] ומלך המשפט<sup data-n=\"5853\">365</sup>, וביאור[ו] ידוע עמ\"ש נכון כסאך מאז<sup data-n=\"5854\">366</sup> עפ\"ל<sup data-n=\"5855\">367</sup> המדרש משל לאגוסטוס יושב<sup data-n=\"5856\">368</sup> מלך [עומד] כו' אגוסטוס [הוא] מלך על המלכים (שנק' קיסר) ומלך הוא המלך על העבדים כו', ובכאן כפל ושלש מלך מלכי המלכים, הענין הוא כמ\"ש לך הוי' הממלכה<sup data-n=\"5857\">369</sup> והוא בחי' מלך מרומם לבדו<sup data-n=\"5858\">370</sup> כאשר ההתנשאות",[["5837","349","<b>עד\"ז</b>: ביד: עד זה."],["5838","350","<b>שנגלה. . בכבודו ובעצמו</b>: הגש\"פ פיסקא מצה זו [שנגלה. . הקב\"ה]. פיסקא ויוציאנו [הקב\"ה בכבודו ובעצמו]. וראה גם לעיל קט, ג הערה 516."],["5839","351","<b>כ\"י בני מלכים הן</b>: שבת סז, א."],["5840","352","<b>במשנה בני מלכים ישנים</b>: ברכות פ\"א, מ\"ב במשניות [ובמשנה שבגמרא ליתא תיבת בני. וראה ח\"ג במשניות שם]. ושם: לעמוד."],["5841","353","<b>המתנשא מימות עולם</b>: ברכת יוצר."],["5842","354","<b>דאבי\"ע גם באצי'</b>: נסמן לעיל פ' שמות כד, ד."],["5843","355","<b>דאבא מקנן באצי'</b>: ראה ת\"ז ת\"ו (כג, א). הנסמן במאמרי אדה\"א דברים ח\"א ע' רלה."],["5844","356","<b>ואימא בבריאה</b>: נסמן לעיל פ' שמות ה, ד."],["5845","357","<b>וז\"א ביצי'</b>: נסמן לעיל פ' שמות טו, ד."],["5846","358","<b>ומל' בעשי'</b>: ראה ת\"ז שם."],["5847","359","<b>ד' אותיות דשם הוי'</b>: נסמן לעיל פ' שמות כד, ד."],["5848","360","<b>וקוש\"י בכתר</b>: ראה זהר ויקרא י, ב. פרדס (שער שם בן ד') שי\"ט, פ\"ב. הנסמן במאמרי אדה\"א קונטרסים ע' תכז. לקמן פ' בשלח קנ, א. רה, ד."],["5849","361","<b>ממ\"ה</b>: ביד: מלך מלכי."],["5850","362","<b>עליהם</b>: שם: ליתא."],["5851","363","<b>קרי\"ת מל\"ך ר\"ב</b>: תהלים מח, ג."],["5852","364","<b>מל\"ך ר\"ב. . מלך זוטא</b>: נסמן לעיל פ' וארא עה, ב."],["5853","365","<b>המלך [הקדוש] ומלך המשפט</b>: נסמן לעיל שם."],["5854","366","<b>נכון כסאך מאז</b>: תהלים צג, ב."],["5855","367","<b>עפ\"ל</b>: ביד: ע\"פ."],["5856","368","<b>משל לאגוסטוס יושב</b>: נסמן לעיל ק, ג."],["5857","369","<b>לך הוי' הממלכה</b>: דהי\"א כט, יא."],["5858","370","<b>מלך מרומם לבדו</b>: ברכת יוצר."]]],[2300540664,"[הוא] <b>מצד</b> עצמו כמו שהוא לבדו ממש והוא הנק' מלך הקדוש והיינו [בחי'] מל' דא\"ס<sup data-n=\"5859\">371</sup> שעז\"א מלכותך [ממש] מלכות כל עולמים<sup data-n=\"5860\">372</sup> כו' כידוע, וכאשר מלך על עם ומתנשא עליהם זהו מלך סתם שהוא מלך על העבדים, וכאשר מובדל מהיות בחי' מלך על עם ונמשך ומתלבש להיות מלך [על עם] ע\"ז א' ה' מלך גיאות לבש<sup data-n=\"5861\">373</sup> [כו'], וצריך להיות ממוצע ביניהם והוא מ\"ש לך ה' הממלכה להיות מקור לבחי' ממלכה להמליך מלכים כמ[אמר] הממליך מלכים<sup data-n=\"5862\">374</sup> ולו המלוכה וזהו מלכי המלכים כו', וכערך ביטול העבדים לגבי מלך כו' כך<sup data-n=\"5863\">375</sup> ערך ביטול המלכים לגבי מלכי המלכים. אך מלך מלכי המלכים הוא למעלה מהיות גם מקור להמליך מלכים עד שהוא רם ומובדל מהם ג\"כ <span data-k=\"pg\">קנב</span> ּ וזהו מלך יחיד מרומם לבדו מאז כמ\"ש<sup data-n=\"5864\">376</sup> נכון כסאך מאז ממש, ומ\"ש [מלכותך] מלכות כ\"ע להיות ממה\"מ ג\"ז בחי' ירידה לגבי בחי' העצמות ממש שלמעלה מבחי' התנשאות שמצד עצמו והוא הנק' הקב\"ה גם לא בשם מלך יחיד כו' וד\"ל (וע\"ד אחר פי' מלכים הן הנשמות או ת\"ח שנק' מלכים כמו בי מלכים ימלוכו<sup data-n=\"5865\">377</sup> והוא התורה שנק' מלכי המלכים דג' קשרים<sup data-n=\"5866\">378</sup> ישראל מתקשראן באורייתא ומלך מלכי כו' היינו מה דאורייתא מתקשראה בקודב\"ה וידוע דקוב\"ה סתים וגליא<sup data-n=\"5867\">379</sup> כו', וע\"כ גם מה שנק' [מלך] מלכי המלכים להתקשר באורייתא [וישראל] ירידה אצלו כו'. אך ביצ\"מ נגלה על נש\"י כמו שהן בשרש הראשון שהוא הקב\"ה בכבודו ובעצמו שלמעלה גם מבחי' אותיות דמהו\"ע<sup data-n=\"5868\">380</sup> להיות נק' מלך מלכי המלכים שהן על התורה [ו]כנס\"י וד\"ל) (וכמ\"ש במ\"א בענין ספר וסיפור וסופר<sup data-n=\"5869\">381</sup> כו' ובענין מיילדות העבריות<sup data-n=\"5870\">382</sup> ). וענין מה שנק' הקב\"ה היינו גילוי אוא\"ס שבפנימיות אבא שנק' קדוש והוא בחי' כתר דחכמה כנ\"ל וברוך הוא ההמשכה הנגלית להיות מלך מלכי המלכים עד בחי' סוף עולם העשי' גם בחיצוני' [דחיצוני'] דמל' דעכשיו<sup data-n=\"5871\">383</sup> והוא להוציא בנ\"י ממצרים מנש\"ט דקליפה ע\"י אותות ומופתים כמ\"ש מלך אלקים על גוים<sup data-n=\"5872\">384</sup> כו' [ו]זהו שנגלה עליהם מלך כו' וגאלם מנש\"ט דמצרים וד\"ל.\n<b>ובזה</b> הדרך יובן ג\"כ מ\"ש בהגדה ועברתי באמ\"צ אני ולא מלאך<sup data-n=\"5873\">385</sup> כו', דהנה ע\"ד הנ\"ל בד' מדרגות דאבי\"ע כו' כך הוא ג\"כ ענין מלאך ושרף ושליח שהן ג' מדריגות דבי\"ע",[["5859","371","<b>מלך הקדוש. . מל' דא\"ס</b>: נסמן לעיל ק, ג."],["5860","372","<b>מלכותך. . כל עולמים</b>: תהלים קמה, יג."],["5861","373","<b>ה' מלך גיאות לבש</b>: תהלים צג, א."],["5862","374","<b>הממליך מלכים</b>: פיוט (לימים נוראים) האוחז ביד."],["5863","375","<b>כו' כך</b>: ביד: כן."],["5864","376","<b>כמ\"ש</b>: ביד: כמו."],["5865","377","<b>בי מלכים ימלוכו</b>: משלי ח, טו."],["5866","378","<b>דג' קשרים</b>: נסמן לעיל פ' שמות ב, ד."],["5867","379","<b>דקוב\"ה סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א."],["5868","380","<b>דמהו\"ע</b>: ביד: דטה\"ע."],["5869","381","<b>ספר וסיפור וסופר</b>: ראה ס\"י פ\"א, מ\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370235\" data-slug=\"torah-or\" data-id=\"3901370235\">תו\"א שמות נב, ג</a>-ד."],["5870","382","<b>מיילדות העבריות</b>: ראה לעיל פ' שמות כה, ג. לב, ג ואילך."],["5871","383","<b>דעכשיו</b>: ביד: דמל' דעשי'."],["5872","384","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["5873","385","<b>ועברתי. . ולא מלאך</b>: ראה גם הנסמן לעיל פ' וארא נד, ב."]]],[2300540676,"מלאך<sup data-n=\"5874\">*386</sup> הוא [ב]בחי' עשי' ושרף הוא ביצי'<sup data-n=\"5875\">386</sup> ושליח בבריאה והקב\"ה בעצמו הוא בבחי' [ה]אצי' והיינו בדרך כלל, ובדרך פרט הוא אצי' שבאצי' כנ\"ל. כי הנה בחי' המל' נוק' דז\"א נק' מלאך כמ\"ש בזהר ע\"פ המלאך הגואל אותי<sup data-n=\"5876\">387</sup> כו' והוא בחי' עשי' דאצי', וז\"א דאצי' שהוא יצי' דאצי' [כידוע] נק' שרף בער[ך] בחי' מלאך דמל', ובחי' אימא דבריאה דאצי' נק' שליח, והקב\"ה [בעצמו] אצי' שבאצי' בחי' פנימי' אבא דאצי' שבו דוקא מלובש מפנימי' ועצמו' אוא\"ס ב\"ה כידוע. וזהו אני הוי'<sup data-n=\"5877\">388</sup> אני [ממש] מלובש בהוי' דחכמה (בבחי' כת\"ר דחכמה כנ\"ל) (אני הוי'<sup data-n=\"5878\">389</sup> נסתר דאנ\"י הוי' הוא<sup data-n=\"5879\">390</sup> גילוי אוא\"ס בחכ' ואנ\"י אותיות אי\"ן<sup data-n=\"5880\">391</sup> הוא בפנימיות הכת\"ר שנק' הוא<sup data-n=\"5881\">392</sup> ל' נסתר כמו שהחכמה בבחי' אין ממש שע\"ז נאמר וכבודי לאח\"ר לא אתן<sup data-n=\"5882\">393</sup> שהקליפות נק' אלקים אחרים ומתבטלים שם ממציאותם לגמרי כו'. וזהו שא' ועברתי באמ\"צ אני ולא מלאך בארץ מל'<sup data-n=\"5883\">394</sup> דקליפה אני ולא מלאך מל' דאצי', והכיתי כל בכור<sup data-n=\"5884\">395</sup> כו' בחי' דכר דקליפה אני ולא שרף מדות דז\"א דאצי', ובכל אלהי מצרים<sup data-n=\"5885\">396</sup> שהן נש\"ט שמקבלים מאחוריים דנש\"ט<sup data-n=\"5886\">397</sup> אני ולא השליח בחי' אימא דבריאה דאצי', אלא אני הוי' אבא דאצי' שאין פנימיות גילוי אוא\"ס רק בפנימית אור אבא<sup data-n=\"5887\">398</sup> החכ'<sup data-n=\"5888\">399</sup> כידוע. וע\"כ הוא<sup data-n=\"5889\">400</sup> ביטול יניקות נש\"ט דאלקי מצרים כ\"א מפני גילוי אור אבא דשם נא' וכבודי לאחר לא אתן (שלא הי' השבירה רק בבחי' ס\"ג דבינה אבל בחכ' לא הי' שבירה כלל וע\"כ א' ימותו ולא בחכ'<sup data-n=\"5890\">401</sup> כידוע). וכפל עוד לומר אנ\"י הו\"א<sup data-n=\"5891\">402</sup> ל' נסתר שהוא בחי' מקיף דאור אבא שא\"א שיקבלו שם החיצוני' כי מתבטלי' שם לגמרי כנ\"ל בענין [ענן] ה' יומם כו', וזהו אני הוא ולא אחר שאין אחר יכול לעמוד שם <span data-k=\"pg\">306</span> ּ במציאות כלל וכלל וד\"ל (ועוד יש לפרש בהיפוך אני ולא מלאך [ד]בריאה כמ\"ש הנני שולח מלאך<sup data-n=\"5892\">403</sup> לפניך שהוא מט\"ט דבריאה<sup data-n=\"5893\">404</sup> כידוע ושרף ביצי' ושליח בעשי'<sup data-n=\"5894\">405</sup> כמ\"ש במ\"א). וזהו הכלל שכל הנמוך יותר צריך לעליון יותר לירד שם ובאמ\"צ אני ולא מלאך דבריאה או דעשי' ובמכות בכורות אני ולא שרף ובאלקי מצרים אני הוי' דאצי' ששם גילוי אוא\"ס בכבודו ובעצמו).",[["5874","*386","<b>מלאך. . בבריאה</b>: ראה סידור סדר הגדה רצט, א. מאמרי אדה\"ז תקס\"ה ח\"א ע' תמב."],["5875","386","<b>ושרף הוא ביצי'</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רמט."],["5876","387","<b>המלאך הגואל אותי</b>: נסמן לעיל פט, א הערה 92."],["5877","388","<b>אני הוי'</b>: המשך הכתוב ועברתי."],["5878","389","<b>הוי'</b>: ביד: הוא לשון."],["5879","390","<b>הוי' הוא</b>: ב: הוא. ידיט: הוי'."],["5880","391","<b>ואנ\"י אותיות אי\"ן</b>: נסמן לעיל נ, ד."],["5881","392","<b>הכת\"ר שנק' הוא</b>: ראה שערי אורה — לר\"י גיקטלייא — שער יו\"ד [ירושלים תש\"ך קא, ב]. פרדס (שעה\"כ) שכ\"ג מערכת הוא. ע\"ח (שער תיקון הנוקבא) של\"ד, ספ\"ב."],["5882","393","<b>וכבודי לאח\"ר לא אתן</b>: ישעי' מב, ח. מח, יא."],["5883","394","<b>בארץ מל'</b>: ראה זהר (תוספתא) בראשית לא, ב."],["5884","395","<b>והכיתי כל בכור</b>: המשך הכתוב ועברתי."],["5885","396","<b>ובכל אלקי מצרים</b>: המשך הכתוב ועברתי."],["5886","397","<b>דנש\"ט</b>: ביד: דבינה דנש\"ב — ר\"ה כא, ב."],["5887","398","<b>אבא</b>: ביד: ליתא."],["5888","399","<b>גילוי אוא\"ס. . החכ'</b>: נסמן לעיל פ' שמות ז, ד."],["5889","400","<b>הוא</b>: ביד: אין."],["5890","401","<b>ימותו ולא בחכ'</b>: נסמן לעיל פ' שמות מב, ב."],["5891","402","<b>וכפל. . אנ\"י הו\"א</b>: בהגדה כאן."],["5892","403","<b>הנני שולח מלאך</b>: משפטים כג, כ [ושם: הנה אנכי — ראה מאמרי אדה\"א במדבר ח\"ב ע' תט. ידיט: מלאכי — ראה מאמרי אדה\"א נ\"ך ע' שנ. וש\"נ. שע\"ת קיא, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670208\" data-slug=\"torat-chaim\" data-id=\"2300670208\">תו\"ח וירא צט, ד</a> הערה 39]."],["5893","404","<b>הנני. . מט\"ט דבריאה</b>: סנהדרין לח, ב. רש\"י משפטים כג, כא. ראה מאמרי אדה\"א נ\"ך ע' שלד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670193\" data-slug=\"torat-chaim\" data-id=\"2300670193\">תו\"ח וירא צט, ג</a> ובהערה 17. שע\"ת כט, ב ובהערה 10. ש\"א עא, א ובהערה 12. לעיל צח, א. לקמן פ' משפטים רצב, ב. תרומה שיד, ד."],["5894","405","<b>מלאך [ד]בריאה. . ושרף ביצי' ושליח בעשי'</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תתמב."]]],[2300540688,"<b>והנה</b> אחר כ\"ז הנה יובן ענין סמיכות פסוק זה והגדת לבנך<sup data-n=\"5895\">406</sup> כו' למ\"ש תחלה מצות יאכל את ז' הימים כו' והגדת לבנך כו' וא' שזה שא' בעבור זה עשה ה' לי<sup data-n=\"5896\">407</sup> כו' בעבור זה לא אמרתי<sup data-n=\"5897\">408</sup> אלא בשעה שיש מצה כו'. וכללות הענין הוא דקאי אדסמיך לי' דוקא מצות יאכל כו' שזהו בחי' המשכות דעצמות אור אבא שנק' זה לנוכח בגילוי לפי שבו בא גילוי העצמות דא\"ס כנ\"ל והיינו בעבור המצה שבה התלבשות דאור אבא שנק' זה עשה [ה'] לי כו'. וביאור הענין הנה יובן ע\"פ המבואר במ\"א בענין ההפרש בין בחי' מוחי' דאבא לאימא<sup data-n=\"5898\">409</sup> שהוא ההפרש בין התפעלות ההשגה דבינה שנק' י\"ש מורגש ובין בחי' הביטול העצמי דחכ' שהוא בחי' האי\"ן, וכידוע בענין מ\"ש ואחר האש קול דממה דקה<sup data-n=\"5899\">410</sup> דתמן קאתי מלכא<sup data-n=\"5900\">411</sup> שזהו בש\"ע<sup data-n=\"5901\">412</sup> דוקא בלחש בבחי' הביטול דאי\"ן בתכלית משום דקאתי מלכא עד\"מ העומד לפני המלך שמתבטל בביטול שלמעלה מן הטעם בהעדר הרגשת עצמו לגמרי מכל וכל כו'. וכך הוא בש\"ע שהוא גילוי אוא\"ס שבחכ' שנק' אין ממש דתמן קאתי מלכא, משא\"כ קודם לזה בק\"ש הוא בחי' ההשגה דבינה בשמע ישראל באחדות ה' כידוע נק' אש שההתפעלות הוא מהות<sup data-n=\"5902\">413</sup> ההשגה [ה]אלקי' בבחי' רשפי אש מורגש ליש וכו' לפי שמרחוק הוי' נראה רק בשמיעה דבינה דלא קאתי מלכא בגילוי גמור כמו בחכ' (וכמ\"ש במ\"א בסדר הד' מדרגות<sup data-n=\"5903\">414</sup> הללו בתפלה רוח בפסוד\"ז בשיר ושבח המלאכים דעשי' ורעש ביצי' בשתים לפניה באופנים וחיות ואש בבריאה בק\"ש וקול דממה דקה באצי' בש\"ע).\n<b>והנה</b> כל ענין יצ\"מ הי' משעבוד לגאולה מאפילה לאור גדול שהוא מן המיצר דק\"נ שנק' אפילה וחושך כו' (וכמ\"ש מי זאת עולה מן המדבר<sup data-n=\"5904\">415</sup> כו' שהוא עלי' כנס\"י מן הק\"נ, יפה כלבנה בפסוד\"ז ושתים לפניה ברה כחמה<sup data-n=\"5905\">416</sup> בק\"ש כו'). וכ\"ז סדר העלי' בתפלה עד ק\"ש הכל ע\"י בחי' ההשגה אלקי' דבינה דוקא כאשר יתבונן ומשיג באלקו' בהשתלשלות דממכ\"ע וסוכ\"ע<sup data-n=\"5906\">417</sup> [כו'] איך שהוא ית' מקורא דכולא",[["5895","406","<b>והגדת לבנך</b>: בא יג, ח."],["5896","407","<b>בעבור זה עשה ה' לי</b>: המשך הכתוב והגדת לבנך."],["5897","408","<b>בעבור זה לא אמרתי</b>: הגש\"פ פיסקא יכול מר\"ח. מכילתא בא יג, ח. יל\"ש שם (רמז רכג)."],["5898","409","<b>ההפרש. . מוחי' דאבא לאימא</b>: ראה סידור, מאמרי אדה\"ז תקס\"ה ולקו\"ת שנסמנו בריש המאמר."],["5899","410","<b>ואחר האש קול דממה דקה</b>: מלכים-א יט, יב. ידיט: ואחרי — ראה לקמן פ' תצוה שמט, א. שה\"א עח, א הערה 14."],["5900","411","<b>דתמן קאתי מלכא</b>: ראה זהר (רע\"מ) פינחס רכג, ב. ת\"ז בהקדמה (ג, ב)."],["5901","412","<b>שזהו בש\"ע</b>: ראה מאמרי אדה\"א נ\"ך ע' טו ואילך (ובהנסמן בריש המאמר שם). קונטרסים ע' שז. לקמן פ' תצוה שמט, ד."],["5902","413","<b>מהות</b>: ביד: מחמת."],["5903","414","<b>בסדר הד' מדרגות</b>: ראה גם לקמן ע' שמט, א ואילך. מאמרי אדה\"א נ\"ך ע' טז."],["5904","415","<b>מי זאת עולה מן המדבר</b>: שה\"ש ג, ו. ח, ה. ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ע' תצג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370422\" data-slug=\"torah-or\" data-id=\"3901370422\">תו\"א צד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380324\" data-slug=\"likkutei-torah\" data-id=\"4001380324\">לקו\"ת במדבר ד, א</a>. מאמרי אדה\"א במדבר ח\"א ע' ו ואילך. ע' קע. דברים ח\"ב ע' תקיב. נ\"ך ע' שפד. לעיל פ' וארא עד, ב. לקמן פ' בשלח קלז, ג. פ' יתרו רנא, ד."],["5905","416","<b>יפה כלבנה. . ברה כחמה</b>: שה\"ש ו, י. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תכד. לעיל שם. לקמן שם."],["5906","417","<b>דממכ\"ע וסוכ\"ע</b>: זהר (רע\"מ) פינחס רכה, א."]]],[2300540700,"עלמא<sup data-n=\"5907\">418</sup> וכולא קמי' [כלא]<sup data-n=\"5908\">419</sup> כו', מזה יתפעל בלבו ומוחו ביותר עד שפועל התפעלות זאת האלקי' גם בלב בשר החומרי להיות לבו ובשרו יוצא מחשכת החומרי' ל[ה]דבק באלקים חיים וא\"כ זה[ו] כמו שיוצא מאפילה לאור גדול ממש, ואמנם א\"א לצאת מן החשך ואפילה כ\"א ע\"י האור דוקא והוא בחי' [ה]השגה [ה]אלקי' בהשתלשלו' שנק' אור ובחי' התרחבות ההשגה דבינה נק' אור גדול, וא\"כ מ\"ש בהגדה מאפילה לאור גדול לא יתכן כ\"א בבחי' ההשגה דבינה שנק' אור גדול, אבל בבחי' החכ' שבבחי' אין בעצמו' האור דא\"ס דלמתב\"כ כו' שלמעלה מן ההשתל' דסו\"מ<sup data-n=\"5909\">420</sup> כו' כמו בש\"ע שנק' קול דממה דקה כנ\"ל, הרי ידוע ששם האור והחשך שוין <span data-k=\"pg\">קנג</span> ּ ממש בהשוואה א' וכמ\"ש גם חשך לא יחשיך ממ\"ך כחשיכה כאורה<sup data-n=\"5910\">421</sup> כו' שהרי האור והחשך הן באים בבחי' ההשתלשלו' כמו יוצר אור כו' וא\"כ איך יתכן שם לומר שיצא מאפילה לאור גדול מאחר שגם האור כחשך יחשב כו', וכמ\"ש גם חשך לא יחשיך כו' וא\"כ גם האור יחשב כחשך מאחר ששניהם שוין ממש כחשיכה כאורה כו' וד\"ל. ולפ\"ז הרי יובן עכ\"פ מאחר שבבחי' אין דחכמה שוין חשך ואור ממש כנ\"ל א\"כ הרי יוכל להיות שיתפשט ויומשך בחי' גילוי אוא\"ס שבחכ' גם למטה מטה במקום חשך ואפילה דק\"נ בעולם הפירוד לגמרי כמו שהוא מאיר בעולם היחוד שהוא בחי' האור בכלל ממש בשוה כמ\"ש גם חשך לא יחשיך כו' אחר שהוא למעלה מן ההשתל' לגמרי, וכמו שיכול להיות גילוי אור האלקי [ב]בחי' אי\"ן דחכ' גם בחומר גופני שנלקח מד\"י דק\"נ שיהי' גם הוא בבחי' ביטול העצמי למעלה מן [הטעם וה]השגה כמו בש\"ע בהשתחווא' הגוף כמו בנש\"י<sup data-n=\"5911\">422</sup> ממש משום דתמן קאתי מלכא כו' מטעם שגם חשך כו'. וזהו ועברתי באמ\"צ [אני ולא מלאך] כו' אני הוי' דחכמה דוקא [כנ\"ל] מפני שהוא בבחי' האין ממש וד\"ל (והוא למעלה מבחי' יצ\"מ מאפילה לאור גדול שע\"י ההשגה אלקי' דבינה שאין לפני גילוי דאוא\"ס שבחכ' ענין אפילה וחשך כלל וכלל כו'). וזהו שא' והגדת לבנך ביום ההוא לאמר בעבור זה עשה כו', פי' בעבור זה שהוא בחי' גילוי דא\"ס באור אבא דוקא שנק' זה בגילוי לנוכח כנ\"ל עשה ה' לי בצאתי ממצרים, פי' לי שגם בבחי' החושך שבחומר הגופני עשה ה' להיות גם בו [גילוי] אור האלקי' שהוא גילוי אוא\"ס שבחכ' מטעם הנ\"ל דגם חשך כו' שזהו דוקא בבחי' זה דהיינו גילוי אור דאבא כמו ז\"ה אלי ואנוהו<sup data-n=\"5912\">423</sup> כו', ואם לא בעבור זה לא עשה ה' גם לי להאיר גם בחשך כמו באור כו' וד\"ל. ומ\"ש עשה [ה'] לי בצאתי ממצרים דוקא, הענין הוא הגם דיצ\"מ הי' ע\"י",[["5907","418","<b>עלמא</b>: ביד: ליתא."],["5908","419","<b>וכולא קמי [כלא]</b>: נסמן לעיל לח, א."],["5909","420","<b>דסו\"מ</b>: יד: דסובב וממלא."],["5910","421","<b>גם חשך. . כאורה</b>: תהלים קלט, יב [בדילוג]. יד: וגם (וכן בסמוך) — נסמן לעיל סד, א."],["5911","422","<b>בנש\"י</b>: ביד: בנשמה."],["5912","423","<b>ז\"ה אלי ואנוהו</b>: בשלח טו, ב."]]],[2300540712,"בחי' [ה]השגה האלקי' לצאת מאפילה לאור גדול כנ\"ל, אבל היא גופא מאין הי' בהם כח זה לצאת מנש\"ט הוא שעשה הוי' לי בחי' הוי' דאור אבא דוקא, להיות ידוע שבחי' המשכה זאת דבחי' גילוי אוא\"ס בחכמה הי' בבחי' הדילוג הגדול כמ\"ש ופסח ה' על הפתח כו'. והוא ענין הנ\"ל בשרש בחי' המצה שבא התלבשות אור עצמות אבא בקטנות [דאמונה שהוא המצה בלילה הא' דפסח כנ\"ל, וז\"ש בעבור זה דבחי' מוחי'] דאבא עשה ה' לי בצאתי ממצרים שהי' אז בחי' [הדילוג] מגבוה לנמוך שאין זה [ביכולת] רק בבחי' גדלות המוחי' דאבא, ולא הי' יכול להיות השתלשלו' למטה כ\"כ עד שגם חשך כו' ע\"י בחי' בינה, שכל הגבוה גבוה יותר יותר יוכל לירד למטה להאיר גם החשך מפני ששם כחשיכה כאורה כנ\"ל, וע\"כ יצאו ממילא מאפילה לאור גדול ע\"י ההשגה דבינה והיינו שא' בעבור זה לא אמרתי כנ\"ל וד\"ל. ובכ\"ז יתורץ ענין הסמיכות דפ[סוק] והגדת לבנך כו' עם מ\"ש<sup data-n=\"5913\">424</sup> תחלה מצות יאכל את ז' הימים שזה[ו] בחי' המשכות דעצמות אור אבא במצה כנ\"ל וע\"כ סמך לו והגדת לבנך כו' בעבור זה דהתלבשות דאור אבא במצה עשה כו' וד\"ל.\n<span data-k=\"pg\">308</span> ּ<b>והנה</b> מעתה י\"ל מ\"ש בהגדה עמ\"ש בעבור זה עשה ה' לי [לי] דוקא ולא לו, והוא כאשר רשע או[מר] מה העבודה הזאת לכם, לכם ולא לו הוציא א\"ע מן הכלל כו' [ו]אף אתה הקהה את שיניו ואמור לו בעבור זה עשה ה' לי בצאתי ממצרים [לי] ולא לו אלו הי' שם לא הי' נגאל<sup data-n=\"5914\">425</sup>. ולהבין זה המאמר יש להבין<sup data-n=\"5915\">426</sup> תחלה ענין א' במ\"ש במשה בי\"ג מדה\"ר (בפ' כי תשא) וימהר משה<sup data-n=\"5916\">427</sup> ויקוד ארצה וישתחו וארז\"ל מה ראה מ\"ד<sup data-n=\"5917\">428</sup> ארך אפים ראה שכשם שמאריך אף לצדיקים מאריך אף לרשעים לכך וימהר ויקוד שלא להאריך אף לרשעים כ\"א לצדיקים כו', וכמו שביקש משה<sup data-n=\"5918\">429</sup> ונפלינו אני<sup data-n=\"5919\">431</sup> ועמך<sup data-n=\"5920\">430</sup> שלא תשרה שכינה באוה\"ע<sup data-n=\"5921\">432</sup>. ויש להבין דבשלמא מה שביקש שלא תשרה שכינה באוה\"ע יתכן משום שלא קיבלו התו\"מ והפרידן מיחודו<sup data-n=\"5922\">433</sup> כו', וגם לפ\"ז יפלא מה הי' צריך לבקש שלא תשרה שכינה כנ\"ל. אבל מה שביקש שלא יאריך אף לרשעים זהו פלא דעיקר מ\"ד אריכות אפים הוא לעוברי על רצונו שיאריך אפו עד שישוב ומדה זו דארך אפים שוה לכל לרשעים כמו לצדיקים ואיך תחלק כו', וראי' מדור אנוש<sup data-n=\"5923\">434</sup> שהי' עד\"ז והי' מאריך<sup data-n=\"5924\">435</sup> אפו להם<sup data-n=\"5925\">436</sup> כמאמר להודיע כמה ארך אפים<sup data-n=\"5926\">437</sup> [לפניו] כו'. אך הנה ידוע בשרש ענין המשכת י\"ג מדה\"ר דה'<sup data-n=\"5927\">438</sup> אל רחום וחנון<sup data-n=\"5928\">439</sup> כו' שאנו מתחילין להזכיר מר\"ח אלול<sup data-n=\"5929\">440</sup> שבו עלה",[["5913","424","<b>עם מ\"ש</b>: יד: למ\"ש."],["5914","425","<b>בעבור זה. . רשע. . נגאל</b>: ראה הגש\"פ פיסקא רשע. מכילתא בא יג, ח. יל\"ש שם (רמז רכג)."],["5915","426","<b>להבין</b>: ביד: להקדים."],["5916","427","<b>וימהר משה</b>: תשא לד, ח. ראה סנהדרין קיא, א."],["5917","428","<b>מ\"ד</b>: ביד: מדת."],["5918","429","<b>משה</b>: ביד: תחלה."],["5919","431","<b>אני ועמך</b>: ב: ליתא. יד: ניתוסף: כו'."],["5920","430","<b>ונפלינו אני ועמך</b>: תשא לג, טז."],["5921","432","<b>שלא תשרה שכינה באוה\"ע</b>: נסמן לעיל פ' שמות לא, א."],["5922","433","<b>והפרידן מיחודו</b>: ראה זהר יתרו פז, א. לקמן פ' תשא שפב, א. וש\"נ."],["5923","434","<b>מדור אנוש</b>: נסמן לעיל מד, א."],["5924","435","<b>שהי' עד\"ז והי' מאריך</b>: ביד: שהיו עובדי ע\"ז והאריך."],["5925","436","<b>והי' מאריך אפו להם</b>: ראה לעיל כד, ד הערה 54."],["5926","437","<b>להודיע כמה ארך אפים</b>: נסמן לעיל לא, א."],["5927","438","<b>דה'</b>: כ\"ה גם במאמרי אדה\"א בראשית ע' רנז. אבל בסידור כאן (רצט, ב) ליתא. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041347\" data-slug=\"likkutei-sichot\" data-id=\"1300041347\">לקו\"ש</a> אלול (כרך ד) ע' 1348-9. אגרות קודש שלו ח\"ב ע' שסט-שע."],["5928","439","<b>דה' אל רחום וחנון</b>: תשא לד, ו."],["5929","440","<b>להזכיר מר\"ח אלול</b>: במאמרי אדה\"ז תקס\"ה כאן (ע' תמד): בר\"ח אלול נמשכי' י\"ג מדות. בסידור כאן (רצט, ב): אנו מזכירין באלול עד יה\"כ. ועד\"ז ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380126\" data-slug=\"likkutei-torah\" data-id=\"4001380126\">לקו\"ת כאן (צו יב, ג</a>): באלול ועד יוה\"כ מזכירין י\"ג מדות. וראה גם מאמרי אדה\"א דברים ח\"ב ס\"ע תכב ואילך. וש\"נ."]]],[2300540724,"משה<sup data-n=\"5930\">441</sup> לקבל לוחות האחרונות וירד ביו\"כ שהוא להמשיך י\"ג מדה\"ר מבחי' רעדכ\"ר שבפנימיות הכתר לסליחות העוונות וחטאי' לבע\"ת, דגם שתשובה ביו\"כ<sup data-n=\"5931\">442</sup> [מכפר] מ\"מ אין הפגם נתקן רק ע\"י המשכת י\"ג מדה\"ר דוקא והוא מ\"ש לפני הוי' תטהרו<sup data-n=\"5932\">443</sup>, להיות שהמשכת י\"ג מדה\"ר נמשך מפנימיות הכתר (שהן [י\"ג] ת\"ד<sup data-n=\"5933\">444</sup> דא\"א כידוע) ששם גילוי עצמות אוא\"ס ב\"ה שלמעלה מעלה מכל ההשתלשלות דאבי\"ע (והוא למעלה מצמצום הראשון שנק' חשך סתרו<sup data-n=\"5934\">445</sup> ששם אור וחשך העלם וגילוי שוין וכמ\"ש במ\"א בענין טהרה שלמעלה מן הקדושה<sup data-n=\"5935\">446</sup> כמו כעצם השמים לטוה\"ר<sup data-n=\"5936\">447</sup> שהוא עצם בהירות האור בתקפו כו' וז\"ש לפני הוי' תטהרו שהוא מעין העוה\"ב ממש ונק' טה\"ע<sup data-n=\"5937\">448</sup> שלמעלה מהעלם וגילוי כו' ושם נא' כחשיכה כאורה כו'), ומשם יכול להתפשט השפע גם למטה מטה בירידות המדרגות היותר תחתון שהוא גם בחשך ואפילה דק\"נ שרש הרע גמור דרשעים לתקן הפגמים שלהם מן העוונות ש[י]הפכו מחשך לאור ממש, והוא סליחות העוונות ביו\"כ שהזדונות עצמן נהפכו לזכיות<sup data-n=\"5938\">449</sup> ממש כמ\"ש ויהפוך ה' את הקללה לברכה<sup data-n=\"5939\">450</sup> שהקללה עצמ[ה] מן הרע יתהפך<sup data-n=\"5940\">451</sup> לברכה כאשר הקטיגור נעשה סניגור<sup data-n=\"5941\">452</sup> כו' שנוסף ברכה על עצם הברכה שמן הטוב כמ\"ש במ\"א בענין טוב מאד זה מ\"ה<sup data-n=\"5942\">453</sup> [כ]שנהפך לחיים וטוב (כמו שנהפך מנג\"ע לענ\"ג<sup data-n=\"5943\">454</sup> ממש כו'). אך אין זה יכול להיות כ\"א ע\"י [ה]הארה מעצמות המאציל ממש ע\"י המשכת י\"ג מדה\"ר דרעדכ\"ר (שבמצחא דע\"י וא\"א<sup data-n=\"5944\">455</sup> כו' כמ\"ש והי' על מצחו<sup data-n=\"5945\">456</sup> כו') להיותו למעלה מעלה בבחי' רוממות העצמות שאין כל ההשתל' תופס מקום כלל וכלל וכמ\"ש אם צדקת<sup data-n=\"5946\">457</sup> מה תתן לו<sup data-n=\"5947\">458</sup> כו' ע\"כ נושא עון<sup data-n=\"5948\">459</sup> ועובר על פשע וכמ\"ש אנכי אנכי<sup data-n=\"5949\">460</sup> מוחה פשעיך כו' וד\"ל. וע\"כ כאשר חטאו ישראל בחטא העגל הוצרך [לתקן הפגם ע\"י המשכות י\"ג מדה\"ר<sup data-n=\"5950\">461</sup> דוקא, וזהו ויעבור ה' על פניו<sup data-n=\"5951\">462</sup> ויקרא ה' ה' אל רחום כו' מטעם הנ\"ל, ובחטא מרגלים הוצרך] משה <span data-k=\"pg\">קנד</span> ּ לעורר כח ועוז המשכ[ו]ת י\"ג מדה\"ר<sup data-n=\"5952\">463</sup> מלמטה",[["5930","441","<b>מר\"ח אלול שבו עלה משה</b>: ראה טור ושו\"ע הל' ר\"ה סתקפ\"א ובנ\"כ שם. הוספות לשו\"ע אדה\"ז הל' ר\"ה ובקו\"א שם (ע' תרפב). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091337\" data-slug=\"likkutei-sichot\" data-id=\"1300091337\">לקו\"ש</a> אלול (כרך ט) ס\"ע 310 ואילך בהערה."],["5931","442","<b>ביו\"כ</b>: ביד: ויו\"כ."],["5932","443","<b>לפני הוי' תטהרו</b>: נסמן להלן הערה 448."],["5933","444","<b>י\"ג מדה\"ר. . [י\"ג] ת\"ד</b>: ראה זהר (אד\"ר) נשא קלא, א. תרומה (ספדצ\"נ פ\"ת) קעז, א. ע\"ח (שער א\"א) שי\"ג, פ\"ט."],["5934","445","<b>מצמצום הראשון שנק' חשך סתרו</b>: תהלים יח, יב. ראה גם לקמן פ' בשלח קמז, ד. קצ, ד. תצוה שכד, ד. שסח, א. ויקהל תו, ד. פקודי תנד, א. ש\"א כח, ב. מאמרי אדה\"א נ\"ך ע' שצז. וש\"נ."],["5935","446","<b>טהרה שלמעלה מן הקדושה</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תקיח."],["5936","447","<b>כעצם השמים לטוה\"ר</b>: משפטים כד, י [ושם: וכעצם — ראה מאמרי אדה\"א דברים ח\"ד ע' א'תז. וש\"נ. שמות ח\"ב ע' שצו]."],["5937","448","<b>לפני הוי' תטהרו. . טה\"ע</b>: אחרי טז, ל. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'לח. ח\"ד ע' א'שלא ובהנסמן בהנ\"ל. לעיל פ' שמות ח, ד. לקמן פ' בשלח קנח, ד. רלז, ג. תצוה שמה, ד."],["5938","449","<b>שהזדונות עצמן נהפכו לזכיות</b>: ראה יומא פו, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא</a> פ\"ז. מאמרי אדה\"א בראשית ע' סג. וש\"נ. ש\"א עד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301550131\" data-slug=\"likkutei-sichot\" data-id=\"1301550131\">לקו\"ש עקב (כרך לד) ע' 60</a> ואילך ובהערות שם."],["5939","450","<b>ויהפך ה' את הקללה לברכה</b>: תצא כג, ו [בדילוג]. ראה מאמרי אדה\"א דברים ח\"ב ע' תרס ואילך (ובהנסמן בריש המאמר שם). לקמן פ' תצוה שעו, א."],["5940","451","<b>יתהפך</b>: ב: נהפך. יד: הפך."],["5941","452","<b>הקטיגור נעשה סניגור</b>: ע\"פ ברכות נט, א."],["5942","453","<b>טוב מאד זה מ\"ה</b>: בראשית א, לא. ראה ב\"ר פ\"ט, י. פיה\"מ פקכ\"ח ואילך. מאמרי אדה\"א בראשית ע' סג. שמות ח\"ב ע' תריג. דברים ח\"א ע' ז. וש\"נ."],["5943","454","<b>מנג\"ע לענ\"ג</b>: נסמן לעיל כ, ג."],["5944","455","<b>דע\"י וא\"א</b>: ב: דא\"א וע\"י."],["5945","456","<b>והי' על מצחו</b>: תצוה כח, לח."],["5946","457","<b>אם צדקת</b>: איוב לה, ז."],["5947","458","<b>מה תתן לו</b>: ביד: ליתא."],["5948","459","<b>נושא עון</b>: מיכה ז, יח."],["5949","460","<b>אנכי אנכי</b>: ישעי' מג, כה [בדילוג]."],["5950","461","<b>בחטא העגל. . י\"ג מדה\"ר</b>: ראה גם סידור כאן (רצט, ג). שער האלול (רכז, א) רכט, ג ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380852\" data-slug=\"likkutei-torah\" data-id=\"4001380852\">לקו\"ת ראה לד, ב</a>. מאמרי אדה\"ז תקס\"ז ע' שנא. דרמ\"צ קפד, ב. מאמרי אדה\"א במדבר ח\"ג ע' א'ע."],["5951","462","<b>ויעבור ה' על פניו</b>: תשא לד, ו."],["5952","463","<b>ובחטא מרגלים. . י\"ג מדה\"ר</b>: ראה שער מאמרי רשב\"י לזח\"ג רצה, א [רצה, ב בדפי הספר — תל-אביב תשכ\"א]. לקו\"ת — להאריז\"ל — תשא שם. דרמ\"צ ומאמרי אדה\"א שם."]]],[2300540736,"למעלה בא[מרו] ועתה יגדל נא<sup data-n=\"5953\">464</sup> כח אד[נ\"י] כו' כידוע. אך הנה לפי\"ז שמדה [זו] דארך אפיים שבי\"ג מדה\"ר באה מעוצם הרוממות לסלוח העוונות גם לרשעים גמורים מטעם הנ\"ל, הרי היא הנותנת שמאריך אף לרשעים כמו לצדיקים ממש בשוה מאחר שאין כל ההשתלשלו' תופס מקום כלל עד שכחשיכה כאורה כו' שמחמת זה גם החשך יהופך לאור וזדונות יהפכו לזכיות כנ\"ל, א\"כ יכול להיות שיומשך אור השפע האלקי' גם לקליפות שיקבלו יניקה גם הם כמו שנמשך לסט' דקדושה באין הפרש מפני שמצד עצם הרוממות שוה ומשוה לטובים ולרעים וכמו שמצינו בדור אנוש כנ\"ל, לפי שמשם יכול להאיר גם בחשך ואפילה דק\"נ וכמ\"ש גם חשך לא יחשיך ממך כו'. וכמו שמצינו שהי' גילוי אור האלקי בנבואה [ל]בלעם שהי' בתכלית הזוהמא של טומאה נחה\"ק כו' ויאמר ה' לבלעם<sup data-n=\"5954\">465</sup> כו' ויאמר ה' אל הנחש<sup data-n=\"5955\">466</sup> כו', ובאמת הרי א' לא יגורך רע<sup data-n=\"5956\">467</sup> לא יגור כלל במגורו וכתי' טהור עינים מראות ברע<sup data-n=\"5957\">468</sup> כו' ונק' תועבת ה' ואי[ך] ישרה שכינתו בהם, אך מטעם הנ\"ל דקמי' ממש כחשיכה [כאורה] כו' וכמו אם אסק שמים<sup data-n=\"5958\">469</sup> שם אתה ואציעה שאול הנך ממש כמו בשמים ממעל אין עוד<sup data-n=\"5959\">470</sup> כך מתח[ת] לארץ בהיכלות דק\"נ כו'. ולזאת הי[תה] בקשת משה שלא תשרה שכינה באוה\"ע כמ\"ש ונפלינו אני ועמך כו', ולכאורה מה הוצרך לבקש זאת אחר שלא יוכל להיות גילוי שכינה בכל דבר רע כנ\"ל וכמ\"ש וכבודי לאחר לא אתן כו'. אך מטעם הנ\"ל הוצרך לבקש (בא' פני ילכו<sup data-n=\"5960\">471</sup> כו' וא\"ל אם אין פניך הולכים<sup data-n=\"5961\">472</sup> אל תעלינו מזה ובמה יודע<sup data-n=\"5962\">473</sup> כו' ונפלינו אני ועמך כו' כמשי\"ת) שלא תשרה שכינה באוה\"ע וא\"ל<sup data-n=\"5963\">474</sup> הי' מבקש יכול להיות השראת השכינה באוה\"ע כמו בישראל ממש<sup data-n=\"5964\">475</sup> בשוה ממש משום דקמי' כחשיכה כאורה כנ\"ל, והבטיח לו ה' בא[מרו אליו] גם את הדבר הזה<sup data-n=\"5965\">476</sup> אשר דברת אעשה כי מצאת חן כו' נתקיימה<sup data-n=\"5966\">477</sup> שלא הי' עוד גילוי אלקות בנבואה באוה\"ע אחר בלעם [וד\"ל]. ועד\"ז יובן מ\"ש וימהר משה ויקוד כו' שראה מדת ארך אפים שבאה מעצם הרוממות דא\"ס",[["5953","464","<b>ועתה יגדל נא</b>: שלח יד, יז. ראה מאמרי אדה\"א שם ע' א'עא."],["5954","465","<b>ויאמר ה' לבלעם</b>: ביד: אלקים אל בלעם — בלק כב, יב."],["5955","466","<b>ויאמר ה' אל הנחש</b>: בראשית ג, יד [ושם: ה\"א]."],["5956","467","<b>לא יגורך רע</b>: תהלים ה, ה."],["5957","468","<b>טהור עינים מראות ברע</b>: חבקוק א, יג [ושם: רע — ראה מנחת שי שם. לקמן פ' יתרו רעא, ג. תצוה שנז, ג [הוגה מגוכתי\"ק]. שעב, ב. מאמרי אדה\"א בראשית ע' צו. שמות ח\"א ע' כה ובהנסמן בהנ\"ל]."],["5958","469","<b>אם אסק שמים</b>: תהלים קלט, ח."],["5959","470","<b>בשמים ממעל אין עוד</b>: ואתחנן ד, לט [בדילוג]."],["5960","471","<b>פני ילכו</b>: תשא לג, יד."],["5961","472","<b>אם אין פניך הולכים</b>: תשא שם, טו."],["5962","473","<b>ובמה יודע</b>: שם לג, טז."],["5963","474","<b>וא\"ל</b>: ביד: ואם לא."],["5964","475","<b>ממש</b>: שם: ליתא."],["5965","476","<b>גם את הדבר הזה</b>: תשא שם, יז."],["5966","477","<b>נתקיימה</b>: ביד: וכן נתקיים."]]],[2300540748,"ב\"ה שיכול להאריך אף [לרשעים כמו לצדיקים ממש בשוה מטעם הנ\"ל ע\"כ ביקש משה שלא יאריך אף] כ\"א לצדיקים ולא לרשעים כמו שביקש משה שלא תשרה שכינה באוה\"ע וד\"ל.\n<b>אך</b> עדיין י\"ל איך יוכל להיות שיאריך אף לצדיקים ולא לרשעים מאחר שמדה זאת דארך אפים באה מעצם הרוממות כו' דכולא קמי' כו'<sup data-n=\"5967\">478</sup> להיות[ו] למעלה מעלה מכל ההשתלשלו' [כנ\"ל] שמחמת זה הכל שוין<sup data-n=\"5968\">479</sup>. ועוד דעיקר מדה זו היא להאריך אף גם לעוברי רצונו כנ\"ל. אך הענין הוא דגם בעצם בחי' הרוממות שבעצמות שלמעלה מכל ההשתלשלו' יוכל להיות הבדלה בין פנימי' וחיצוני' כמו יאר ה' פניו אליך<sup data-n=\"5969\">480</sup> [אליך] דוקא וכתיב אהבתי אתכם<sup data-n=\"5970\">481</sup> כו' ואת עשו שנאתי<sup data-n=\"5971\">482</sup> כו' (וכמ\"ש במ\"א בענין ישראל ואוה\"ע עבמ\"ח<sup data-n=\"5972\">483</sup> [רק] שישראל עלו בבחי' הפנימי' דוקא [ו]כמ\"ש יבחר לנו<sup data-n=\"5973\">484</sup> כו' הבוחר בעמו ישראל<sup data-n=\"5974\">485</sup> כו' וכמ\"ש בהבדלה המבדיל כו'). וזהו כמשל הפנים באדם שמורה על בחי' הפנימי' ועצמי' והעורף למול פנים שהוא בחי' הרצון [החיצוניו' והוא חיצוניו'] ו[ב]מצח הוא פנימי' הרצון ופנימי' המוחי' כו'. וז\"ש [משה] אם אין פניך דוקא הולכים [כו'] שביקש משה<sup data-n=\"5975\">486</sup> שגם בעצמות הרוממות יובדל הפנימי' מן החיצוני' ואז ונפלינו אני ועמך כו' לא תשרה שכינה באוה\"ע <span data-k=\"pg\">310</span> ּ כנ\"ל, [וממילא גם במדה הזאת דארך אפי' הגם ששרשה באה מבחי' העצמות ממש כנ\"ל] ביקש משה שלא יאריך אף כ\"א לצדיקים ולא לרשעים מפני שיובדל גם במדה זו ג\"כ הפנימי' מן החיצוני' והוא כדי<sup data-n=\"5976\">487</sup> שיאר ה' פניו רק לצדיקים ולא לרשעים ששרשם רק [ב]בחי' אחוריים בבחי' עורף שאחורי המצח כו' כך לא יומשך בחי' ארך אפיים רק לבחי' הפנימי' שהן [ה]צדיקים ולא יומשך לרשעים כלל ולא כמו שהי' בדור אנוש כו', וזהו וימהר משה ויקוד ארצה כו' וד\"ל (ומה שאנו רואים בכל ימי הגלות שמאריך אף לרשעים להשפיע להם כל טוב עוה\"ז הגם שעוברים על ז' מצות בני נח<sup data-n=\"5977\">488</sup> כמו גזל ועריות וע\"ז וש\"ד כו', ומה ששחק ר\"ע ואמר אם לעוברי רצונו כך<sup data-n=\"5978\">489</sup> כו' היא גופא קשי' למה יאריך אפו לעוברי רצונו כך כו', הענין הוא ע\"ד שא' ומשלם לשונאיו<sup data-n=\"5979\">490</sup> אל פניו כו' שמשלם רוב טובה יתירה על המדה ומשפט התורה כדי להאבידו בעוה\"ב וכמו אם רעב שונאך<sup data-n=\"5980\">491</sup> האכילהו לחם כו' וד\"ל ועוד מטעם ענין הבירורים דרפ\"ח כידוע בסוד ענין גלות השכינה<sup data-n=\"5981\">492</sup> בע\"ש<sup data-n=\"5982\">493</sup> דנוגה כו').\n<b>והנה</b> אחר כ\"ז יובן מאמר ההגדה אף אתה הקהה את שיניו ואמור לו בעבור זה עשה ה' [לי] לי ולא לו כו'.",[["5967","478","<b>כו'</b>: ב: כלא. יד: כנ\"ל שמחמת זה הכל שוין."],["5968","479","<b>[כנ\"ל]. . שוין</b>: יד: ליתא. וראה הערה שלפנ\"ז."],["5969","480","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["5970","481","<b>אהבתי אתכם </b>[ב: ניתוסף: אמר]: מלאכי א, ב."],["5971","482","<b>ואת עשו שנאתי</b>: מלאכי שם, ג."],["5972","483","<b>ישראל ואוה\"ע עבמ\"ח</b>: ראה גם לקמן פ' בשלח קלה, א ובהערה 113."],["5973","484","<b>יבחר לנו</b>: נסמן לעיל לה, ג."],["5974","485","<b>הבוחר בעמו ישראל</b>: ברכת — אהבת עולם — ק\"ש."],["5975","486","<b>משה</b>: ביד: ליתא."],["5976","487","<b>כדי</b>: ביט: ליתא."],["5977","488","<b>ז' מצות בני נח</b>: נסמן לעיל פ' וארא ס, א."],["5978","489","<b>אם לעוברי רצונו כך</b>: מכות כד, ב."],["5979","490","<b>ומשלם לשונאיו</b>: נסמן לעיל ל, ד."],["5980","491","<b>אם רעב שונאך</b>: נסמן לעיל שם."],["5981","492","<b>גלות השכינה בע\"ש</b>: ראה גם לעיל פ' שמות ל, ד."],["5982","493","<b>בע\"ש</b>: נסמן לעיל לז, ג."]]],[2300540760,"<b>דהנה</b> י\"ל תחלה פתיחת ההגדה עבדים היינו לפרעה כו' שזהו פתיחה כללית למה שא' אח\"כ, להיות שבאמת יפלא למה היינו עבדים לפרעה כו' ואח\"כ ויוציאנו ה' ממצרים כו', להיות מבואר למעלה שבחי' עצמות הרוממות דא\"ס ב\"ה שם הכל יכולים לקבל בשוה משום דקמי' כחשיכה כאורה שוין כו', ו[ע]\"כ גם שפרעה הי' שרשו מבחי' עורף<sup data-n=\"5983\">494</sup> העליון שהוא בחי' אחוריים דכת\"ר עליון המאיר בפנימי' כו' וישראל שרשם בבחי' הפנימי'<sup data-n=\"5984\">495</sup> ל' רא\"ש<sup data-n=\"5985\">496</sup> כו', הרי<sup data-n=\"5986\">497</sup> יכול להיות להיפך ממש שישראל היו עבדים לפרעה כו', לפי שלגבי רוממות העצמות אין הפרש כלל ויכול גם פרעה ששרשו מעורף לקבל יניקה מהקדושה וישראל שהן בבחי' פנימי' יהיו לו לעבדים (וכך הוא בכל הגלות) מאחר שחש\"ך ואור שוין שם כו'<sup data-n=\"5987\">498</sup>. [ו]זהו שא' שמתחילה עבדים היינו לפרע\"ה מטעם הנ\"ל, אבל אח\"כ ויוציאנו ה' כו' מפני שגם ברוממות העצמות הובדלו בחי' הפנימי' מן החיצוני' עד שגם בבחי' כת\"ר עליון יצא לחלק בין פנים לעורף שאין עיקר האור והשפע הפנימי' הולך רק לבחי' הפנימי' ולא לחיצוני' ואחוריי' [כלל], רק כמאן דשדי בתר כתפוי<sup data-n=\"5988\">499</sup> בבחי' חיצוני' הרצון מאד כו', וע\"כ הוציאנו ה' ממצרים בדרך הבדלה להוציא בחי' הפנימי' מן החיצוני' וכמ\"ש או הנסה אלקי' לבא לקחת<sup data-n=\"5989\">500</sup> [לו] גוי מקרב גוי כו' וד\"ל. וכמו [כן] בקי\"ס אע\"פ שטע[נה] מדה\"ד מה נשתנו אלו מאלו<sup data-n=\"5990\">501</sup> כו', מ\"מ פרעה וחילו טבעו בי\"ס וישראל עברו בים ביבשה לפי שנעשה בחי' הבדלה כנ\"ל וכפי בקשת משה הנ\"ל גם אחר שחטאו בעגל שהורד עדיים<sup data-n=\"5991\">502</sup> שקיבלו בהר חורב כו' פעל שיחזיר להם<sup data-n=\"5992\">503</sup> והוא מ\"ש אם אין פניך הולכים כו' כנ\"ל. וז\"ש אף אתה אמור לו בעבור זה עשה ה' לי דוקא [לי] ולא לו כו', דהנה מבואר למעלה בפי' שבעבור ז\"ה שהוא בחי' המשכת עצמות אור אבא שע\"י המצה שנק' זה כו' שבו בחי' גילוי אור [ה]פנימי' [מ]עצמו' דא\"ס ב\"ה שהוא בבחי' ההבדלה בין [ה]פנימי' לחיצוני' <span data-k=\"pg\">קנה</span> ּ כנ\"ל בעיקר ענין יצ\"מ וכבקשת משה כנ\"ל, וזהו בעבור ז\"ה דבחי' התגלות פנימיות אוא\"ס לא עשה ה' רק [לי] לישראל לבדם ולא [לו] לרשעים שנבדלו בבחי' החיצוני' ואחוריים כנ\"ל, ואלו הי' שם לא הי' נגאל כלל לפי שכבר הובדל[ה] הפנימי' מן החיצוני' לגמרי ואין לחיצוני' ואחוריי' דק\"נ שום שרש יניקה ואחיזה בפנימי' דקדושה כלל וכלל, וע\"כ גם אם הי' שם בשעה שנגלה עליהם מלך כו' וגאלם לא הי' נגאל בבחי' גאולה זו דגילוי שכינה עצמה בבחי' הפנימי' שהי' בצאתם ממצרים בבחי' הבדלה הנ\"ל, והיינו עשה ה' לי לבחי' פנים ולא לו שעומד בבחי' אחוריים מטעם",[["5983","494","<b>שפרעה. . עורף</b>: נסמן לעיל יט, ב."],["5984","495","<b>בפנימי'. . הפנימי'</b>: ב: בפני'. יד: בפנים. . ביד: בפנים."],["5985","496","<b>וישראל. . ל' </b>[ב: לי]<b> רא\"ש</b>: נסמן לעיל פ' שמות יח, ב."],["5986","497","<b>הרי</b>: ביד: הי'."],["5987","498","<b>כו'</b>: ביד: כנ\"ל."],["5988","499","<b>כמאן דשדי בתר כתפוי</b>: ראה תניא פכ\"ב."],["5989","500","<b>או הנסה. . לקחת</b>: ואתחנן ד, לד. ראה גם לעיל סד, ב."],["5990","501","<b>מה נשתנו אלו מאלו</b>: נסמן לעיל פח, ד."],["5991","502","<b>שהורד עדיים</b>: תשא לג, ד-ו."],["5992","503","<b>פעל שיחזיר להם</b>: ראה מאמרי אדה\"ז תק\"ע ע' לז. וע' מב. מאמרי אדה\"א נ\"ך ע' תנב וע' תקכא. פני דוד — להחיד\"א — ר\"פ ויקהל-פקודי."]]],[2300540772,"ההבדלה הנ\"ל<sup data-n=\"5993\">504</sup>. ועד\"ז<sup data-n=\"5994\">505</sup> יובן ג\"כ בענין ועברתי באמ\"צ אני ולא מלאך עד אני הוי' אני הוא ולא אחר שהוא ע\"י בחי' ההבדלה הנ\"ל, ע\"כ בעברו במצרים פסח [ה'] על הפתח כו' להבדיל בין בחי' פנים לאחוריים עד גם באלקי מצרים עשה שפטים להבדילם מן בחי' הפנימי' דקדושה לגמרי וממילא נאבדו וכמ\"ש בזהר עמ\"ש ויסר את אופן מרכבותיו דתבר שלשליהון לעילא<sup data-n=\"5995\">506</sup> כו'. וזהו [מ\"ש] אני ה' בחי' פנימי' בפנימי'<sup data-n=\"5996\">507</sup> דשם הוי' דחכ' דאור אבא ולא אחר פי' ולא בבחי' אחוריים דעורף ששם יניקה לאחר כו' כי אין בפנימי' שום יניקה לאחר כלל וד\"ל (וע\"כ לא הי' באפשר להיות זה ע\"י מלאך ושרף ושליח שהן בבחי' ההשתל' דבי\"ע [כנ\"ל ב]א' אני הוי' שבפנימי' אבא ששם מקור הכח להבדל[ה] זו וד\"ל).\n<b>ומעתה</b> י\"ל מ\"ש במאמר זה דתשובה זאת אף אתה אמור לו ה[י]א לרשע דוקא שאו' מה העבודה הזאת לכם ולא לו הוציא א\"ע מן הכלל כו', דהנה מבואר בס' הקבלה בכללות ענין ד' בנים הללו א' חכם וא' רשע ותם ושאינו יודע לשאול שהוא בחי' קטנות דשם ב\"ן<sup data-n=\"5997\">508</sup> שבכל עולם עד עולם העשי', והוא מ\"ש חכם מה הוא אומר מה העדות כו' הוא בחי' החכ' שהוא בחי' פנימיות שבכל עולם שכלול מג' מוחין חב\"ד שהוא הראשית שבהם נמשך גילוי אוא\"ס תחלה כידוע שאין התלבשות אוא\"ס רק בבחי' אין דחכמה כמו במע\"ב דכתי' בראשית ברא בחוכמתא<sup data-n=\"5998\">509</sup> כו', ומבחי' המוחין דחב\"ד נמשך למדות חג\"ת ומחג\"ת לנהי\"[ם] כו' וא\"א שיבא השפע למקבלים בלתי בחי' אור החכ' בתחלה כמו כולם בחכמה עשית<sup data-n=\"5999\">510</sup>. וכך הוא בכל בחי' גילוי אור האלקי' הבא [מלמעלה למטה צריך שיעבור תחלה דרך בחי' המוחי' דחב\"ד כו', ובכאן ביצ\"מ הי' בחי' הדילוג הגדול מעצמות המאציל בהתלבשות] בהעלם בקטנות דאבא מבחי' ג\"ר דחכמה שהוא בחי' מקיף על בחי'<sup data-n=\"6000\">511</sup> גילוי אור המוחי' דחב\"ד [כו'], ע\"כ החכ\"ם מתפלא ביותר [ואו'] מה העדות והחוקים והמשפטים שהן בחי' [ה]מוחי' הפנימי' דתורה שנחלקו לג' קוין עדות חוקים ומשפטים שנתלבשו במצה ופסח אשר ציוה ה' אלקינו שהוא פנימי' חו\"ב<sup data-n=\"6001\">512</sup> אתכם בכנס\"י שהוא בחי' המל' בבי\"ע, ומפני שאינו משיג שרש העדות כו' מאין בא עליהם שלא ע\"י חכמה שבו שהי' צריך לעבור האור ע\"י בחי' המוחי' דחב\"ד",[["5993","504","<b>הנ\"ל</b>: ביד: וד\"ל."],["5994","505","<b>ועד\"ז</b>: ידיט: ועם זה."],["5995","506","<b>ויסר. . דתבר שלשליהון לעילא</b>: בשלח יד, כה. ראה זהר בשלח מט, א."],["5996","507","<b>בחי' פנימי' בפנימי'</b>: ביד: בבחי' הפנימיות."],["5997","508","<b>ד' בנים. . דשם ב\"ן</b>: ראה פע\"ח (שחה\"מ) שכ\"א, פ\"ז במקומו."],["5998","509","<b>בראשית ברא בחוכמתא</b>: בראשית א, א. וראה תרגום ירושלמי שם."],["5999","510","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["6000","511","<b>בחי'</b>: ביד: ליתא."],["6001","512","<b>ה' אלקינו. . חו\"ב</b>: נסמן לעיל פט, ב הערה 109."]]],[2300540783,"תחלה כשאר ההשתל' כנ\"ל, אך מפני שהי' בחי' הדילוג הגדול על המוחי' דחב\"ד מבחי' המקיף דאור אבא שמלובש בג\"ר שבו<sup data-n=\"6002\">513</sup> שזהו בחי' כת\"ר דחכמה כנ\"ל, ע\"כ אין החכ\"ם יודע מזה [כלל] ולכך לפלא גדול בעיניו מאין בא לכנס\"י בחי' המוחי' הללו דעדות וחוקים כו' אשר צוה ה' אלקינו אתכם מפני שאין לו השגה בהם כלל מטעם הדילוג כנ\"ל וד\"ל. ואף אתה אמור לו כהלכות הפסח אין מפטירין אחר הפסח <span data-k=\"pg\">312</span> ּ אפיקומן<sup data-n=\"6003\">514</sup>, פי' שצריך לגלות לחכם זה סוד ושרש ענין הפסח שהוא בחי' הדילוג הגדול שהי' בחצות הלילה דוקא וכמ\"ש ופסח ה' על הפתח כו' והי' בזה ענין ההבדלה בין הפנימי' לחיצוני' כנ\"ל כמ\"ש ועבר ה' לנגוף<sup data-n=\"6004\">515</sup> [כו']. ובזה יתורץ קושייתו מה שציוה ה' אתכם דוקא וזהו שאו' לו אין מפטירין אחר הפסח<sup data-n=\"6005\">516</sup> כו' שמזרז על חצות לילה שעובר זמן אכילת פסח.\n<b>וענין</b> רשע מה הוא אומר כו', הנה מבואר למעלה שיש בחי' פנימי' וחיצוני' ואחוריי' בכל מדרגה גם ברצון וחכמה כו', וגם בבחי' החכמה יש פנים ואחור כמו מגילה כתובה פנים ואחור<sup data-n=\"6006\">517</sup> כו' וכמו חכם באחור ישבחנה כו', וכמו שהעורף הוא אחוריים דרצון העצמי' והפנימי'<sup data-n=\"6007\">518</sup> שבמצח כך יש מנגד לעומת החכ' שבפנימי'<sup data-n=\"6008\">519</sup> היפך בחי' הביטול דאין שבחכ' והוא בחי' השמרים והפסולת דחכמה שהוא בחי' הישות והגסות<sup data-n=\"6009\">520</sup> שבחכ' כמו ראיתי איש חכם בעיניו<sup data-n=\"6010\">521</sup> כו' וכמו שמבואר במ\"א בענין מ\"ש לא בים היא<sup data-n=\"6011\">522</sup> במי שמרחיב דעתו על[י'] כים, לא תמצאינה בגסה\"ר [כו']. וזהו כמו ענין ופלגשו ושמה ראומ\"ה<sup data-n=\"6012\">523</sup> ראו שאני בטל כו', ומזה [מ]סתעף בחי' הגבו' הקשות שבחכ' שנק' חויא דרבנן<sup data-n=\"6013\">524</sup> בסט' דקדושה כידוע בענין נח\"ש הנחושת<sup data-n=\"6014\">525</sup> כו' שהוא בחי' קטנות דיסוד אבא (כידוע בענין בא נח\"ש על חו\"ה<sup data-n=\"6015\">526</sup> בחי' אחוריים דשם מ\"ה<sup data-n=\"6016\">527</sup> ו[ב]ענין לו\"ט גימ' מ\"ה<sup data-n=\"6017\">528</sup> לווטי' וקללות<sup data-n=\"6018\">529</sup> שהוא אחוריים דמ\"ה דחכמה דאברהם אב\"ר מ\"ה<sup data-n=\"6019\">530</sup> דקדושה וכמ\"ש הפרד נא מעלי<sup data-n=\"6020\">531</sup> כו', וזהו כל שאינו נוקם ונוטר כנח\"ש<sup data-n=\"6021\">532</sup> אינו ת\"ח ואמנם זהו בבחי' הקדושה עדיין רק שהוא מצד בחי' הקטנות שמלא גבו' כו'). ויוכל להתהפך לחסדים כמו בנחש הנחשת שעשה משה שכל הנשוך מנחשים השרפים כאשר הביט בו וחיה<sup data-n=\"6022\">533</sup> כו' (והיינו בחי' רש\"ע דקדושה בחי' אחוריי' דשם ב\"ן דמ\"ה), אך מסתעף מזה בחי' גבו' קשות דק\"נ [ממש]",[["6002","513","<b>שבו</b>: ביד: ליתא."],["6003","514","<b>אחר הפסח אפיקומן</b>: ב: אחר כו'. ידיט: כו'."],["6004","515","<b>ועבר ה' לנגוף</b>: בא יב, כג."],["6005","516","<b>אחר הפסח</b>: ביד: ליתא."],["6006","517","<b>מגילה כתובה פנים ואחור</b>: ראה זכרי' ה, א. ב. יחזקאל ב, י. עירובין כא, א. לקמן פ' תצוה שמב, ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תעג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680310\" data-slug=\"torat-chaim\" data-id=\"2300680310\">תו\"ח וישלח קפה, ג</a>."],["6007","518","<b>העצמי' והפנימי'</b>: ביד: הפנימי' ועצמי'."],["6008","519","<b>שבפנימי'</b>: שם: שבפנים."],["6009","520","<b>הישות והגסות</b>: שם: הגסות והישות."],["6010","521","<b>ראיתי איש חכם בעיניו</b>: משלי כו, יב."],["6011","522","<b>לא בים היא</b>: נצבים ל, יג [ושם: ולא מעבר לים — ראה שע\"ת כג, ב ובהערה 20]. עירובין נה, א (כגי' הע\"י). ראה גם לעיל פ' שמות ג, ד. וארא פג, ב."],["6012","523","<b>ופלגשו ושמה ראומ\"ה</b>: וירא כב, כד. ראה מאמרי אדה\"א דברים ח\"ד ע' א'תצג. וש\"נ. שעה\"י קמא, א ובהערה 16."],["6013","524","<b>חויא דרבנן</b>: שבת קי, א. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקלח. ויקרא ח\"א ע' רמ. במדבר ח\"ב ע' תתיב. דברים ח\"ב ע' תרטו. הנחות תקע\"ז ע' מא. אמ\"ב שער הציצית פד, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670338\" data-slug=\"torat-chaim\" data-id=\"2300670338\">תו\"ח נח נא, ב</a> ובהערה 25."],["6014","525","<b>נח\"ש הנחושת</b>: חוקת כא, ט. ראה לקו\"ת חוקת סא, ד ואילך. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תקלח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680346\" data-slug=\"torat-chaim\" data-id=\"2300680346\">תו\"ח ויגש רלה, ד</a>."],["6015","526","<b>בא נח\"ש על חו\"ה</b>: שבת קמו, רע\"א."],["6016","527","<b>חו\"ה בחי' אחוריים דשם מ\"ה</b>: נסמן לעיל קיג, ד הערה 134."],["6017","528","<b>לו\"ט גי' מ\"ה</b>: ראה מאו\"א ותו\"א שבהערה הבאה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670280\" data-slug=\"torat-chaim\" data-id=\"2300670280\">תו\"ח לך פד, א</a> ובהערה 12."],["6018","529","<b>לוט. . לווטי' וקללות</b>: ראה ע\"ח (שער ק\"נ) שמ\"ט, פ\"ט. מאו\"א מערכת לוט סכ\"ז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370051\" data-slug=\"torah-or\" data-id=\"3901370051\">תו\"א לך יא, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670503\" data-slug=\"torat-chaim\" data-id=\"2300670503\">תו\"ח שם פט, ג</a>."],["6019","530","<b>דאברהם אב\"ר מ\"ה</b>: ראה זהר בהקדמה ד, רע\"א."],["6020","531","<b>הפרד נא מעלי</b>: לך יג, ט."],["6021","532","<b>כל שאינו נוקם ונוטר כנח\"ש</b>: ראה יומא כב, סע\"ב ואילך."],["6022","533","<b>שכל הנשוך. . וחיה </b>[ביד: וחי']: חוקת כא, ט."]]],[2300540794,"שזהו בחי' רש\"ע דקליפה כמו ולרש\"ע א'<sup data-n=\"6023\">534</sup> מה לך לספר חוקי שהוא העובר עמ\"ש בתו' שלומד ו[כ]לומד שלא לשמה ממש שע\"ז א' למשמאילים בה סמא דמותא<sup data-n=\"6024\">535</sup> ממש<sup data-n=\"6025\">536</sup> להיות ממש היפך דחכ' דתורה דשם מ\"ה שהוא בבחי' הביטול בתכלית כו'. ולהיותו בבחי' הפירוד ממש המנגד לבחי' הביטול דמ\"ה דחכ' ע\"כ א' רש\"ע מה הוא אומר מה העבודה הזאת לכם [לכם] ולא לו שמוציא א\"ע מן הכלל כו', לפי שעבודה הזאת דמצה ופסח הוא בבחי' הביטול העצמי ופנימי דפנימי' שם מ\"ה דאור אבא כו' ע\"כ מאד הוא לנגד העבודה הזאת ושונא אותה ביותר, ע\"כ מוציא עצמו מן הכלל<sup data-n=\"6026\">537</sup> היחוד העליון דעצמות א\"ס בפנימי' אבא ואו' מה העבודה הזאת לכם דוקא לכם הוא שאתם בחי' המל' שעולה עד הכת\"ר כו' ולא לו מפני שהובדל מבחי' הפנימי' לגמרי כנ\"ל וזהו שכפר בעיקר בעיקרא ושרשא דכ\"ע<sup data-n=\"6027\">538</sup> שהוא בחי' אני הוי' דאבא הנ\"ל שהוא פנימי' דשם מ\"ה וע\"כ צריך להשיב [לו] כדרכו ומדריגתו שעומד בחוץ בבחי' אחוריים המנגד לפנים כנ\"ל אף אתה הקהה את שיניו כנ\"ל<sup data-n=\"6028\">539</sup>. דהנה כתי' שיני רשעים שברת<sup data-n=\"6029\">540</sup> כו' דכמו שבסט' דקדושה השיניים הן ל\"ב נ\"ח<sup data-n=\"6030\">541</sup> שהן המבררים וטוחני'<sup data-n=\"6031\">542</sup> המאכל להבדיל בין הפנימי' לחיצוני' וזהו ענין שבחכ' אתברירו<sup data-n=\"6032\">543</sup> והוא ע\"י לימוד התורה בדיבור בפה<sup data-n=\"6033\">544</sup> דוקא שנק' גירסא גר\"ש כרמל<sup data-n=\"6034\">545</sup> כידוע דאבא יסד ברת\"א שזהו עיקר תכלית מצות ת\"ת דאורייתא <span data-k=\"pg\">קנו</span> ּ מח\"ע נפקת ועיקר שלימותא כשבאים<sup data-n=\"6035\">546</sup> בגרסא דוקא כמ\"ש ואשים דברי בפיך<sup data-n=\"6036\">547</sup> כו' למען תהי'<sup data-n=\"6037\">548</sup> כו' בפיך דוקא. וזהו כי לא על הלחם [לבדו] דחכמה יחי' האדם [כ\"א על<sup data-n=\"6038\">549</sup> כל מוצא פי הוי' בדיבור יחי' האדם] מטעם דזהו עיקר הבירור להבדיל בין טמא לטהור וכו\"פ כו'. אבל לעו\"ז יש בסט' דקליפה והן שיני רשעים דאחוריים דחכ' דקדושה המנגד לה בתכלית כנ\"ל והן היפוך הבירור דחכ' דקדושה ששיני רשעים כמו חץ שחוט<sup data-n=\"6039\">550</sup> וכתער מלוטש<sup data-n=\"6040\">551</sup> להוסיף יניקה לחיצונים [ו]כמ\"ש ולרשע א' מה לך לספר חוקי כו' מפני שמוסיף יניקה מן הקדושה הפנימי' לחיצוני' כו'. וזהו ענין אכלם משפע אור הקדושה כמו ויאכלו את ישראל<sup data-n=\"6041\">552</sup> כו' וכמו ברוך ה'<sup data-n=\"6042\">553</sup> שלא נתננו טרף לשיניהם כו' וכ\"ש ע\"י הקטרוגים שלהם ששיניהם חנית וחיצים<sup data-n=\"6043\">554</sup> וכמו תאלמנה שפתי שקר<sup data-n=\"6044\">555</sup> הדוברות על צדיק<sup data-n=\"6045\">556</sup> כו' בגאוה ובוז כו'",[["6023","534","<b>ולרשע א' </b>[ידיט: ליתא]: תהלים נ, טז [בדילוג]."],["6024","535","<b>למשמאילים בה סמא דמותא</b>: ראה גם לעיל פ' שמות ג, ב. וש\"נ."],["6025","536","<b>ממש</b>: ביט: ליתא."],["6026","537","<b>עצמו מן הכלל</b>: ביט: א\"ע מכלל. יד: עצמו מכלל."],["6027","538","<b>דכ\"ע</b>: ביד: דכל העולמו' — זהר בהקדמה יא, ב."],["6028","539","<b>כנ\"ל</b>: ביד: כו'."],["6029","540","<b>שיני רשעים שברת</b>: תהלים ג, ח."],["6030","541","<b>השיניים הן ל\"ב נ\"ח</b>: ראה ע\"ח־ מבו\"ש־ פע\"ח שנסמנו לעיל פ' שמות טו, ג הערה 665."],["6031","542","<b>השיניים. . וטוחני'</b>: ראה זהר (רעיא מהימנא) נשא קכא, ב. שבת קנב, א."],["6032","543","<b>שבחכ' אתברירו</b>: נסמן לעיל י, ג."],["6033","544","<b>לימוד התורה בדיבור בפה</b>: נסמן לעיל פ' וארא פ, ג."],["6034","545","<b>גירסא גר\"ש כרמל</b>: ויקרא ב, יד. ראה מאמרי אדה\"א בראשית ס\"ע תפד ואילך. וש\"נ. שמות ח\"א ע' קמה. לקמן פ' ויקהל תיט, ג."],["6035","546","<b>כשבאים</b>: ביט: כשבא. יד: כשבאה."],["6036","547","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["6037","548","<b>למען תהי'</b>: בא יג, ט."],["6038","549","<b>כי לא. . כ\"א על</b>: עקב ח, ג [ושם: כי על — ראה מאמרי אדה\"א בראשית ע' תפו. דברים ח\"ב ס\"ע תג]."],["6039","550","<b>חץ שחוט</b>: ירמי' ט, ז."],["6040","551","<b>וכתער מלוטש</b>: תהלים נב, ד."],["6041","552","<b>ויאכלו את ישראל</b>: ישעי' ט, יא."],["6042","553","<b>ברוך ה'</b>: תהלים קכד, ו."],["6043","554","<b>ששיניהם חנית וחיצים</b>: תהלים נז, ה."],["6044","555","<b>תאלמנה שפתי שקר</b>: תהלים לא, יט."],["6045","556","<b>הדוברות על צדיק</b>: ב: ליתא. ידיט: הדוברות."]]],[2300540804,"וכמ\"ש בתלים בכמה מקומות. וע\"ז א' אף אתה הקהה את שיניו לשבור שיני רשעים שאו' לכם להיות שכבר הובדל הפנימי' מן החיצוני' כמ\"ש בעבור זה עשה הוי' לי דוקא לי ולא לו לפי שלא יוכלו לקבל יניקה עוד מבחי' הפנימי' ע\"כ ממילא נשברו שיני רשעים שלא יקבלו יניקה מן הקדושה [וז\"ש ואמור לו בעבור זה] כו' אלו הי' שם לא הי' נגאל כו' (ועוד יתפרש הקהה את שיניו אות השי\"ן שברשע שהוא ב'<sup data-n=\"6046\">557</sup> קוין המוחי' דחב\"ד שנמשך לר\"ע דקליפה כמו חכמים המה להרע<sup data-n=\"6047\">558</sup> כו' וממילא לא נשאר רק הרע לבד מצד עצמו בלי חיבור וקשר כלל עם החכמה דקדושה, וזהו עיקר הבירור של [ה]רשעים וכמו [ו]יתבררו רשעים<sup data-n=\"6048\">559</sup> ויתלבנו כו' מפני ש[ב]שי\"ן דחכמה גם שהוא נמשך ברע יש בו תערובות טו\"ר<sup data-n=\"6049\">560</sup> עדיין משרש ומקור דחכ' דקדושה רק שנתערב ברע ביותר כמו בחטא עה\"ד טו\"ר כמו אני חכמה שכנתי ערמה<sup data-n=\"6050\">561</sup> כו', אבל לאחר שהקהה את שי\"ן דרש\"ע לא נשאר בו שום חלק טוב דחכמה רק אותיות ר\"ע לבד ואין לרע מצד עצמו קיום במציאות כלל כשאין בו שום טוב רק רע לבד שאין רע יורד מלמעלה<sup data-n=\"6051\">562</sup> [כו'] ואין קיום במציאות לרע רק מתערובות חלק הטוב שבו כידוע בענין סר צלם מעליהם<sup data-n=\"6052\">563</sup> צ\"ל דחכמה שכולם בחכ' עשית כו'. ולכך אברהם כבש הד' מלכים<sup data-n=\"6053\">564</sup> מפני שהפריד מהם כל בחי' הטוב שבהם לגמרי ע\"י שהפריד בעצמו מכל תערובות רע וכמ\"ש ויחלק עליהם לילה ליל ה'<sup data-n=\"6054\">565</sup> כמ\"ש במ\"א, וז\"ש איכה ירדוף אחד אלף<sup data-n=\"6055\">566</sup> כו'. וגם כאן כשיקהה את שיני רשעים שהוא שי\"ן דרשע ישאר בלא חיות כלל וכמ\"ש תמותת רשע רע\"ה<sup data-n=\"6056\">567</sup> שהרע\"ה עצמה תמ[י]תהו כעלוקה<sup data-n=\"6057\">568</sup> שמושכת הדם ומתה כמ\"ש במ\"א<sup data-n=\"6058\">569</sup> וד\"ל (וכ\"ז [עולה] בענין א' עם מ\"ש בכוונתו בהגדה<sup data-n=\"6059\">570</sup> חכם מ\"ה הוא אומר כו' דחכמה הוא בקו הימין כו' ורשע בקו השמאל ותם בקו האמצעי ושאינו יודע לשאול במל' כמשי\"ת).\n<b>ומעתה</b> י\"ל מ\"ש תם מה הוא אומר<sup data-n=\"6060\">571</sup> מה זאת<sup data-n=\"6061\">572</sup> כו', הנה ידוע במ\"ש בזוהר בבחי' תמי\"ם ת\"ם י\"ם<sup data-n=\"6062\">573</sup> דחכ' שהוא בחי' קטנות המוחין שבמדות שלמטה מן הדעת המתפשט במדות כו', ואמנם יש בו בחי' הביטול שלמעלה מן הדעת שהוא תו\"ם בחול\"ם<sup data-n=\"6063\">574</sup> כמו הולך בתו\"ם<sup data-n=\"6064\">575</sup> כו' בבחי' ביטול עצם נקודת",[["6046","557","<b>ב'</b>: ידיט: ג'."],["6047","558","<b>חכמים המה להרע</b>: ירמי' ד, כב."],["6048","559","<b>וכמו. . רשעים</b>: ידיט: ליתא."],["6049","560","<b>טו\"ר</b>: ביד: טוב."],["6050","561","<b>אני חכמה שכנתי ערמה</b>: משלי ח, יב."],["6051","562","<b>שאין רע יורד מלמעלה</b>: נסמן לעיל פ' וארא נח, ד."],["6052","563","<b>סר צלם מעליהם</b>: שלח יד, ט."],["6053","564","<b>אברהם כבש הד' מלכים</b>: לך יד, יד-טו."],["6054","565","<b>ויחלק עליהם לילה ליל ה'</b>: לך יד, טו. ראה מאמרי אדה\"ז הקצרים ע' קמו. שע\"ת נא, ב. לעיל פח, ג. לקמן פ' תצוה שכט, ד בשם הזהר."],["6055","566","<b>איכה ירדוף אחד אלף</b>: האזינו לב, ל."],["6056","567","<b>תמותת רשע רעה</b>: תהלים לד, כב. ראה מאמרי אדה\"א נ\"ך ע' תצח. וש\"נ."],["6057","568","<b>כעלוקה</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תרח. וש\"נ. שע\"ת נא, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670154\" data-slug=\"torat-chaim\" data-id=\"2300670154\">תו\"ח בראשית לב, א</a> ובהערה 6. לקמן פ' ויקהל תט, ג."],["6058","569","<b>כמ\"ש במ\"א</b>: ביד: ליתא."],["6059","570","<b>בכוונתו בהגדה</b>: יד: בכונות דהגדה — ראה פע\"ח (שחה\"מ) שכ\"א, פ\"ז במקומו."],["6060","571","<b>תם מה הוא אומר</b>: הגש\"פ (פיסקא זו). מכילתא בא יג, יד."],["6061","572","<b>מה זאת</b>: בא יג, יד."],["6062","573","<b>תמי\"ם ת\"ם י\"ם</b>: ראה זהר שלח קסד, ב."],["6063","574","<b>תו\"ם בחול\"ם</b>: ראה מאמרי אדה\"א דברים ח\"א ע' קז. וש\"נ."],["6064","575","<b>הולך בתו\"ם</b>: משלי י, ט."]]],[2300540813,"הרצון כו' שזהו ביטול הפנימי' והעצמי' שבפנימי' דחכ' בחי' מ\"ה בעצם כנ\"ל, וע\"כ גם הוא שואל מה זאת פי' בחי' מ\"ה זה העצמי [ד]פנימי' הרצון וחכ' [כו'] מאין הוא בא ונמצא בבחי' <span data-k=\"pg\">314</span> ּ זאת שהוא מדרגה האחרונה ביותר והוא ביטול חיצוני' [ד]קעומ\"ש [ד]בחי' יר\"ת שנק' זא\"ת כידוע בענין בזא\"ת יבא אהרן<sup data-n=\"6065\">576</sup> כו' שהוא רק ביטול היש בהכנעה ושפלות עצמו שזהו ענין המצה שנק' לחם עוני<sup data-n=\"6066\">577</sup> כו' ד\"י אכלו כו' נקודה תח\"י<sup data-n=\"6067\">578</sup> כו' וכמ\"ש מי זאת עולה מן המדבר<sup data-n=\"6068\">579</sup> כו', וע\"כ מתפלא הת\"ם בתמידות<sup data-n=\"6069\">580</sup> שא\"א שיבא ביטול זה דמל' בחיצוני' כ\"א שיהי' תחלה [ה]ביטול רצון שבמדות למעלה מן הדעת ע\"י שהוא למטה מן הדעת דוקא ששרשו למעלה מן הדעת כו' (והוא בחי' קו האמצעי דת\"ת שעולה עד הכת\"ר<sup data-n=\"6070\">581</sup> ), וע\"כ שואל מאין יש חיבור זה דמ\"ה [ב]זא\"ת [כו'], ואמרת אליו בחוזק יד<sup data-n=\"6071\">582</sup> כו' שזהו בחי' הדילוג הנ\"ל שפסח ה' על הפתח דוקא שהוא היראה דבחי' מל' שנק' פת\"ח<sup data-n=\"6072\">583</sup> כידוע לפי שנתב\"ס דוקא, וכידוע בענין מה ה' אלקיך שואל מעמך<sup data-n=\"6073\">584</sup> כ\"א ליראה כו' דיר\"ת שרשה ביר\"ע<sup data-n=\"6074\">585</sup> דפנימי' הביטול דמ\"ה, ומצד בחי' הדילוג מעצמות אור אבא במל' דוקא ע\"כ נתחבר מה [זה] בזא\"ת דוקא כמ\"ש מאת ה' היתה זא\"ת<sup data-n=\"6075\">586</sup> מאת הוי' דאור אבא כו' נפלאת בעינינו בבחי' פלא העליון כו', וז\"ש בחוזק יד דהיינו בחי' הגבו' שבחסד דאבא שזהו מ\"ש קול דודי כו' מדל\"ג על ההרי\"ם מקפץ כו' ולהיכן הוא מדלג<sup data-n=\"6076\">587</sup> זהו שכ' ופסח ה' על הפת\"ח דוקא כמ\"ש במ\"א וד\"ל (ומ\"ש בחוזק יד הוציאנו ה' ממצרים היינו בחי' הלידה שהי' פרעה עומד באחורי עורף שהוא מיצר מ\"י דגרון, ובחוז\"ק י\"ד יד החזקה וזרוע הנטוי' בחי' ב' זרועות דא\"א הוציאנו כו' כמ\"ש בכוונות דעבדים היינו לפרעה<sup data-n=\"6077\">588</sup> כו'). וגם זהו תשובה על שאלתו מ\"ה זאת כפשוטו שאינו יודע מה זאת העבודה דמצה בבחי' הקטנות כ\"כ כו'.\n<b>ושאינו</b> יודע לשאול<sup data-n=\"6078\">589</sup> את פתח לו שנאמר והגדת לבנך כו', הנה זאת המדריגה הוא בסוף עולם העשי' שהוא תכלית הקטנות ביותר שאי[ן] שם אפי' ביטול חיצוני דקבלת עומ\"ש מצד עוצם ההסתר אלקו' עד שאינו יודע לשאול בהעלא' מ\"נ שהוא העדר [ה]התעוררות תשובה או יראה מצד בחי' קטנות הדעת והמוחין מאד כו', וכמו אין קורא בשמך<sup data-n=\"6079\">590</sup> כו' כידוע שכל שאלה היא בחי' העלא' בבקשה וקריאה כמו יעננו ביום קראנו<sup data-n=\"6080\">591</sup> כו'. אך הנה גם שם יוכל להגיע המשכת אור אבא לעורר",[["6065","576","<b>בזא\"ת יבא אהרן</b>: אחרי טז, ג. ראה זהר אחרי נו, א. מאמרי אדה\"א ויקרא ח\"א ע' סב. בראשית ע' כט ובהנסמן בהנ\"ל."],["6066","577","<b>המצה שנק' לחם עוני</b>: נסמן לעיל צה, ג."],["6067","578","<b>ד\"י אכלו כו' נקודה תח\"י</b>: נסמן לעיל קא, ב."],["6068","579","<b>מן המדבר</b>: ביד: ליתא."],["6069","580","<b>בתמידות</b>: ביד: במדות."],["6070","581","<b>קו האמצעי. . הכת\"ר</b>: נסמן לעיל פ' שמות כא, ב."],["6071","582","<b>ואמרת אליו בחוזק יד</b>: המשך הכתוב מה זאת — בא יג, יד."],["6072","583","<b>מל' שנק' פת\"ח</b>: ראה לעיל צא, א ובהנסמן לשם. צב, ג (ספ\"ו)."],["6073","584","<b>מ\"ה ה' אלקיך שואל מעמך</b>: עקב י, יב."],["6074","585","<b>דיר\"ת שרשה ביר\"ע</b>: ראה ביאוה\"ז אמור פא, ב. מאמרי אדה\"א דברים ח\"ב ע' תרנט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670200\" data-slug=\"torat-chaim\" data-id=\"2300670200\">תו\"ח בראשית כא, ג</a> ובהערה 22."],["6075","586","<b>מאת ה' היתה זא\"ת</b>: תהלים קיח, כג."],["6076","587","<b>קול דודי. . הוא מדלג</b>: שה\"ש ב, ח. ראה לעיל צ, ג."],["6077","588","<b>בכוונות דעבדים היינו לפרעה</b>: ראה פע\"ח (שחה\"מ) שכ\"א, פ\"ז במקומו."],["6078","589","<b>ושאינו יודע לשאול</b>: הגש\"פ. מכילתא בא יג, יד."],["6079","590","<b>אין קורא בשמך</b>: ישעי' סד, ו [ושם: ואין — ראה לקמן פ' תרומה שיג, א. תצוה שלז, ד. ש\"א לב, ב. מאמרי אדה\"א דברים ח\"ד ע' א'קצט. וש\"נ]."],["6080","591","<b>יעננו ביום קראנו</b>: תהלים כ, י."]]],[2300540822,"ולפתוח הלב ומוח שיהי' בו דעת לשאול ולדרוש את ה' והוא מ\"ש את פת\"ח לו לעשות בו פתח בית קיבול לזה והוא ע\"י האור<sup data-n=\"6081\">592</sup> פנימי' אור אבא שהולך ונמשך גם עד בחי' המדריגות היותר נמוכות והוא מצד עצם כח התולדה דיסוד אבא שנמשך לכל הענפים המסתעפים ונולדים מכחו הראשון והוא כענין מה שכאו\"א יכול לומר כי אתה אבינו כנ\"ל וד\"ל. וז\"ש והגד\"ת לבנ\"ך דוקא ביום ההוא שהי' בו הדילוג כנ\"ל בעבור ז\"ה דפנימי' אור אבא עשה ה' לי דוקא בצאתי ממצרים שזהו ענין ההבדלה הנ\"ל ועי\"ז יוכל גם הבן לשאול ולהעלות מ\"נ בעבודה הזאת במצה, וז\"ש והגד\"ת שתמשיך לו לפתוח פיו שלא יהי' כאלם כו' ולמעלה הוא בבחי' הקטנות דמל' דע\"ז א' נאלמת\"י דומי'<sup data-n=\"6082\">593</sup> ע\"כ א\"י לשאול בהעלאת מ\"נ ואמנם כתיב אד[נ\"י] שפתי תפתח<sup data-n=\"6083\">594</sup> כו' כענין א\"ת פת\"ח לו כו' וד\"ל.\n<b>והנה</b> להבין בתוס' ביאור ענין ההבדלה הנ\"ל בין פנימי' לחיצוני' שזהו עיקר ענין יצ\"מ <span data-k=\"pg\">קנז</span> ּ בכלל כמ\"ש או הנסה אלקים [לבוא] לקחת לו גוי מקרב גוי [כו'] וכנ\"ל במדת ארך אפיים שביקש משה שלא יאריך אף לרשעים כו', הנה י\"ל במ\"ש ב[פ]ע\"ח<sup data-n=\"6084\">595</sup> ובסידור להאריז\"ל על מאמר ההגדה דעבדים היינו לפרעה כנ\"ל<sup data-n=\"6085\">603</sup> דאנו בני ז\"א היינו במצרים בע[י]בור מיצר מ\"י דבינה כו' ופרעה שיונק מאחורי עורף הי' מונע ומעכב לצאת כו' וז\"ש עבדי\"ם היינו לפרעה כו' ע\"ש. והנה יש להקדים תחלה ענין פנימי' וחיצוני', דפנים ועורף [ה]נ\"ל שזהו ברצון שנק' כתר<sup data-n=\"6086\">596</sup> בחי' קוצו של יו\"ד דשם הוי' כידוע, כי הנה ידוע שיש ברצון פנימי' וחיצוני', הפנימי' נק' חפץ<sup data-n=\"6087\">597</sup> שחפץ ורוצה בפנימי' הנפש כמו יקרא חפצי בה<sup data-n=\"6088\">598</sup> כו' וכמו והנערה אשר חפץ בה המלך<sup data-n=\"6089\">599</sup> כו' והיינו ל' רצון ולשון מרוצה כמו רץ לבך שהנפש תרוץ בעצמ[ה] כו'. ויש בזה חילוקי מדרגו' יש רצון הנולד מן השכל שמחייבו, ויש רצון שהוא מצד עצם התענוג שבו, עד שיש רצון רק בניצוח ובהסכם המח' ומעשה למעלה מן הטעם ותענוג ועכ\"ז יכול להיות בו פנימי' הנפש כמו לעשות חסד וטוב שאין בלבו ודעתו כלל רק מצד הניצוח וההסכם ונק' נצח שבחסד דא\"א כנ\"ל. ואמנם הרצון הב' הוא הבא רק בבחי' חיצוני' בדרך אגב לבד או לצאת י\"ח שאינו בא מפנימי' נפשו כלל רק בבחי' אחוריים וחיצוני' דחיצוני', כמו הרצון בדבר מה שאין לו בה טובת הנאה כלל וכלל וכמו מותרות השפע שילך לאיבוד לגמרי רק מצד שיש בזה פיזור נדבנות הוצאה יתירה שאין ב[ו] צורך",[["6081","592","<b>האור</b>: ביד: הארת."],["6082","593","<b>נאלמת\"י דומי'</b>: תהלים לט, ג."],["6083","594","<b>אד[נ\"י] שפתי תפתח</b>: תהלים נא, יז."],["6084","595","<b>ב[פ]ע\"ח</b>: (שער חה\"מ) שכ\"א, פ\"ז (במקומו)."],["6085","603","<b>כנ\"ל</b>: ביב: הכל."],["6086","596","<b>ברצון שנק' כתר</b>: נסמן לעיל פ' וארא עט, א."],["6087","597","<b>ברצון. . הפנימי' נק' חפץ</b>: ראה שו\"ת הצ\"צ אבה\"ע ח\"ב סרס\"ג (ח, ג). מאמרי אדה\"ז תקע\"א ע' קעט ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'רצ. וש\"נ. נ\"ך ע' תפ. וש\"נ."],["6088","598","<b>יקרא חפצי בה</b>: ישעי' סב, ד."],["6089","599","<b>והנערה אשר חפץ בה המלך</b>: ראה אסתר ב, יג-יד. מאמרי אדה\"א דברים ח\"א ע' קו. שמות ח\"ב ע' תקעט ובהנסמן בהנ\"ל. שע\"ת סא, א ובהערה 5. לקמן פ' תצוה שעו, ג. ויקהל תלה, ד. פקודי תנו, ג. וראה גם לעיל פ' וארא ע, ד [ושם בר\"מ]."]]],[2300540831,"כלל ולא חל בו הרצון כלל, ויש רצון הבא בדרך אגב וטפל דטפל בענין הנצרך לו כמו בהוצאות ביתו הנצרך לו שיוציא הוצאה יתירה על אכילה ולבוש עו\"ש<sup data-n=\"6090\">600</sup> ובהמות מן הנשאר מסעודת ב\"ב, הנה על זה חל ג\"כ הרצון כמו ברצון הפנימי שהרי רצונו לזון לעו\"ש ולבהמות הטפל[י'] ומשמשים לצרכי חיות ב\"ב רק שאינו כמו רצון הפנימי לזון ב\"ב, וכ[מו כן] מלך שעשה משתה לשריו ועבדיו החשובים שזהו פנימי' רצונו יקראו גם לפחותים הרבה<sup data-n=\"6091\">601</sup> שיאכלו גם הם ויהנו ומקבל המלך שמחה מאשר הכל שמחי' בשמחתו גם קטני הערך, הגם שאין זה ערך לתענוג שמחתו מקרוביו<sup data-n=\"6092\">602</sup> ואוהביו רואי פניו עכ\"ז חל מזה הרצון והתענוג גם על פיזור הוצאות משתה לכל פחותי הערך לעשות כרצון איש ואיש דוקא, משום שנכלל הכל כאחד חיצוני' עם פנימי', ואין זה נק' אחוריים וחיצוני' ממש גם שאין כל פנימי' התענוג בזה שאוכלים כנ\"ל ושמחים מ\"מ ג\"ז נגרר אחר פנימי' התענוג ממש כמו העורף שנמשך ונגרר אחר הפנימי' והיו לאחדים ממש, שהרי גם זרים ושונאים שאוכלים ושמחים בשמחתו יקבל תענוג ושמחה כו'. וגם השיריים הנופלים מן הסעודה ומשתה לאיבוד או לכלבים וכה\"ג שלא הי' בזה רצון כלל וכלל ג\"ז נכלל ברצון בדרך אגב דאגב מפני שא\"א לסעודה גדולה בלא שיריים היוצאים לאיבוד ולכלבים וכה\"ג, אך מה שהעו\"ש שאחר הרחיים אוכלים השיריים נכלל יותר ברצון ואינו חיצוני' כ\"כ כו'. וכמו\"כ אנו רואים בכל רצון פנימי כמו בעס[ק] מו\"מ שיחפוץ להרויח שבזה כל פנימי' חיותו שודאי זהו פנימי' חפצו ורצונו אך א\"א להרויח זה כ\"א בהשתלשלו' מטרדא<sup data-n=\"6093\">604</sup> ויגיעה רבה בגופו ובפיזור <span data-k=\"pg\">316</span> ּ ממונו הנה גם ע\"ז חל הרצון לפי שנגרר אחר רצון הפנימי שהוא הריוח מאחר ש[מ]בלעדי זה לא יגיע לפנימי' רצונו, וכמו בשמחת המשתה שאין לה שלימות הרצון והתענוג מבלעדי שמחת רבים זרים ופחותים דוקא. וכן ענין מותרות שפע נדיבותו שאינו בא מצד החסד והטוב רק שהוא פזרן גדול להוציא כסף וזהב לרוב בלי שיעור ומדה כלל וכלל הרי יש בזה ב' אופנים א' שחל בו הרצון והתענוג להיות הכל מקבלים ממנו שלא כפי המדה וכן לעשות לו מרכבות וסוסי' ועבדים שאין מהצורך כלל שיתגדל שמו וכה\"ג, והכל<sup data-n=\"6094\">605</sup> פיזור מותרות הנופל לאיבוד לגמרי רק שאינו חושש כלל מצד העדר תפיסת מקום שאין<sup data-n=\"6095\">606</sup> כסף<sup data-n=\"6096\">607</sup> נחשב למאומה כמו בשלמה המלך<sup data-n=\"6097\">608</sup> מרוב העושר והגדולה כו' וכמו ברבי שא' אהוריירי' דבי רבי<sup data-n=\"6098\">609</sup> עתיר כו', וכל שיגדל המלך יותר יותר יוצא ממנו",[["6090","600","<b>עו\"ש</b>: יט: עבדים ושפחות."],["6091","601","<b>לפחותים הרבה</b>: ב: לפחותי הערך."],["6092","602","<b>שמחתו מקרוביו</b>: ביד: שלו משמחת מקורביו."],["6093","604","<b>בהשתלשלו' מטרדא</b>: ביב: בהשתדלות (ו)טרחא."],["6094","605","<b>והכל</b>: ביב: והב'."],["6095","606","<b>שאין כסף נחשב למאומה</b>: מל\"א י, כא. דהי\"ב ט, כ."],["6096","607","<b>כסף</b>: ב: ניתוסף: וזהב."],["6097","608","<b>המלך</b>: ביד: ליתא."],["6098","609","<b>אהוריירי' דבי רבי</b>: בבא מציעא פה, א. שבת קיג, ב."]]],[2300540840,"רוב המותרות כידוע. והנה הגם שבבחי' מותרות ונובלות השפע אין הרצון בו אף בחיצוני' דרך אגב כו' עכ\"ז הרי שייך לענין הגדולה היתירה שבזה ניכר עוצם רוממות הערך של גדולתו עכ\"פ כו', אבל יש שפע הנמשך שלא ברצונו כלל רק מצד ההכרח לצאת י\"ח או מפני שרוצה לפטור ממנו כמו השופע לשונאו שנותן לו בע\"כ רק כדי שלא יראה פניו וזהו כמאן דשדי בתר כתפוי או כמו אם רעב שונאך האכילהו לחם כו' וד\"ל.\n<b>והדוגמא</b> [מ]כל זה בהפרש שבין פנימי' לחיצוני' שברצון יובן למעלה בבחי' רצון העליון שא' בראשית ברא בקדמין<sup data-n=\"6099\">610</sup> פי' ברצונו<sup data-n=\"6100\">611</sup> ובחי' הרצון הזה הוא המקור הראשון לכל מע\"ב שממנו נמשך לחכמה ומחכ' למדות [ו]מדו\"מ כידוע, [ו]כמ\"ש כי הוא א'<sup data-n=\"6101\">612</sup> בלשון<sup data-n=\"6102\">613</sup> ויהי וכן או' שאמר והי' העולם<sup data-n=\"6103\">614</sup> והי' בלשון זה כלול מפנימי' וחיצוני', הפנימי' הן הנשמות של הצדיקים ותו\"מ ש[י]קיימו בסו\"מ עבמ\"ת<sup data-n=\"6104\">615</sup> בבחי' כוונה פנימי' לרצון כמ\"ש בראשית בשביל התורה<sup data-n=\"6105\">616</sup> ומצות<sup data-n=\"6106\">617</sup> שנק' ראשית ובשביל ישראל<sup data-n=\"6107\">618</sup> שנק' ראשית שהוא קיום התו\"מ שע\"י ישראל כמ\"ש אם לא בריתי<sup data-n=\"6108\">619</sup> יומם ולילה חוקות שמים וארץ<sup data-n=\"6109\">620</sup> כו' וארז\"ל תנאי הי' להקב\"ה במע\"ב<sup data-n=\"6110\">621</sup> כו' אם יקיימו כו' והוא במ\"ת שדיבר עמהם פב\"פ<sup data-n=\"6111\">622</sup> יו\"ד הדברות שזהו פנימי' המכוון שהי' בי\"מ<sup data-n=\"6112\">623</sup> כידוע. וזהו שבאור פניך נתת לנו<sup data-n=\"6113\">624</sup> כו' וכן יאר ה' פניו אליך שהוא בחי' הפנימי'<sup data-n=\"6114\">625</sup> ומצחא שבו רעדכ\"ר<sup data-n=\"6115\">626</sup> שהוא פנימי' רצה\"ע, והיינו ע\"י שהמשכת רצה\"ע בתו\"מ הוא בחי' פנימי' הרצה\"ע עד\"מ באדם רצון שנק' חפץ שכל פנימי' הנפש מלובש ונמשך בזה הרצון כנ\"ל גם שרצון זה נולד מן השכל שמחייבו כנ\"ל, כך רצה\"ע שבתו\"מ שחכ' שבתורה מחייבו הרי התורה היא עצם חכמתו ית' וכל עיקר חכ' דתורה הוא הטעם הכמוס לרצה\"ע שבמצות והתחכמות זאת אינו רק איך שיבא גילוי אוא\"ס [ב]מהו\"ע בעולמות בסו\"מ<sup data-n=\"6116\">627</sup> כו' דהיינו באיזה אופן שיהי' גילוי פנימי' רצונו כו', וע\"כ גזרה חכמתו ית' שבאופנים אלה ברמ\"ח מ\"ע יהי' התעוררות גילוי עצמות אוא\"ס בעולמות בבחי' יחו\"ע שנעשי' ע\"י המצות כשהן נעשים באופן זה דוקא אז הן נק' פנימי' רצונו ואו'<sup data-n=\"6117\">628</sup> כו' וכמ\"ש על התורה ואהי' אצלו אמון<sup data-n=\"6118\">629</sup> כו', והוא להיות <span data-k=\"pg\">קנח</span> ּ המשכת<sup data-n=\"6119\">630</sup> אורות בכלים מכלים שונים ע\"י המצות כך וכך, כמו במצות תפילין יהי' ד' מקיפים לד' מוחי' חו\"ב וחו\"ג בד' בתים וד' פרשיות<sup data-n=\"6120\">631</sup> באופן מעשיהם כך וכך דוקא, וכך במצות ציצית יהי'",[["6099","610","<b>בראשית ברא בקדמין</b>: בראשית א, א ובת\"א."],["6100","611","<b>בקדמין פי' ברצונו</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670056\" data-slug=\"torat-chaim\" data-id=\"2300670056\">תו\"ח בראשית ז, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670385\" data-slug=\"torat-chaim\" data-id=\"2300670385\">שעה\"י קטו, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670134\" data-slug=\"torat-chaim\" data-id=\"2300670134\">קלט, ב</a>. מאמרי אדה\"א דברים ח\"א ע' עדר."],["6101","612","<b>כי הוא א'. . ויהי</b>: תהלים לג, ט. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תריט."],["6102","613","<b>בלשון</b>: ביד: ברצון."],["6103","614","<b>שאמר והי' העולם</b>: ברכת ברוך שאמר. ראה גם לקמן קנא, ב. ריח, א. רנב, ב. מאמרי אדה\"א בראשית ע' טו. במדבר שם. שעה\"י קיח, א. שע\"ת כו, א."],["6104","615","<b>בסו\"מ </b>[יב: דסוף מעשה]<b> עבמ\"ת</b>: פיוט לכה דודי."],["6105","616","<b>בראשית בשביל התורה</b>: נסמן לעיל פ' וארא פא, ג."],["6106","617","<b>ומצות</b>: ביד: ליתא."],["6107","618","<b>בראשית. . ובשביל ישראל</b>: בראשית א, א וברש\"י שם. הנסמן בלקו\"ש מקץ (כרך ג) ע' 820."],["6108","619","<b>אם לא בריתי</b>: ירמי' לג, כה."],["6109","620","<b>חוקות שמים וארץ</b>: ביד: ליתא."],["6110","621","<b>תנאי הי' להקב\"ה במע\"ב </b>[יד: בוימ\"ב]: ראה שבת פח, א."],["6111","622","<b>שדיבר עמהם פב\"פ</b>: ואתחנן ה, ד."],["6112","623","<b>יו\"ד הדברות. . בי\"מ </b>[יד: ביו\"ד מאמרות]: נסמן לעיל פא, ג."],["6113","624","<b>שבאור פניך נתת לנו</b>: סיום תפלת העמידה."],["6114","625","<b>הפנימי'</b>: יד: הפנים."],["6115","626","<b>ומצחא שבו רעדכ\"ר</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, ב."],["6116","627","<b>בסו\"מ</b>: יב: בסובב וממלא."],["6117","628","<b>ואו'</b>: יד: וא\"ל. ביט: ואם לאו."],["6118","629","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["6119","630","<b>המשכת</b>: ידיט: ניתוסף: אא\"ס."],["6120","631","<b>לד' מוחי'. . בד' בתים וד' פרשיות</b>: ראה זהר (רע\"מ) בא מג, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'רמא."]]],[2300540849,"המשכת המקיף הכללי [ו]ל\"ב נ\"ח<sup data-n=\"6121\">632</sup> יאיר מן המקיף דטלית כשיהי' פרטי הלכותיו כך וכך דוקא, וכך הוא במצות שבת ויו\"ט ומצות סוכה ואתרוג וכה\"ג כמ\"ש בפע\"ח בפרטי הכוונ[ות] שלהם באורות עליונים במקיפים ופנימי' [כו'], וכן במצות צדקה יהי' גילוי אוא\"ס שבחסד עליון דאצי' להחיות רוח שפלים<sup data-n=\"6122\">633</sup> וכל אופן יחו\"ע שנעשה עי\"ז הכל ע\"י מצות הצדקה למטה כמו<sup data-n=\"6123\">634</sup> פרטי דיני הצדקה והכל ע\"י ישראל דוקא, והכל גזרה ח\"ע דאורייתא<sup data-n=\"6124\">635</sup> שבאופן זה דוקא יהי' גילוי אוא\"ס ולא ע\"י אופן אחר זולתו כלל, וכך גזרה חכ' דתורה על ענין אופנים פרטי[י'] בשס\"ה ל\"ת שהן דברים פרטי[י'] שהן המונעים ומסתירים מאד גילוי אור האלקי כמו בלבוש שעטנז וכלאים וכל ל\"ת דחלב ודם וכה\"ג בכל מאכלים וביאות אסורות ול\"ת דמלאכה וגזל ועריות<sup data-n=\"6125\">636</sup> וש\"ד וכל פרטיהם שנק' בכלל תועבת ה' שתעוב ושנאוי בעיני ה' שלא יגורך רע וטהור עינים מראות ברע, ע\"כ צריך האדם לפרוש מכל רע שהחיצוני' שור[ה] עליהם ונק' איסור שאסור וקשור בידי החיצוני'<sup data-n=\"6126\">637</sup> ואין להם עלי' למעלה להיות כלי לגילוי אור האלקי שלא יומשך להם כמ\"ש וכבודי לאחר לא אתן כו' כידוע וד\"ל.\n<b>ונמצא</b> מובן עכ\"פ שעיקר ענין ח\"ע דתורה היא להמשיך גילוי אוא\"ס ברמ\"ח מ\"ע ולהסיר כל מונע שהן שס\"ה ל\"ת והוא להבדיל בין טוב לרע בכדי שיהי' לו דירה בתחתונים ע\"י בירור עה\"ד טו\"ר ע\"י מ\"ע ול\"ת וזהו בדרך כלל, ובד\"פ יש הארה פרטי' בכל מצוה ומצוה מבחי' פנימי' רצה\"ע דוקא כידוע וד\"ל<sup data-n=\"6127\">638</sup> שנק' מצות הוי'<sup data-n=\"6128\">639</sup> וארחות הוי'<sup data-n=\"6129\">640</sup> ממש, וע\"כ כאשר<sup data-n=\"6130\">641</sup> לכנס\"י בקיום התו\"מ יאר ה' פניו אליך שזהו פנימי' המכוון בכל ההשתל' [כנ\"ל ב]פי' בראשית בשביל התורה וישראל כו', וכל הרצון וחכמה שנמשך במע\"ב להתהוות העולמות ומלאכים הוא בא בדרך אגב כטפל לגבי עיקר כו'. אך מבואר למעלה ב' חילוקים<sup data-n=\"6131\">642</sup> שברצון הב' הבא דרך חיצוני' שיוכל להיות הרצון חל ממש על החיצוני' בשביל הפנימי' ונכלל הכל כא' מפני שא\"א לזה בלא זה כלל כמו עד\"מ המשתה סעודה שרצונו על הרחוקים וקטנים כמו על הקרובים וגדולים וכן בהוצאות ביתו על העו\"ש ושאר דברים השייכים לצרכי ב\"ב [וד\"ל] (וכן משל העסק מו\"מ ביגיעה ופיזור כו' שנגרר החיצוני' אחר הפנימי' והיו לאחדים ממש וד\"ל).\n<b>והנה</b> מבואר למעלה בחילוקי הג'<sup data-n=\"6132\">643</sup> בחיצוני' הרצון שאין הרצון ותענוג חל עליו כלל כמו בבחי' מותרות השפע במשתה המלך הנק' שיריים הנופל לאיבוד כו' שאינו תופס",[["6121","632","<b>ציצית. . [ו]ל\"ב נ\"ח</b>: נסמן לעיל פ' וארא נו, ב."],["6122","633","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["6123","634","<b>כמו</b>: ביד: כפי."],["6124","635","<b>דאורייתא</b>: שם: דתו'."],["6125","636","<b>ועריות</b>: שם: ליתא."],["6126","637","<b>איסור שאסור וקשור בידי החיצוני'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא</a> פ\"ז. אגה\"ק סכ\"ו (קמג, ב)."],["6127","638","<b>וד\"ל</b>: ביד: ליתא."],["6128","639","<b>מצות הוי'</b>: ויקרא ד, ב. יג. כב. ועוד."],["6129","640","<b>וארחות הוי'</b>: נסמן לעיל פ' וארא סט, ד."],["6130","641","<b>כאשר</b>: ביד: נא'."],["6131","642","<b>ב' חילוקים</b>: שם: בח[י]לוקי'."],["6132","643","<b>בחילוקי הג'</b>: שם: בחלוקה הב'."]]],[2300540858,"מקום כלל וכלל, ויש מותרות שפע שחל עליו הרצון והתענוג בפיזור המותרות בנדיבות שפע יתירה מכפי המדה גם שהולך לאיבוד מצד העדר תפיסת מקום לרוב גדולתו ששייך זה לענין הרוממות והגדולה כו'. הנה כ\"ז יובן למעלה בענין החיצוני' ואחוריים דאחוריים שנמשך מבחי' מותרות שפע העליונה דקדושה בעולמות ומלאכי' דבי\"ע והן היכלות דק\"נ שבכל עולם [דבי\"ע דאת זלע\"ז עשה האלקי'<sup data-n=\"6133\">644</sup> כו' שמקבלים מבחי' השיריים והתמצית שנופל מחיצוני' הכלים דמל' דקדושה שבכל עולם], ובכלל הן מ\"ח צירופי' האחרונים דשם אלקי'<sup data-n=\"6134\">645</sup>, כמו <span data-k=\"pg\">318</span> ּ שמשם נמשך שפע לע\"ש דנוגה שמקבלים משמרי האופנים<sup data-n=\"6135\">646</sup> דעשי' שאין בחי' הרצון העליון חל ע\"ז גם בחיצוניות ואגב הנגרר אחר הפנימי' ממילא כנ\"ל, אלא זהו בא מבחי' השיריים והמותרות לבד הנופל לאיבוד שלא הי' ע\"ז שום כוונה ברצה\"ע רק לאחר שנמשך בחי' הפנימי' דרצה\"ע בנשמות בסט' דקדושה גם במלאכים [כו' ש]נק' עבדים המשמשים כנ\"ל אז יקבלו גם הזרים החיצונים מן השיריים הנופלים כו'. ויש בזה ב' אופנים א' שמ\"מ חל עליהם הרצון כמו בפיזור המותרות ושיריים גם שהולך לאיבוד שבא מצד הרוממות והגדולה היתירה [כנ\"ל] וכך הוא ענין ריבוי השפע יתירה דתענוגי עוה\"ז לע\"ש דק\"נ ביתר מכפי המדה והולך [לאיבוד] כו', וכענין שא' להודיע כמה ארך אפים לפניו בדורו של אנוש כנ\"ל מצד העדר תפיסת מקום שפע הגשמי' שנופל בבחי' פסולת מעונג ורצה\"ע הפנימי' שבתו\"מ וכה\"ג גם במותרות של שפע האלקי' במלאכים כמו שמרי האופנים וכה\"ג כנ\"ל, וע\"כ א' הן הן גבורותיו גוים מרקדים בהיכלו והוא שותק<sup data-n=\"6136\">647</sup> וכמו ששחק ר\"ע על כרך רומי שמלא טוב עוה\"ז וא' אם לעוברי רצונו כך דהיינו בחי' הפסולת והשיריים שנופל מעונג האלקי העליון שבג\"ע ועוה\"ב, לעושי רצונו בתו\"מ שהוא עוה\"ב וג\"ע בחי' פנימי' התענוג ורצה\"ע כנ\"ל עאכו\"כ וכידוע במשל השממית<sup data-n=\"6137\">648</sup> בהיכל מלך שאינה תופסת מקום כלל כו'. וכך יובן בכל ענין ריבוי השפע גשמי לעוברי רצונו כרשעים שהשגו חיל כו' (וגם אנו רואים בשפע החסד והרחמים שנמשך לבריות בכלל שפותח ה' ידיו ומשביע לכל חי רצון וזן ומפרנס לכל [לרעים] כמו לטובים ונותן לחם לכ\"ב כו' אע\"פ שאינן ראוי' כלל ניזונים בחסדו ביתר מכפי המדה שזהו הכל מצד הרוממות דקמי' כלא ממש חשיבא<sup data-n=\"6138\">649</sup>. ומה ש[ל]ישראל מדקדק עליהם במשפט התורה דוקא כמו אם בחוקתי תלכו<sup data-n=\"6139\">650</sup> כו' וא'<sup data-n=\"6140\">651</sup> כו' [וכן] והי' אם שמוע<sup data-n=\"6141\">652</sup> כו' וא\"ל ועצר ה'<sup data-n=\"6142\">653</sup> כו', זהו לפי שאליהם נמשך בחי' הפנימי' דרצה\"ע שע\"י קיום המצות שקבלת שכרם מבחי' פנימיות הענג העצמות<sup data-n=\"6143\">654</sup> שבעוה\"ב כידוע ע\"כ גם שפע הגשמי שלהם נידון",[["6133","644","<b>דאת זלע\"ז עשה האלקי'</b>: נסמן לעיל פ' שמות לד, ג."],["6134","645","<b>מ\"ח צירופי'. . דשם אלקי'</b>: נסמן לעיל ל, ב."],["6135","646","<b>לע\"ש. . שמקבלים משמרי האופנים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670093\" data-slug=\"torat-chaim\" data-id=\"2300670093\">תו\"ח נח נט, ד</a> ובהערה 57. לקמן פ' משפטים רפג, ג."],["6136","647","<b>הן הן גבורותיו. . שותק</b>: ראה יומא סט, ב. יל\"ש נחמי' רמז תתרעא."],["6137","648","<b>במשל השממית</b>: נסמן לעיל כא, ג."],["6138","649","<b>חשיבא</b>: אוצ\"ל: חשיבא)."],["6139","650","<b>אם בחוקתי תלכו</b>: בחוקותי כו, ג."],["6140","651","<b>וא'</b>: ביד: ואם לא."],["6141","652","<b>והי' אם שמוע</b>: עקב יא, יג."],["6142","653","<b>ועצר ה' </b>[ביד: ליתא]: עקב שם, יז."],["6143","654","<b>העצמות</b>: ב: העצמי. יט: העליון."]]],[2300540867,"במשפט התורה דוקא (כמ\"ש במ\"א בפ' בשלח<sup data-n=\"6144\">655</sup> ). ויש בזה ב' אופנים הנ\"ל במשל [א'] פזרנות המותרות או שיריים שהוא לפ\"ע הגדולה כו' והב' שפע שנותן לשונאו שלא ברצונו כלל כמאן דשדי [בתר] כו' זהו ענין גלות השכינה בע\"ש להשפיע להם שלא ברצון כלל רק כמו משלם לשונאיו אל פניו להאבידו בעוה\"ב וכמו אם רעב שונאך האכילהו לחם כנ\"ל וכידוע בענין אשר שלט האדם<sup data-n=\"6145\">656</sup> באדם לרע לו דוקא שהוא כדי לברר ולהוציא מפיו מה שבלע מניצוצות הקדושה כמו שהי' בגלות מצרים דכתיב וינצלו את מצרים<sup data-n=\"6146\">657</sup> כו' כידוע וד\"ל. והנה מובן עכ\"פ מכל הנ\"ל דדוקא כאשר נמשך אור השפע הפנימי' בבחי' פנימי' רצה\"ע בבחי' הפנימי'<sup data-n=\"6147\">658</sup> אז יש שפע גם בחיצוני' הרצון בבחי' אגב וטפל וממילא יש שפע גם בבחי' השיריים ומותרות הטפל<sup data-n=\"6148\">659</sup> כו' כנ\"ל, וכמו בזמן בהמ\"ק שהי' גילוי שכינה בהיכל קדה\"ק וקרבנות ע\"ג המזבח הי' נמשך מעשן המערכה דקרבן החלב ודם בחי' הפסולת לע\"ש<sup data-n=\"6149\">660</sup> ג\"כ וכשעיר לעזאזל<sup data-n=\"6150\">661</sup> כו' <span data-k=\"pg\">קנט</span> ּ (וכמ\"ש בזהר בענין קוצ[א דשערי] שבתפילין<sup data-n=\"6151\">662</sup> כו'), אבל כאשר לא בא האור והשפע עונג ורצה\"ע בגילוי בפנימי' כמו<sup data-n=\"6152\">663</sup> בהסתר והעלם כמו בחי' יחוד פנימי' דאוא\"ס<sup data-n=\"6153\">664</sup> בשבת ויו\"ט<sup data-n=\"6154\">665</sup> ויחוד זו\"נ בעמידה דש\"ע וכה\"ג, וכ\"ש בעבודת כה\"ג ביוה\"כ לפני ולפנים בהיכל קדה\"ק ובעלי' דנעילה ביו\"כ וכמו<sup data-n=\"6155\">666</sup> בעלי' העולמות דכל שבת<sup data-n=\"6156\">667</sup> אין שם צד אחיזה ויניקה לחיצוני' מחיצוני' ואחוריי' כלל [וכלל], לפי שהוא הכל בבחי' [ה]פנימי' והעצמות שאין שם בחי' חיצוני' ואחוריים כלל כמו שאין סעודת השבת מגשם כמ\"ש ולא פרש שבתכם וכמו לחם הפנים שכולו פנים<sup data-n=\"6157\">668</sup> וכלחם הפנים<sup data-n=\"6158\">669</sup> והמן יוכיח וכה\"ג<sup data-n=\"6159\">670</sup>, וכמו\"כ הוא בענין פנימי' התורה שהוא בפנימי' אבא שהוא פנימי' ע\"י כמ\"ש בע\"ח וד\"ל.\n<b>ואחר</b> כ\"ז יובן שרש ענין קליפה דפרעה אותיות עורף<sup data-n=\"6160\">671</sup> ששרשו באחוריים וחיצוני' דכת\"ר דוקא ע\"כ א' מי הוי'<sup data-n=\"6161\">672</sup> אשר אשמע בקולו כו', כי הנה ידוע בענין שם הוי' שהוא בחו\"ב ומדות ומל' דקוצו ש\"י הוא בכתר וי' בחכמה ה\"א בבינה<sup data-n=\"6162\">673</sup> וי\"ו מדות כו', וכאשר נמשך [אור] השפע בבחי' פנימי'",[["6144","655","<b>בפ' בשלח</b>: ראה לקמן קלה, א (ובהנסמן בריש המאמר שם). קעד, ג."],["6145","656","<b>אשר שלט האדם</b>: נסמן לעיל ל, ד."],["6146","657","<b>וינצלו את מצרים</b>: ראה גם לעיל פ' שמות לו, ג. וש\"נ."],["6147","658","<b>הפנימי'</b>: ביד: הפנים."],["6148","659","<b>השיריים ומותרות הטפל</b>: ביד: שיריים ופסולת הנופל."],["6149","660","<b>מעשן המערכה. . לע\"ש</b>: ראה זהר תרומה קל, א. קמא, א. פקודי רמב, ב. ע\"ח (שער קליפת נוגה) שמ\"ט, פ\"ג. טעמי המצות להאריז\"ל ס\"פ יתרו. תו\"א תשא קיב, ד. מאמרי אדה\"ז על נביאים ע' רמז. מאמרי אדה\"א נ\"ך ע' תקיג. וש\"נ. דרושי חתונה ח\"ב ע' תלא. לקמן פ' תצוה שמח, ג. תשא שפו, ב בשם הזהר."],["6150","661","<b>וכשעיר לעזאזל</b>: אחרי טז, ח ואילך. ראה ע\"ח שם פ\"ז. פ\"ח. לקו\"ת להאריז\"ל פ' אחרי. מאמרי אדה\"א דברים ח\"ב ע' תרח. וש\"נ. נ\"ך שם. וש\"נ."],["6151","662","<b>קוצ</b> [א דשערי]<b> שבתפילין</b>: ראה זהר פקודי רלז, ב. הערה במאמרי אדה\"א דברים ח\"ב ע' תקצו."],["6152","663","<b>כמו</b>: ביד: כ\"א."],["6153","664","<b>דאוא\"ס</b>: שם: דאו\"א."],["6154","665","<b>ויו\"ט</b>: שם: וק\"ש."],["6155","666","<b>ביו\"כ וכמו</b>: שם: וכמו\"כ."],["6156","667","<b>בעלי' העולמות דכל שבת</b>: ראה ע\"ח (שער פנימיות וחיצוניות) ש\"מ, דרוש ג. ח. טו. מאמרי אדה\"א ויקרא ח\"ב ע' תקסו וע' תשסה. נ\"ך ע' קמח ובהנסמן בהנ\"ל. לעיל צא, ב הערה 214. לקמן פ' ויקהל תטו, ד. תכו, ד."],["6157","668","<b>לחם הפנים שכולו פנים</b>: ראה מנחות צו, א. מאמרי אדה\"א דברים ח\"ג ע' א'קיח. וש\"נ. בראשית ע' קכד. וש\"נ."],["6158","669","<b>וכלחם הפנים </b>[ביד: פנג]: נסמן לעיל פ' שמות כג, ב."],["6159","670","<b>וכה\"ג</b>: ביד: ליתא."],["6160","671","<b>דפרעה אותיות עורף</b>: ראה לקו\"ת להאריז\"ל וישב מ, א. שמות א, ח. שער מאמרי רשב\"י לזהר תצוה קפד, ב בסופו. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקיג ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670048\" data-slug=\"torat-chaim\" data-id=\"2300670048\">תו\"ח לך צא, ב</a>. הנסמן לעיל יט, ב."],["6161","672","<b>מי הוי'</b>: שמות ה, ב."],["6162","673","<b>וי' בחכמה ה\"א בבינה</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."]]],[2300540876,"הרצון בחכמה כמו בחכמה שבתו\"מ כנ\"ל זהו ענין שם הוי' כידוע בענין מצות הוי' [ו]תו' הוי'<sup data-n=\"6163\">674</sup> כנ\"ל, אבל קודם שיומשך בחי' פנימי' הרצה\"ע בחכמה דתו\"מ ה\"ז בבחי' הסתר והעלם עדיין להיותו למעלה מן הטעם וחכמה כנ\"ל אז יש לנגד זה יניקה בעורף שהוא ג\"כ בעצם הרצון הנעלם בבחי' חיצוני' ואחוריים שבו ג\"כ למעלה מן החכ' וטעם (וכענין הניצוח שברצון למעלה מן הטעם שמחיצוני' שבו נמשך בצד העורף כמו שפע לשונאו שלא ברצון וטעם רק כמאן דשדי בתר כתפוי כו'). וזה הי' שרש פרעה [שר] של מצרים שנק' התנים הגדול<sup data-n=\"6164\">675</sup> כו' שה[י'] שרשו באחורי העורף שלנגד הכת\"ר שבמצחא כנ\"ל וע\"כ הי' בבחי' חוצפא והתנשאות מלכותא בלא תגא<sup data-n=\"6165\">676</sup> למעלה מן הטעם כמ\"ש לי יאורי ואני עשיתני<sup data-n=\"6166\">677</sup> כו', כי שרשו באחוריי' דכת\"ר [דקדושה] שהוא בבחי' הרוממות והתנשאות העצמי' האלקי' עד שלפ\"ע עצם הרוממות נמשך [גם] בחיצוני' בדרך מותרות ונובלות והוא למעלה מן [הטעם] (כמאן דשדי בתר כתפוי כנ\"ל מצד העדר תפיסת מקום כמשל השממית בהיכל מלך כנ\"ל וד\"ל. וזהו פרעה אותיות עורף עד\"מ באדם העורף שבו נמשך מותרי השפע מהפנימי' שבגלגלת הראש דרך ירידת<sup data-n=\"6167\">678</sup> חיצוני' ומותרות לבד ועיקר פנימי' חיות המוח נמשך לפנים וע\"כ נק' פנים ע\"ש בחי' הפנימי'<sup data-n=\"6168\">679</sup> וע\"ש שפונ\"ה<sup data-n=\"6169\">680</sup> בצד הפנים שבו דוקא והאחוריים נגררים ממילא אחר הפנים כו' (כמ\"ש במ\"א [בענין] ד\"ו פרצופים [ד]אדה\"ר<sup data-n=\"6170\">681</sup> ). וז\"ש פרעה מי הוי' שלא ידע משם הוי'<sup data-n=\"6171\">*682</sup> זה כי שרשו למעלה מבחי' הפנימי' דשם הוי' דחכמה הבא בגילוי בפנימי' כי יניקתו בעורף שבראש (ועוד מפני שהובדל[ה] הפנימי' מן החיצוני' כו' ע\"כ לא ידע והשיג בפנימי' דשם הוי' כמו שהוא בפנימי' הכתר [עליון כלל] ולזה הי' עיקר [ענין] האותות ומופתים שידעו מצרים כי אני הוי' כמשי\"ת). ובכ\"ז יובן כללות ענין המאמר שא' עבדים היינו לפרעה במצרים אנו בני ז\"א דאצי' מדות דאצי' ששרשן בפנימיות אבא כמו כי אתה אבינו כידוע היינו עבדים לפרעה שעומד באחורי עורף דכתר עליון שהוא בגלגלתא <span data-k=\"pg\">320</span> ּ דא\"א כו' שמשם הי' יניקת פרעה הגשמי למטה כו'. והנה יש להקדים תחלה בדרך הפשוט ע\"פ דרך הטבע מה שהי' סיבה לשעבוד",[["6163","674","<b>[ו]תו' הוי'</b>: בא יג, ט."],["6164","675","<b>התנים הגדול</b>: יחזקאל כט, ג."],["6165","676","<b>מלכותא בלא תגא</b>: ראה סנהדרין צט, ב. קה, א. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע ר."],["6166","677","<b>לי יאורי ואני עשיתיני</b>: יחזקאל שם."],["6167","678","<b>ירידת</b>: בידיט: ורידים — וכ\"ה בסידור כאן (רצד, ג)."],["6168","679","<b>פנים ע\"ש בחי' הפנימי'</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שפ־ קונטרסים ע' רצז־ הנחות תקע\"ז ע' סא ובהנסמן בהנ\"ל. שע\"ת קכח, א. ש\"א יב, ב. לקמן פ' בשלח קעד, ד. תצוה שלז, א."],["6169","680","<b>פנים. . וע\"ש שפונ\"ה</b>: ראה מאמרי אדה\"א קונטרסים שם־ הנחות תקע\"ז ע' קלא ובהנסמן בהנ\"ל."],["6170","681","<b>ד\"ו פרצופים [ד]אדה\"ר</b>: ברכות סא, א. עירובין יח, א וברש\"י שם. שער היחוד ע' קמב. ביאוה\"ז אחרי עה, ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשפה וע' תתעט. אוה\"ת נ\"ך ע' א'ג."],["6171","*682","<b>פרעה. . שלא ידע משם הוי'</b>: ראה גם לעיל פ' שמות כה, סע\"א ואילך."]]],[2300540885,"ישראל בעבודה קשה תחת פרעה כמו שסיפר וימת יוסף<sup data-n=\"6172\">682</sup> וכל הדור ההוא ויקם מלך חדש<sup data-n=\"6173\">683</sup> על מצרים אשר לא ידע את יוסף [כו'], דהענין הוא ע\"פ סיבת הטבע האנושי' דבעוד שהי' יוסף מושל על מצרים לא הי' פרעה גוזר גזירות קשות על ישראל אך מפני שמת יוסף וקם מלך חדש כו' גזר גזירות קשות על ישראל, ובאמת סיבה זאת היתה מאת ה' ע\"פ סוד ה' למעלה מעלה שעולה טעם מה כמו שהוא<sup data-n=\"6174\">684</sup> למטה בדרך הטבע, דהנה אם לא מת יוסף וכל הדור ההוא דוקא לא הי' מקום לשרש יניקת [ל]פרעה העליון למעלה לשעבד בישראל רק אחרי מות יוסף וכל הדור ההוא וקם מלך חדש שלא ידע [ל]יוסף בחי' צ\"ע ע\"כ נעשו בנ\"י עבדים לפרעה לקבל שפעם מבחי' חיצוני' ואחוריים דעורף דפרעה דוקא וד\"ל.\n<b>וביאור</b> ענין זה ידוע ד[ה]אבות הן המרכבה לבחי' המדות דחג\"ת דז\"א דאצי', אברהם אוהבי רחימא דמלכא<sup data-n=\"6175\">685</sup> הי' מרכבה לחסד<sup data-n=\"6176\">686</sup> דז\"א ויצחק במדת פחד ויראה פנימי' לגבו'<sup data-n=\"6177\">687</sup> דז\"א ויעקב אמר אלקי [אבי] אברהם<sup data-n=\"6178\">688</sup> ופחד יצחק היה לי שכלול מחו\"ג בחי' הרחמים<sup data-n=\"6179\">689</sup> בחי' ת\"ת דז\"א. וזהו שאנו אומרים<sup data-n=\"6180\">690</sup> אלקי אברהם ואלקי יצחק כו' שמקבלים מבחי' פנימי' חו\"ב דאצי' ששרשם בחג\"ת דאוא\"ס<sup data-n=\"6181\">691</sup> וע\"י שז\"ש הגדול הגבור כו' בה\"א<sup data-n=\"6182\">692</sup> הידיעה שנק' ימי קדם<sup data-n=\"6183\">693</sup> או הרי קדם<sup data-n=\"6184\">694</sup> כו' וכמ\"ש אשר נשבעת לאבותינו מימי קדם<sup data-n=\"6185\">695</sup> וכידוע. ושרש המדות דא\"א הרי הן מדות שברצון הפנימי שנק' חפץ הוא למעלה גם מח\"ס דא\"א שנק' טעם כמוס<sup data-n=\"6186\">696</sup> כידוע שאין טעם לרצה\"פ<sup data-n=\"6187\">697</sup> שנק' כת\"ר שבכת\"ר אפי' טעם כמוס [כו'], ולפי\"ז הרי הוא<sup data-n=\"6188\">698</sup> מאיר [על האבות] מבחי' פנימי' רצה\"ע שנק' פנימי' הכתר בכלל והוא בחי' פנים העליונים דא\"א כו' שמשם שרש י\"ג מדה\"ר שא' ויעבור הוי' על פניו כו' [כידוע], והוא ג\"כ ענין יאר ה' פניו אליך כו', וכמ\"ש באברהם התהלך לפני<sup data-n=\"6189\">699</sup> דוקא וגם יעקב א' אלקי אבי אברהם כו'. ונמצא שלא הי' באבות שום אחיזה ויניקה לבחי' חיצוני' ואחוריים דכתר [כלל] מאחר ששרשם הי'",[["6172","682","<b>וימת יוסף</b>: שמות א, ו [בדילוג]."],["6173","683","<b>ויקם מלך חדש</b>: שמות שם, ח."],["6174","684","<b>מה. . שהוא</b>: ביד: זה. . שהי'."],["6175","685","<b>אברהם. . רחימא דמלכא</b>: נסמן לעיל פ' וארא סב, א."],["6176","686","<b>אברהם. . לחסד</b>: נסמן לעיל פ' וארא נו, ג."],["6177","687","<b>ויצחק. . לגבו'</b>: נסמן לעיל פ' וארא סא, ד."],["6178","688","<b>אלקי [אבי] אברהם</b>: ויצא לא, מב [בדילוג — ראה לעיל פ' וארא פה, ד. לקמן פ' משפטים רפו, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תשסג. וש\"נ. שה\"א כה, א ובהערה 8]."],["6179","689","<b>ויעקב. . הרחמים</b>: נסמן לעיל פ' וארא סא, ד."],["6180","690","<b>שאנו אומרים</b>: בתפלת העמידה."],["6181","691","<b>דאוא\"ס</b>: ביד: דא\"א."],["6182","692","<b>הגדול הגבור כו' בה\"א</b>: תפלת העמידה. ראה גם לקמן פ' פקודי תנז, ג. סידור שער הלולב רסב, א."],["6183","693","<b>ימי קדם</b>: ראה גם לעיל צ, א. וש\"נ. בהערה הבאה."],["6184","694","<b>הרי קדם</b>: ראה גם לקמן פ' בשלח קצט, ד. רמח, ד. שה\"א קב, א ובהערה 2."],["6185","695","<b>אשר נשבעת לאבותינו מימי קדם</b>: מיכה ז, כ. ראה גם שה\"א צו, ב ובהערה 20."],["6186","696","<b>מח\"ס דא\"א שנק' טעם כמוס</b>: נסמן לעיל פ' וארא סח, ד."],["6187","697","<b>שאין טעם לרצה\"פ</b>: נסמן לעיל פט, ד."],["6188","698","<b>הוא</b>: ביד: הי'."],["6189","699","<b>התהלך לפני</b>: לך יז, א."]]],[2300540894,"רק בעצם פנימי' הכתר שהובדל [מ]בחי' החיצוני' לגמרי (שאין שם בחי' חיצוני' ואחוריים כלל אלא כולו מפנימי'<sup data-n=\"6190\">700</sup> כנ\"ל) ומה<sup data-n=\"6191\">701</sup> שא' אברהם יצא ממנו ישמעאל חסד דק\"נ היינו במדות דז\"א דוקא כידוע, ולכך א' שהטעימן לאבות מעין העוה\"ב<sup data-n=\"6192\">702</sup> שלמעלה מבחי' עה\"ד טו\"ר, ולכך יש מ\"ד זכות אבות לא תמו<sup data-n=\"6193\">703</sup> כו' וד\"ל) לפי שגם הג' קוין דחג\"ת דפנימי' הכת\"ר מיוחדים בעצמות פנימי' הכת\"ר, ע\"כ גם אחרי מות האבות האיר הוי' פניו מפנימי' רצה\"ע וחפץ ה' אל השבטים שהן ע' נפש דיעקב<sup data-n=\"6194\">705</sup> שנחלקו לד' דגלים<sup data-n=\"6195\">706</sup>, אעפ\"י שהן בעולם הבריאה בבחי' ו\"ק דנוק' ([ו]נק' י\"ב בקר שהי\"ם עומד עליהם<sup data-n=\"6196\">707</sup> ) ששרשם בי\"ב ג\"א<sup data-n=\"6197\">708</sup> דנוק' דז\"א דאצי' בעלמא דדכורא<sup data-n=\"6198\">704</sup> וכמ\"ש ששם עלו שבטים<sup data-n=\"6199\">709</sup> שבטי י\"ה פי' עלו שבטים דנוק' דמל' דאצי' בבריאה לו\"ק דאצי' ששם נק' שבטי י\"ה שהן פנימי' חו\"ב<sup data-n=\"6200\">*710</sup> ששרשם בפנימי' הכת\"ר דוקא כנ\"ל, [ו]עד\"מ השבט שנק' ענף שיניקתו מן האילן ושדי נופו בתר עיקרו<sup data-n=\"6201\">710</sup> אעפ\"י שאין קורין אבות אלא לשלשה<sup data-n=\"6202\">711</sup> שהן גוף השרש של האילן (אלא שיש בשבטים ב' אופנים א' שגדלים מלמטה למעלה <span data-k=\"pg\">קס</span> ּ כמ\"ש ששם עלו שבטים שבטי י\"ה כו'<sup data-n=\"6203\">712</sup> בבחי' או\"ח, והב' בשבטים [בו\"ק] דדכורא שיורדים ונמשכים מלמעלה למטה בבחי' או\"י כמ\"ש במ\"א ע\"פ למה תתענו ה' מדרכיך<sup data-n=\"6204\">713</sup> כו' שוב למען עבדיך שבטי נחלתיך כו' שהן ששה<sup data-n=\"6205\">714</sup> אלפים לצבא<sup data-n=\"6206\">715</sup> כו' היורדים למטה לברר לעה\"ד כו').\n<b>והנה</b> בחי' יוסף הוא פנימי' יסוד<sup data-n=\"6207\">716</sup> ז\"א<sup data-n=\"6208\">717</sup> ושרשו בפנימי' יסוד דפנימי' הכת\"ר כו', שבו כל השבטי' נאחזי' כמ\"ש למחי' שלחני אלקים<sup data-n=\"6209\">718</sup> כו' והוא המעלה כל העלאות מ\"נ [דשבטים] דנוק' כמ\"ש קמה אלומתי<sup data-n=\"6210\">719</sup> כו' כמ\"ש במ\"א<sup data-n=\"6211\">720</sup>). אך לאחר שמת יוסף וכל הדור ההוא שנסתלק אור פנימי' הכת\"ר שבפנימי' יסוד כו' אז נעשה כמו מחיצה המפסקת להארת אור פנימיות הכתר שיש בו הארת אור מל' דא\"ס שבקו\"ח כו', וזהו ויקם מ\"ח על מצרים אשר לא ידע את יוסף צ\"ע דבחי' פנימי' יסוד דא\"א",[["6190","700","<b>מפנימי'</b>: ביד: פנים."],["6191","701","<b>ומה</b>: אוצ\"ל: (ומה."],["6192","702","<b>שהטעימן לאבות מעין העוה\"ב</b>: בבא בתרא טז, סע\"ב ואילך."],["6193","703","<b>זכות אבות לא תמו</b>: ראה גם לעיל פ' וארא סב, ב."],["6194","705","<b>ע' נפש דיעקב</b>: ויגש מו, כז."],["6195","706","<b>לד' דגלים</b>: במדבר ב, ב ואילך."],["6196","707","<b>י\"ב בקר שהי\"ם עומד עליהם</b>: מלכים-א ז, כה. מד. דהי\"ב ד, טו."],["6197","708","<b>בי\"ב ג\"א</b>: ס\"י פ\"ה, מ\"א. ס' הבהיר סמ\"ב. ונמנו בפרדס (שער פרטי השמות) שכ\"א, פ\"ו-ח. שה\"א עג, א. הנסמן במ\"מ לשע\"ת צב, ג הערה 34."],["6198","704","<b>השבטים. . דנוק'. . דדכורא</b>: ראה זהר פקודי רכט, ב. רל, א. מאמרי אדה\"א ויקרא ח\"א ס\"ע רעח ואילך. וש\"נ. שע\"ת צב, ג ובהערה 28."],["6199","709","<b>ששם עלו שבטים</b>: תהלים קכב, ד. ראה גם לעיל פ' וארא עט, א."],["6200","*710","<b>י\"ה. . חו\"ב</b>: ראה גם לקמן פ' משפטים רפז, א. וש\"נ."],["6201","710","<b>ושדי נופו בתר עיקרו</b>: שבת ד, ב."],["6202","711","<b>שאין קורין אבות אלא לשלשה</b>: נסמן לעיל פ' וארא סו, א."],["6203","712","<b>שבטי י\"ה כו'</b>: ביד: כנ\"ל."],["6204","713","<b>למה תתענו ה' מדרכיך</b>: ישעי' סג, יז. ראה תו\"ח ויצא קעו, ד ואילך."],["6205","714","<b>ששה</b>: יד: כתב ששה ומחקו וכתב ממעל לשיטה י\"ב. — ראה פיה\"מ מב, סע\"א ואילך."],["6206","715","<b>ששה אלפים לצבא</b>: ראה סידור שער נט\"י קא, ב בשם הלק\"ת [נדפס גם במאמרי אדה\"ז תקס\"ב ח\"א ס\"ע קז]. מאמרי אדה\"א שמות ח\"א ע' רכח. וש\"נ. פיה\"מ מא, סע\"א ואילך. לעיל צג, א. לקמן פ' בשלח רמא, ד [ושם: ז']."],["6207","716","<b>יוסף. . פנימי' יסוד</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680354\" data-slug=\"torat-chaim\" data-id=\"2300680354\">תו\"ח וישב רי, ג</a>. מאמרי אדה\"א בראשית ס\"ע רצב ואילך. קונטרסים ע' רכה. וש\"נ."],["6208","717","<b>יוסף. . יסוד ז\"א</b>: ראה ע\"ח (שער הצלם) שכ\"ו, פ\"ג. לקמן פ' יתרו עדר, ב. וש\"נ."],["6209","718","<b>למחי' שלחני אלקים</b>: ויגש מה, ה."],["6210","719","<b>קמה אלומתי</b>: וישב לז, ז. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קטו ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370132\" data-slug=\"torah-or\" data-id=\"3901370132\">תו\"א וישב כח, ב</a>."],["6211","720","<b>במ\"א)</b>: יט: במ\"א. ואולי התחלת הסוגר צ\"ל בתיבת כמ\"ש."]]],[2300540903,"(שנק' טובך הגדול<sup data-n=\"6212\">721</sup> כו') אזי לא נמשך בחי' הארת פנים דא\"א בישראל כי נסתר ונעלם אורו (כמו ב[כל] גלות דכתיב ואנכי הסתר אסתיר פני ביום ההוא<sup data-n=\"6213\">722</sup> בבחי' סדכ\"ס<sup data-n=\"6214\">723</sup> כו' כמ\"ש במ\"א בענין אסת\"ר מן התורה<sup data-n=\"6215\">724</sup> כו') ואז מלובש ומוסתר בחי' הפנימי' לגמרי ולא בא השפע כ\"א ע\"י בחי' אחוריי' וחיצוני' רצה\"ע (שנבדל לגמרי מן הפנימי' כנ\"ל). והיא בחי' אחוריים דעורף דפרעה העליון יונק שם, וע\"כ היו ישראל בגלות למטה עם השכינה בשר של מצרים כמ\"ש אנכי ארד עמך מצרימה<sup data-n=\"6216\">725</sup> לקבל יניקה ושפע [מ]פרעה שלמטה בדרך שעבוד קשה עד שהיו עבדים לפרעה ממש וד\"ל.\n<b>ובאמת</b> עדיין י\"ל דאין כל הנ\"ל מחייב רק מה שילך השפע ע\"י בחי' אחוריים דעורף שרש פרעה וזה כבר הי' ע\"י יוסף שהי' מכלכל<sup data-n=\"6217\">726</sup> לכל בית יעקב מטוב ארץ מצרים בארץ גושן אבל מאיזה טעם הי' שעבוד הקשה דישראל לפרעה מלך החדש מפני שלא ידע ליוסף כנ\"ל. אך הענין הוא דמפני שלא ידע את יוסף נעשה ענין הגלות מצרים שהוא מ\"ש בפע\"ח ובכוונות<sup data-n=\"6218\">727</sup> שהיו בנ\"י דלעילא בבחי' עיבור דבינה שכן<sup data-n=\"6219\">728</sup> מיצ\"ר מ\"י ומצרים<sup data-n=\"6220\">729</sup> דחכמה ופרעה הי' מונע הלידה [כו']. וי\"ל תחלה שרש ענין בחי' עיבור בגשמי' בקטנות<sup data-n=\"6221\">730</sup> במעי אמו שהולד ראשו בין ברכיו [מקופל ואוכל מה שאמו אוכלת<sup data-n=\"6222\">731</sup> דרך הטבור כו'. פי' מקופל ראשו בין ברכיו] שזהו מוחין דחב\"ד נעלמ[י'] בחג\"ת ונה\"י שהן הירכים בבחי' הקטנות מאד<sup data-n=\"6223\">732</sup>, והיינו ענין [קטנות המדות כמו שהן מצומצמים ונעלמים מאד בשכל בבחי' עיבור והתכללות כולד במעי אמו, והוא] מה שאנו רואים שיש מציאות אהוי\"ר במוח בינה כאשר [י]תבונן האדם בדבר מה שהוא טוב לו שיחייב שכלו ודעתו שיאהוב אותו הדבר שהוא טוב<sup data-n=\"6224\">733</sup> בעיניו, או להיפוך בהתבוננו' בדבר מה שהוא [רק] רע לו ומזיק שיחייב שכלו שישנא אותו [או] יפחד ויברח ממנו, אזי עדיין [אוי\"ר זו] כלולים בהעלם גדול בהתבוננות זו ואינם ניכרים במציאות כלל עדיין אפי' בהרגש התפעלות השכל כלל, כי כאשר המוח מתפעל באוי\"ר נכרים עכ\"פ במציאות מדות אהוי\"ר רק שהן במוח עדיין אבל כשאינם עדיין בבחי' התפעלות מורגש[ת] במוח כלל רק מה ש[י]חייב שכלו ודעתו שראוי לאהוב דבר זה ועדיין אין לו התפעלות במורגש גם במוחו זה[ו] הנק' בחי' קטנות המדות שכלולים ונעלמים בשכל בתכלית, כי מה שהשכל נותן חיוב לאוי\"ר אין זה מהות מדות במציאות רק בחי' נה\"י דבינה (שנק' תבונה <span data-k=\"pg\">322</span> ּ שהוא פנימי' המח'). וכמו שידוע לכל",[["6212","721","<b>יסוד דא\"א. . טובך הגדול</b>: ראה גם מאמרי אדה\"ז על ענינים ע' תה. שעה\"י קכח, א ובהערה 2. ש\"א כז, ב."],["6213","722","<b>ואנכי הסתר. . ביום ההוא</b>: וילך לא, יח."],["6214","723","<b>סדכ\"ס</b>: לשון הזהר בהקדמה ב, א. ועוד."],["6215","724","<b>אסת\"ר מן התורה</b>: חולין קלט, ב. ראה תו\"א צ, ד. מאמרי אדה\"א נ\"ך ע' שעט ואילך. ע' תיג ואילך."],["6216","725","<b>אנכי ארד עמך מצרימה</b>: ויגש מו, ד. ראה גם לעיל פ' וארא פו, ב."],["6217","726","<b>יוסף שהי' מכלכל</b>: ויגש מז, יא. יב. כז."],["6218","727","<b>בפע\"ח ובכוונות</b>: ראה פע\"ח (שחה\"מ) שכ\"א, פ\"ז בפיסקא עבדים היינו. סידור האריז\"ל שם."],["6219","728","<b>דבינה שכן</b>: ביד: דקטנות בבינה שנק'."],["6220","729","<b>ומצרים</b>: שם: ומיצ\"ר ים."],["6221","730","<b>בקטנות</b>: שם: ליתא."],["6222","731","<b>ואוכל מה שאמו אוכלת</b>: נדה ל, ב."],["6223","732","<b>הקטנות מאד</b>: ראה גם לעיל פ' שמות לא, ג."],["6224","733","<b>שהוא טוב</b>: ביד: שהוטב."]]],[2300540910,"מתחיל בעבודה הנ\"ל<sup data-n=\"6225\">734</sup> בהתבוננות שגם שיוקלט היטב ההשגה אלקי' במוח בגדולת ה' איך שמחיה את הכל מאין ליש וכה\"ג לא יוליד מזה התפעלות אהוי\"ר בהרגש המוח ג\"כ, רק שראוי לאהוב את ה' [ו]לילך בדרכיו וליפחד ולירא מה' להיות סו\"מ בפו\"מ (שנק' בכ\"ן דארף מען כו') שכך יאתה ע\"פ התבוננות אלקי' שמחייב זה כו', וההשגה האלקי' מקפת לחיוב זה דאהוי\"ר מכל צד עד שנכללים ובטלים שם במציאו\"ת (משא\"כ אוי\"ר שהן בבחי' התפעלות ממש במוח בינה נק' דו\"ר שכליים שבאים בבחי' גילוי [ה]הרגשה ממש, אבל כשהשכל וטעם נעלם הוא בחיוב הזה דאהוי\"ר זהו ענין מה שראשו בין ברכיו שחב\"ד שבמדות נעלמים בנה\"י שאין נראה רק החיוב לאהוי\"ר לבד כו'). וזהו הנק' מ\"ם סתומה שסתום מכל צד כולד הסתום במעי אמו בלתי ניכר במציאות בפ\"ע כך המדות אוי\"ר סתומים ונעלמים וכלולים בבינה והשגה כנ\"ל ורק דרך בחי' העלם ומקיף נמשך למדות אלה שהן בבחי' הקטנות כולד שמקבל דרך הטבור [מ]מה שאמו אוכלת ולא דרך פיו כי פיו סתום וטבורו פתוח<sup data-n=\"6226\">735</sup> כו' כי המוחין שלו סתומים ונעלמים בתכלית כו' (ויובן זה גם עכשיו בזמן הגלות שנמשל לעיבור כידוע במאמר המשנה [אפילו<sup data-n=\"6227\">736</sup> בשעה] שאתה מתמלא עליהם עברה כאשה עובר\"ה כו' [ש]מדות דאהוי\"ר שבכנס\"י הן בבחי' הקטנות רק לחיוב [אוי\"ר] בלא טעם [ו]מוחי' מגולים ו[ה]השגה דבינה מקפת מרחוק, אמנם נמשך חיזוק וחיות מבחי' העלם ומקיף דבינה למדות אהוי\"ר אלה עד שהן חזקים וקיימים לענין מעשה בסו\"מ וע\"ט כאלו הן מקבלים חיות ואור מבחי' המוחי' בגילוי במורגש ויותר מזה וכמ\"ש מי יתנני כירחי קד\"ם שמלמדים לתינוק<sup data-n=\"6228\">737</sup> כל התורה בבחי' [ה]מקיף דנר\"נ כו', [וראי'] שלע\"ל בגאולה שנק' לידה [י]פתח [ה]סתום וירא[ו] בעין כולד הנולד ש[נ]פתחו עיניו כו') (וזהו אוכל מה שאמו אוכלת שהוא א\"ם הבנים דכנ\"י שכלולים ב\"ה כל נש\"י בבחי' עיבור בזמן הגלות כידוע (וגם מאכל דלחם דתו' אוכל דרך טבורו<sup data-n=\"6229\">738</sup> [לכריסו] לבד כמ\"ש במ\"א), וזהו מ\"ם סתומה דלמרב\"ה המשר\"ה<sup data-n=\"6230\">739</sup> כו' שהוא בחי' בינה אם הבנים כמ\"ש כי א\"ם לבינה תקרא<sup data-n=\"6231\">740</sup> בעוד שכלולים<sup data-n=\"6232\">741</sup> נש\"י כלולים בה בבחי' עיבור בבחי' תלת גו תלת<sup data-n=\"6233\">742</sup> כו'). והנה מ\"ם סתומה זו לבד ענין הסתומים<sup data-n=\"6234\">743</sup> שסתום מכל צד שלא יצא הולד, משא\"כ מ\"ם פתוח\"ה שמולדת המדות שנק' ולד והוא מאמר פתוח<sup data-n=\"6235\">744</sup> כמשי\"ת, הנה עיקר הסתימות דמ\"ם סתומה הוא על ענין הסתימות וההעלם דנקודת אור החכמה שנק' טפת אבא באימא, והוא ענין נקודה בהיכלא<sup data-n=\"6236\">745</sup> שההשגה דמקיף דבינה",[["6225","734","<b>בעבודה הנ\"ל</b>: שם: בעבודת ה'."],["6226","735","<b>פיו סתום וטבורו פתוח</b>: נדה שם."],["6227","736","<b>במאמר המשנה [אפילו</b>: נסמן לעיל פ' שמות לא, ג."],["6228","737","<b>מי יתנני. . שמלמדים לתינוק</b>: איוב כט, ב. ראה נדה שם. וראה גם לקמן פ' בשלח קפ, ג. וש\"נ."],["6229","738","<b>אוכל דרך טבורו</b>: ראה גם לעיל פ' וארא סו, ג. סז, א ובהערה 337."],["6230","739","<b>מ\"ם סתומה דלמרב\"ה המשר\"ה</b>: ישעי' ט, ו."],["6231","740","<b>כי א\"ם לבינה תקרא</b>: נסמן לעיל פ' וארא סט, ב."],["6232","741","<b>שכלולים</b>: ביד: שכללות."],["6233","742","<b>תלת גו תלת</b>: נסמן לעיל פ' שמות לח, ד."],["6234","743","<b>הסתומים</b>: ביד: הסתימות."],["6235","744","<b>מאמר פתוח</b>: נסמן לעיל פ' שמות יב, ב."],["6236","745","<b>נקודה בהיכלא</b>: ראה זהר בהקדמה ו, רע\"א. תצוה קפ, א. מאמרי אדה\"א בראשית ע' א־ ויקרא ח\"ב ע' תרכה. דברים ח\"ב ע' שסו ובהנסמן בהנ\"ל. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670127\" data-slug=\"torat-chaim\" data-id=\"2300670127\">תו\"ח לך פא, ג</a>. לקמן קלא, א."]]],[2300540917,"היא המקפת ומסתרת ומעלמת לנקודת אור החכ' בתוכה מכל צד (כמו הברקת נקודת המושכל שנעלם ונסתר בהעלם תמצית ההסבר וההשגה שנק' עומק המושג טרם שבא להשגה והבנה בגילוי שנק' פנימי' בינה והוא כח המוליד את השכל שנסתר עצם נקודתו כשבא לכלל עומק ההשגה דוקא, משא\"כ בגילוי ההשגה יכולים לעמוד על נקוד' דחכמה). וזהו כמשל כח ומקור כח<sup data-n=\"6237\">746</sup> המוליד את הולד שהוא בא בהעלם גדול בהיותו סתום במעי אמו עד שמתפשטים גידול אבריו בשר<sup data-n=\"6238\">747</sup> יוצא לגילוי כל מה שהוא בהעלם בכח המוליד<sup data-n=\"6239\">748</sup> בטפת הדכר שהוליד את הולד, וכך הוא בבחי' טפת אבא שהוא מקור <span data-k=\"pg\">קסא</span> ּ המוליד למדות דאהוי\"ר סתום אור כחו במדות אלה אע\"פ שכבר יצאו מכח המוליד דאור טפת יסוד אבא אבל הוא סתום ונעלם בבינה כנ\"ל ע\"כ המדות האלה הן סתומים ונעלמים בבינה בתכלית הקטנות כנ\"ל עד שמתפשטים ויוצאי' לגילוי (כמ\"ש<sup data-n=\"6240\">749</sup> בזהר ע\"פ מראש צורים אראנו<sup data-n=\"6241\">750</sup> כו', (ודוגמא לכ\"ז הוא מה שאנו רואים בתושב\"כ ותושבע\"פ שנק' חו\"ב<sup data-n=\"6242\">751</sup> וספר וסיפור<sup data-n=\"6243\">752</sup> כו' דתושב\"כ היא בחי' נקודה דאור אבא [ד]חכ' שבא הכל בסתימות ובקיצור בכל פ' ופ' ובתושבע\"פ בא העלם זה לגילוי כמו שנדרש מכל אות וקוץ תלי תלים של הלכות כמו מנלן א\"ק<sup data-n=\"6244\">753</sup> כו' כמו יש אם למקרא יש אם למסורת<sup data-n=\"6245\">754</sup>, אבל עד שבא לגילוי גמור במשנה ותלמוד הכל סתום ונעלם בהיכל דבינה כמ\"ש במ\"א עמ\"ש אנהגך אביאך אל בית אמי תלמדני<sup data-n=\"6246\">755</sup> כו' וכן מ\"ש הביאני המלך חדרי\"ו<sup data-n=\"6247\">756</sup> וכמ\"[ש] אשר כתבתי להורותם להרת\"ם<sup data-n=\"6248\">757</sup> כתי' ועכ\"ז כשבא לגילוי גמור בו\"ק דשיתא ס\"מ נאמר אל תטוש תור\"ת אמ\"ך<sup data-n=\"6249\">758</sup> כולד הנולד כו' וד\"ל).\n<b>אך</b> הנה עדיין י\"ל בענין בחי' [ע]יבור דקטנות דולד במעי אמו שראשו בין ברכיו כנ\"ל שלפי הנ\"ל הרי יש בזה ב' ענינים הפכיים בנושא א' ממש, שהרי עיקר ענין בחי' העיבור הוא שהמדות דאוי\"ר דהיינו מה ש[י]חייב השכל שראוי לאהוב ולירא כו' הוא כלול בהעלם בשכל דבינה הרי השכל עיקר והמדות טפלים ובטלים במציאות[ן] לפי שנכללים בשכל, וענין ראשו בין ברכיו היינו שהשכל והמוחי' כלולים בהעלם גדול [במדות] תלת גו תלת [כו'] כנ\"ל שהוא להיפוך שהמדות נראי' עיקר והשכל והטעם שבהן בהעלם הן כמו טפל לעיקר, ואיך יוכל להיות ב' הפכים בנושא א'. ובאמת זה וזה נק' בחי' קטנות אלא שהעלם והתכללות המדות בשכל נק' קטנות המדות בכלל והעלם השכל במדות נק' קטנות המוחי' ושניהם כא' באים. וכידוע שיש ב' מיני העלם, העלם העליון בתחתון והעלם התחתון בעליון, והן ב' מיני מלויים הפכיים ויכולים להיות כא'. והוא מה שאנו רואים [בעבודת ה'] בענין אהוי\"ר דקטנות מה שהשכל מחייב אהבה או",[["6237","746","<b>כח</b>: ביד: ליתא."],["6238","747","<b>בשר</b>: שם: בט\"ח."],["6239","748","<b>שהוא. . בכח המוליד</b>: שם: שהי'. . ובכח היולי."],["6240","749","<b>(כמ\"ש</b>: ביד: וכמ\"ש. ואולי סיום הסוגר הוא לאחרי תיבות: אראנו כו'."],["6241","750","<b>מראש צורים אראנו</b>: בלק כג, ט. זהר בלק רג, ב. ראה ביאוה\"ז שם קג, א ואילך. מאמרי אדה\"ז תקס\"ח ח\"א ע' רסט ואילך."],["6242","751","<b>בתושב\"כ ותושבע\"פ שנק' חו\"ב</b>: נסמן לעיל צד, ד הערה 387."],["6243","752","<b>בתושב\"כ ותושבע\"פ. . וספר וסיפור</b>: נסמן לעיל פ' שמות ט, ג."],["6244","753","<b>מנלן א\"ק</b>: ראה גם לעיל שם. וש\"נ."],["6245","754","<b>יש אם למקרא. . למסורת</b>: קידושין יח, ב."],["6246","755","<b>אנהגך. . תלמדני</b>: שה\"ש ח, ב. ראה גם מאמרי אדה\"א בראשית ע' שנא."],["6247","756","<b>הביאני המלך חדרי\"ו</b>: שה\"ש א, ד."],["6248","757","<b>אשר כתבתי להורותם להרת\"ם</b>: נסמן לעיל פ' שמות יז, א."],["6249","758","<b>אל תטוש תור\"ת אמ\"ך</b>: משלי א, ח [ושם: ואל]. ראה גם לעיל ט, ב ובהנסמן לשם."]]],[2300540924,"יראה אע\"פ שהן בהעלם ובקטנות העיבור והתכללות בשכל המחייבן הנה יש באהבה ויראה זו בכח ובהעלם כל מה שעתיד לימשך בהן בחי' המוחין דגדלות דאו\"א שהוא לאחר שנולדים המדות אהוי\"ר בלב יתגדלו בטעם ושכל גמור והתפעלות האהוי\"ר כמ\"ש לפי שכלו יהולל איש<sup data-n=\"6250\">759</sup> כו' (כמשי\"ת), רק שהמוחי' הללו הן עכשיו באהוי\"ר זו בכח ובהעלם בבחי' נה\"י שבהן לבד שזה ענין ג' [גו] ג' ראשו בין ברכיו כו' (שהוא רק ההודאה שכך יאתה ע\"פ השכל, וג\"ז אמת דההודאה זו כלולה בהתכללות בשכל כאלו אינו במציאות בפ\"ע כלל ונק' מח' טובה<sup data-n=\"6251\">760</sup> שה' מצרפה למעשה (כמ\"ש בלק\"א פי\"ו) דהיינו שעתידה מח' שבהודאה זו לבא למעשה כשהוא בבחי' גדלות המוחי' וגדלות המדות בגילוי חג\"ת ונה\"י כנ\"ל דבזמן הגלות שנק' עיבור בחי' אוי\"ר זה שבהעלם בשכל חזקי' מאד לענין מעשה בסו\"מ וע\"ט כל היום כמו ש[י]הי' בלידה כו'). ודוגמא לזה דיבור שכלול בהעלם במח' שהוא מתעלם בדבור אח\"כ בהתפשטות והרחב[ה] או כמו טעם לרצון שכלול <span data-k=\"pg\">324</span> ּ ברצון שלמעלה מן הטעם, וזהו העלם השכל ברצון שבשעה זו עצמ[ה] יש העלם [ו]כח הרצון בטעם זה שעתיד להתפשט ולהתגלות בהרחבה כמו והחכ' מאין תמצא<sup data-n=\"6252\">761</sup> מההעלם לגילוי כידוע וד\"ל. ונמצא כשהמדות דאהוי\"ר הנ\"ל כלול[י'] בהעלם בשכל לפי שאינם רק קצה האחרון של השכל שהוא רק מה שהשכל נותן ומחייב לאהוי\"ר ואינם נחשבים מאומה לגבי עיקר השכל, הרי באותה שעה עצמה השכל בהעלם גדול במדות אהוי\"ר הללו הרי לא נשאר בהן רק [מה] ש[י]חייב לאהוי\"ר לבד שהוא רק ההסכם לבד כו', וא\"כ קטנות המוחי' שבמדות הללו בהעלם וקטנות המדות שהן בהעלם בשכל הן באים כא' ממש, רק שמ\"מ יש הפרש בזה דבחי' קטנות המדות הוא מצד שכלולים במוחי' דאימא כמו אוכל מה שאמו אוכלת כו' שהרי אין קיום לאהוי\"ר הנ\"ל רק ממה שהשכל יחייב והן עצמן בלתי מורגשים כלל רק מה שהשכל נותן שיאהוב כו', ובחי' קטנות המוחי' במדות הללו הוא מוחי' דאימא ששייך להתפעלות המדות הללו כשיהי' בגדלות שזהו השכל שייך רק להמדות ולא מוחי' דאימא עצמה, אבל מה שהשכל מחייב אהוי\"ר הוא בעצם המוחי' דאימא ממש (והוא בחי' ז\"ת דאימא כמשי\"ת) וד\"ל. והנה ידוע שיש ה' מדריגות עיבור יניקה ומוחי' ובמוחי' יש ב' מדריגות מוחי' ששייך למדות לבד ומוחי' דאימא הוא הנמשך בשביל גדל[ו]ת המוחי' שבמדות, והב' גדלות המוחי' דאימא עצמה במדות והוא הנק' גדלות ראשון דאימא, והג' גדלות שני באבא (והוא ענין למ\"ד מ\"ם דצל\"ם והצ' הוא המוחי' שמצומצם לפי המדות לבד כו' וספי' ומ\"ת הן גדלות ראשון דאימא וגדלות שני דאבא) ונמצא יש כאן ה' מדרגות.",[["6250","759","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."],["6251","760","<b>מח' טובה</b>: קידושין מ, א."],["6252","761","<b>והחכ' מאין תמצא</b>: איוב כח, יב."]]],[2300540931,"<b>וביאור</b> כ\"ז, הנה אחר בחי' העיבור דקטנות המדות דאהוי\"ר הנ\"ל הכלולים בתכלית בשכל כולד שמקופל כו' (וגידולו ט\"ח בבטן והוא להיות כל האברים מוכנים לקבל נרנח\"י כשיולד עד שיזקין כידוע במה שמלמדים לתינוק<sup data-n=\"6253\">762</sup> כו' (והגאולה<sup data-n=\"6254\">763</sup> שנק' לידה נאמר אז יאמרו בגוים<sup data-n=\"6255\">764</sup> הגדי\"ל ה' לעשות עם אלה בב' מיני גדלות הנ\"ל), אח\"כ נולדים המדות ויוצאים לחוץ דהיינו שנמשך מן המוח אל הלב במהות התפעלות הלב באהוי\"ר ממש ואז נתצמצם כל השכל ולא נשאר רק התפעלות הלב לבד באהוי\"ר בבחי' הקטנות בין במדות בין במוחי', דהיינו שהשכל והטעם של האהוי\"ר מצומצם מאד בהן ולא ניכר במציאות כלל וכלל כאלו אין להם מקור המוליד כלל וכתינוק שנולד בבטן אמו שנעשה למהות בריאה בפ\"ע נבדל ונפרד מן [האם כך המדות כשנולדים בלב נעשי' במהות בפ\"ע נבדל ונפרד מן] השכל שבמוח לגמרי ואח\"כ מתחיל גידול המדות והמוחי' שבהם כא' ממש, וההתחלה הוא גידול דמוחי' דיניקה כמו שע\"י החלב נגדלים אבריו שהוא החומר וגם החומר של המוחי' שלו נגדלים כא' עם חומר המדות שבו, כי ביניקה המוחי' שלו בהעלם גדול במדות וגם המדות הן בקטנות מאד ובתשלום ימי היניקה נגדלים חומר המוחי' והמדות כא' כמו גידול הצומח דעץ כמ\"ש כי האדם עץ השדה<sup data-n=\"6256\">765</sup> שנגדל חומר העץ שיהי' מוכן לגידול הפירות עד שבהיותו בן ב' שנים<sup data-n=\"6257\">766</sup> ויודע לקרות אבא <span data-k=\"pg\">קסב</span> ּ ואימא כשיטעום טעם דגן כידוע, וקריאה זאת הכרה היא בהעלם הדעת והמוחי' שבו לפ\"ע גידול חומר מדותיו עד שיכיר ויבחין בין טו\"ר בהכרה שלימה בשכלו ומדותיו מעט מעט בענינים קטנים שנמצא גידול זה הוא רק גידול חומר המוחי' ומדות כא' ממש, אך לא נגלה בו עדיין מוחין שלימים [ומדות שלימים] כי אין בהם תוקף וכח כלל רק בבחי' הקטנות לבד בענינים קטנים לפי דרכן עד שיהי' בן וי\"ו וז' שנים ש[אז] נק' פעוטות<sup data-n=\"6258\">767</sup> שמקחן מקח כו' שאז [נ]גדלו המדות חו\"ג הן [ו]לאו במקצתן עם גידול המוחין ששייך למדות כא', לפי ששכלו ומדותיו<sup data-n=\"6259\">768</sup> נתגדלו יותר ע\"כ מדותיו ממילא [נ]גדלו במקצתן מה ששייך למדת חסד או דין ורחמים ונג\"ה<sup data-n=\"6260\">769</sup> שהוא הן ולאו שלא יטה א\"ע להפוך דעתו ומדותיו מלאו להן ומחסד לדין וכה\"ג. וכך הוא בעבודת ה' שמתפעל בלבו באהבה שמצד הטעם ודעת קצת שיצמצם לפ\"ע גידול המדות דאהוי\"ר אבל עדיין אין בזה שלימות גידולו לא במוחי' ולא במדות, שהרי אין הקטן קודם י\"ג שנה בר עונשין<sup data-n=\"6261\">*770</sup> כי לאו בני דיעה<sup data-n=\"6262\">770</sup> גמורה הן ונוחים להתפתות ולשנות דעתם ומדות שלהם כידוע וכמ\"ש קטן אין לו מחשבה<sup data-n=\"6263\">771</sup> פי' מח' שבדעת המתפשט במדות עד היותו בן י\"ג שנה דוקא שאז נגדל[ו]",[["6253","762","<b>במה שמלמדים לתינוק</b>: נדה ל, ב. ראה מפרשי הע\"י שם. לקמן פ' ויקהל תב, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380488\" data-slug=\"likkutei-torah\" data-id=\"4001380488\">לקו\"ת שלח מד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051013\" data-slug=\"likkutei-sichot\" data-id=\"1300051013\">לקו\"ש בראשית (כרך ה) ע' 13</a> ואילך."],["6254","763","<b>(והגאולה</b>: ב: והגאולה."],["6255","764","<b>אז יאמרו בגוים</b>: תהלים קכו, ב."],["6256","765","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["6257","766","<b>בן ב' שנים</b>: ראה לעיל צה, ב."],["6258","767","<b>וי\"ו וז'. . פעוטות</b>: גיטין נט, א."],["6259","768","<b>ומדותיו</b>: ביד: ומוחו."],["6260","769","<b>ונג\"ה</b>: שם: ונו\"ה."],["6261","*770","<b>אין הקטן. . בר עונשין</b>: ראה נזיר נז, ב."],["6262","770","<b>הקטן. . לאו בני דיעה</b>: ראה חגיגה ב, ב. גיטין כב, סע\"ב. כג, א."],["6263","771","<b>קטן אין לו מחשבה</b>: ראה חולין יב, ב. מאמרי אדה\"א דברים ח\"א ע' רמד. וש\"נ."]]],[2300540938,"המוחי' ששייך למדות לשלימות המדות ע\"כ נק' בר עונשים<sup data-n=\"6264\">772</sup> על ל\"ת וביטול מ\"ע שתלוים בחו\"ג שע\"י הדעת המתפשט בהן דוקא, וזהו בחי' שלימות גדלות המוחי' שבמדות אבל אין זה רק מה ששייך לגידול המדות לבד לשלימותן כו'). וזהו ג' מדריגות דעיבור יניקה [ו]מוחי' דמוחי' הללו הגם שנק' מוחי' דגדלות אבל הוא רק גדלות המוחין ששייך למדות לבד ולא גדלות המוחי' בעצם מהותן עדיין, אך מי\"ג שנה עד כ' שהן ז' שנ[ים] נגדלי' המוחי' עצמן והוא מ\"ש לפי שכלו ממש שהוא גידול מוח בינה שהוליד המדות שנגדל בעצם כך יהולל איש שהן המדות ג\"כ כו'. והענין הוא כידוע הסימן לזה והוא כאשר המוח שליט על הלב<sup data-n=\"6265\">773</sup> דוקא דהיינו שהשכל שבמוח הוא העיקר והתפעלות המדות נגררים וטפלים אחר השכל שבמוח לגמרי ולא ניכר רק התפעלו' המוחי' אף שכבר נולדו המדות והן בגדלות ע\"פ ערך גידול המוחי' שבהם מ\"מ הן טפלים ונכללים בהתפעלות השכל דוקא ואז סימן הוא לגידול השכל שבמוח בינה [שמצד] עצמה (והן ז' מדות שבשכל דאימא שהוא חו\"ג וממוצע שיבא רק מחמת ההשגה וטעם שבשכל שהן בתוקף גדול מאד עד שנכללים בזה [התפעלות] המדות שבלב ושולטים ומושלים עליהם כמו בעבודה שבלב בתפלה גם לאחר שנתפעל הלב נכלל בהתפעלו' המוח וע\"כ יכול המוח לשלוט על הלב לעצור רוחו או להטותו מהיפוך להיפוך תומ\"י). וזהו ההפרש בין תכלית הקטנות דמדות אהוי\"ר במ\"ם סתומה שכלולים במוח הבינה לגמרי בלתי מורגשים כלל כנ\"ל שהוא רק מה ש[י]חייב השכל לאהוי\"ר כו', ובין מ\"ם פתוחה שהוא לאחר שנולדו המדות ונגדלים בגידול המוחי' מעט מעט בצמצום רק כפי המדות וקיומם לבד ואח\"כ גובר עליהם אור השכל והשגה שבמוח ומאיר עליהם בגילוי רב עד ששליט על המדות שבלב וטפלים ונגררים אחריו (וכאשר האם רובצת על האפרוחי' היינו בימי קטנותן שהוא ע\"י גידול אימא להיות שלימות המוחי' <span data-k=\"pg\">326</span> ּ במדות לפ\"ע המדות לבד). וזהו מדריגה הד' שנק' גדלות ראשון דאימא (שהוא ל' דצל\"ם שנק' צ\"ל והוא ענין הספירה והצ' הוא רק גידול המוחי' דמדות לבד שבאי' כא' כנ\"ל). והמדריגה הה' הוא גדלות שני דאבא והוא תוקף כח החכ' שלמעלה גם מן ההשגה וטעם שבבינה ונק' מדות דאבא, כידוע בהפרש בין שכל המטה כלפי חסד מצד הטעם שנק' פנים מסבירות ובין שכל ה[מ]טה כלפי חסד מצד העצם למעלה מן הטעם כמו ב\"ש אוסרין כו', וכענין ששאלו לרב מה בין זה לעגל כו' שתק רב<sup data-n=\"6266\">774</sup> ולא חזר בו מצד עצם כח שכלו מטה כלפי חסד או דין והן המדות דאבא שלמעלה ממדות שבהשגה דאימא, והיינו לאחר גידול המדות בלב עד שנכללים בז\"ת",[["6264","772","<b>י\"ג שנה. . בר עונשים</b>: ראה סנהדרין סח, ב. מאמרי אדה\"א קונטרסים ע' תיג. וש\"נ."],["6265","773","<b>המוח שליט על הלב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310017\" data-slug=\"tanya\" data-id=\"3401310017\">תניא פי\"ב</a>. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תצ."],["6266","774","<b>שתק רב</b>: ביצה ו, א. ראה מאמרי אדה\"א בראשית ס\"ע צד ואילך. וש\"נ. לקמן פ' תצוה שנד, ב. פקודי תנ, ד. סידור שער נפ\"א צב, ג. תו\"ח ח\"ש קמ, סע\"ד ואילך. וישב רז, ד. שער האמונה לז, א. שער היחוד קכח, א. מאמרי אדה\"א נ\"ך ע' שנט. קונטרסים ע' קיב וע' קיג."]]],[2300540945,"דאימא שהוא תוקף האהוי\"ר שבשכל עצמו שלא ניכר רק התפעלות השכל לבד ולא ניכר התפעלות אהבה במציאות בפ\"ע רק שנגרר אחר התפעלות השכל והשגה אז גובר עצם מהות [ה]חכמה במדות שבה [ב]עצם למעלה מן הטעם והשגה. ונמצא ששרש בחי' קטנות דאהוי\"ר שיחייב השכל שאין בהם גילוי אור השכל כלל רק הסכם החיוב לאהוי\"ר [לבד הוא עולה בתכלית הגדלות הב' דאבא שהוא הטיית עצם מהות השכל לאוי\"ר] למעלה מן הטעם כו') (וזהו ענין המצה שהוא האמונה בבחי' קטנות דאבא ששלימות[ה] הוא בחי' גדלות הב' דאבא במ\"ת כידוע). וזהו מיצר מ\"י דבינה היינו מצר י\"ם דחכמה שהוא יצ\"מ ממיצר מ\"י עלו לגדלות המדות דאבא שנק' י\"ם [כו'] והוא מ\"ם סתומה דלמרבה המשרה לאחר שלימות הגידול דמדות שבעיבור במעי אמו יותר מגדלות דאימא כו' והוא מ\"ם דצלם שעז\"א אך בצלם יתהלך איש<sup data-n=\"6267\">775</sup> שהן המדות כידוע וד\"ל.\n<b>וב</b>[כל] זה יובן ענין עבדים היינו לפרעה במצרים, כי הנה עיקר ענין יצ\"מ הוא יציאת המדות ממיצר מ\"י דבינה הנ\"ל שיולדו למהות בפ\"ע, וידוע בשרש כנס\"י למעלה שהוא במדות דז\"א<sup data-n=\"6268\">776</sup> שהן ת\"ר אלף מו\"ק דז\"א דאצי' [ד]כל מדה נחלקה לק' אלף, ושרש המדות דז\"א בבינה דאצי' אם הבנים שהוא מקור כל השגות [הנשמות שנחלקי' לת\"ר אלף דיעות כמו שיש שכל מתפעל כך וכמ\"ש תוכן רוחות<sup data-n=\"6269\">777</sup> כו', ובעודם כלולים בהעלם במקור כל ההשגות] כמו הולד בבטן כנ\"ל נק' מיצר מ\"י ושרשם הראשון הוא באור אבא דאצי' כמ\"ש כי אתה אבינו, והוא מקור הראשון המוליד כל עצם ומהות הנשמה שהוא בחי' כח הביטול העצמי דכח מ\"ה שלמעלה מן ההשגה לגמרי זהו הנק' מיצר י\"ם דחכ' וזהו מצרים מצר י\"ם ומצר מ\"י דחו\"ב שנק' או\"א, וכאשר שרש נש\"י בבחי' עיבור בבינה שהוא הקטנות דאוי\"ר שכלול במוח בינה הנ\"ל אזי יש כח לפרעה שיונק באחוריי' דכתר בעורף למשול על ישראל למטה מפני שמונע בחי' הלידה להיות בבחי' הגדלת המוחי' והמדות כנ\"ל. והענין הוא כנ\"ל דבחי' אחוריים דכתר הוא בחי' חיצוני' הרצון המסתיר על פנימי' הרצון וכאשר באתעדל\"ת כנס\"י הן בבחי' פנימי' הרצון ממילא כמים הפא\"פ אתעדל\"ע ג\"כ [א]ליהם בפנימי' רצה\"ע שהוא בחי' פנימי'<sup data-n=\"6270\">778</sup> דא\"א כמו יאר ה' פניו אליך כו', ואז גם ההשג[ח]ה האלקי' עליהם מבחי' פנימי' הרצה\"ע ש[ב]פנימי' חו\"ב ומדות דבחי' גדלות המוחי' לפי שגם בכנס\"י הוא בבחי' פנימיות המוחי' דחו\"ב באוי\"ר פנימי' (שהמוחי' דחו\"ב עיקר והמדות אהוי\"ר נגררים אחריהם כענין הנ\"ל דמוח שליט על הלב) שנק' פנימי' הלב כמו לך א' לבי<sup data-n=\"6271\">779</sup> בקשו פני את פניך",[["6267","775","<b>אך בצלם יתהלך איש שהן המדות</b>: תהלים לט, ז. ראה גם מאמרי אדה\"א נ\"ך ע' רסו. וש\"נ."],["6268","776","<b>כנס\"י. . במדות דז\"א</b>: ראה לקו\"ת להאריז\"ל פ' וישב דרוש גלות מצרים. לקמן פ' בשלח רמג, ב. רמו, ד."],["6269","777","<b>תוכן רוחות</b>: משלי טז, ב [ושם: ותוכן — ראה לעיל פ' וארא עט, ב. ש\"א צג, א. שע\"ת נא, ד הערה 79]. ראה לעיל עט, ב."],["6270","778","<b>פנימי'</b>: יד: פנים."],["6271","779","<b>לך א' לבי</b>: תהלים כז, ח."]]],[2300540952,"ה' אבקש וכמו במ\"ת שדיבר עמהם פב\"פ כו', אבל כאשר ישראל הן בבחי' קטנות האהוי\"ר רק שהוא הודאה והסכם במוח לאהוי\"ר כנ\"ל ופנימי' המוחי' ורצון הוא בהעלם ומרחוק כמו<sup data-n=\"6272\">780</sup> אתעדל\"ע בחיצוני' הרצון לבד <span data-k=\"pg\">קסג</span> ּ וכמו כי פנו אלי עורף<sup data-n=\"6273\">781</sup> חיצוני' הרצון ולא פנים כו', וע\"כ גם ההשגחה האלקי' באה אליהם דרך חיצוני' הרצון שהוא בבחי' עורף דאחוריים דכתר ש[ז]הו כאשר השפע נמשך רק דרך אגב וטפל כו', והוא מפני שפנימי' רצה\"ע מוסתר ונעלם כמו בזמן הגלות דכתיב הסתר אסתיר פני כו' והוא מ\"ש ויקם מלך חדש אשר לא ידע את יוסף בחי' פנימי' יסוד דא\"א כנ\"ל. והגם שבימי יוסף הי' ג\"כ השפע הולך ע\"י פרעה, אבל הי' בפרעה ועמו בחי' ביטול לגמרי לגבי יוסף שהי' עיקר המושל על כל ארץ מצרים<sup data-n=\"6274\">782</sup> והוא המשביר בר<sup data-n=\"6275\">783</sup> כו'. אבל לאחר מות יוסף הי' להיפוך ששעבדו בישראל בעבודה קשה כו'. והטעם הוא לפי שע\"י הסתלקות יסוד דא\"א הרי גבר בחי' חיצוני' הרצון שיונק משם פרעה להיות מונע בחי' הלידה כמ\"ש בפע\"ח דפרעה אוחז בעורף ומונע הלידה כו', והענין הוא כמו שאנו רואים בחוש בזמן הגלות שנק' עיבור כמ\"ש כי פנו אלי עורף שהוא רק בחיצוני' של הרצון מן השפה ולחוץ, כמו בפיו ובשפתיו כבדוני ולבם רחק ממני<sup data-n=\"6276\">784</sup> שאין זה רק הסכמה והודאה במוח לאהוי\"ר לבד כנ\"ל ופנימי' הרצון והלב מקושר בעניני עוה\"ז ואז גובר התקשרות זו למנוע ענין לידה זו שאינו נולד אהוי\"ר כלל מהודאה זו שבמוח רק נשאר בהעלם המח' שבמוח והוא רק מצד שאין פנימי' הרצון לאלקים חיים והיינו כמשל ב' בנ\"א שעומדים אב\"א כו' וגם כל המצות מעשיות שנעשה יחו\"ע הוא רק בחיצוני' ולא בפנימיות כו'. ומזה הי' נמשך סיבת העבודה [ה]קשה [משר] של מצרים רק למנוע בחי' הלידה וכמ\"ש פרעה תכבד העבודה על האנשים<sup data-n=\"6277\">785</sup> כו' שהוא הלחץ ודחק מן עוצם דחיקת הפרנסה למרר חייהם כו' כדי שלא יבואו לכלל פנימי' הרצון והלב מצד שרש יניקתו באחוריים בלי גילוי פנימי' כלל, והוא משום שלא ידע את יוסף דוקא, וכך הוא בכל גלות שבחי' יוסף צ\"ע בהעלם והסתלקות כמ\"ש הצדיק אבד<sup data-n=\"6278\">786</sup> כו' וד\"ל.\n<b>ולהבין</b> ענין ההמשכה מחיצוני' הרצון דבחי' עורף בתוספת ביאור יש להקדים ענין א' המבואר במ\"א בבחי' ג' כלים<sup data-n=\"6279\">787</sup> פנימי אמצעי חיצון שנק' [ס]ת\"ר והוא רת\"ס<sup data-n=\"6280\">*788</sup> לנגד ג' אורות פנימי אמצעי חיצון שיש בכל מדה וספירה בפרט, ויובן זה מג' לבושי הנפש מחדו\"מ שלבוש המח' פנימי' יותר שנמשך מפנימי' הנפש יותר כנראה בחוש שפנימי' החשק והרצון יהרהר מיד במחשבה משא\"כ בדיבור יוכל לדבר בחיצוני' הרצון והיפוך",[["6272","780","<b>כמו</b>: ביד: כך."],["6273","781","<b>כי פנו אלי עורף</b>: ירמי' ב, כז. ראה גם לקמן פ' תצוה שלח, א."],["6274","782","<b>המושל על כל ארץ מצרים</b>: ויגש מה, כו."],["6275","783","<b>המשביר בר</b>: מקץ מא, נו. נז. מב, ג. ו."],["6276","784","<b>בפיו ובשפתיו. . ממני</b>: ישעי' כט, יג [ושם: ולבו וכ\"ה בב — ראה לקמן פ' בשלח רכט, ג. מאמרי אדה\"א שמות ח\"ב ע' תסט. דברים ח\"ב ע' תקמו. נ\"ך ע' צא]."],["6277","785","<b>תכבד העבודה על האנשים</b>: שמות ה, ט."],["6278","786","<b>הצדיק אבד</b>: ישעי' נז, א. ראה זהר שמות יא, א."],["6279","787","<b>ג' כלים</b>: ראה גם מאמרי אדה\"ז תקס\"ט ע' רכא."],["6280","*788","<b>[ס]ת\"ר והוא רת\"ס</b>: נסמן לקמן פ' תרומה שי, ד."]]],[2300540959,"רצונו כו', ויש במח' ג' אורות מחדו\"מ<sup data-n=\"6281\">788</sup> כח המח' ודיבור המח' ואותיות המחשבה וג' כלים כלי פנימי' לבד<sup data-n=\"6282\">789</sup> המח' גידי המוח ששם אור השכל ובנפש קבועים בעצם הנפש, ודיבור שבמח' או לציור אותיות במח' שנק' עשי' דמח' הכל ע\"י התחלקו' אותיות [ד]מחשבה שיש לזה כלי בפ\"ע כמו כלי הדבור להתחלקות כ\"ב אותיות בפה (ומ\"ש קטן אין לו מחשבה הוא מחשבה הפנימי' וגם לא דיבור דמח' אבל כח הדמיון דמחשבה ולצייר דבר במח' יש לו והוא בחי' [ה]קטנות דמח'), אבל מה שיש במחשבה מדות לאוי\"ר כמו הפחד שבמח' וחשק התאוה יש גם בתינוק היונק<sup data-n=\"6283\">790</sup> שאינו ע\"פ השכל והתבוננות רק טבעי' מ\"מ זהו למעלה מציור האותיות ודומם במח' וכ\"ש למעלה מן הדמיון שבמח' שהוא עשי' דעשי', ועכ\"ז אנו רואים <span data-k=\"pg\">328</span> ּ בתינוק קודם שיוכל לדבר שהוא מדיבור שבמח' יש במחשבה מדות דאוי\"ר דקטנות הטבעי' [ה]נ\"ל ואין לו ציור האותיות במח' רק ציור דומם וכח הדמיון לבד כנ\"ל. ולפי\"ז בחי' אוי\"ר דקטנות ע\"פ הסכם השכל שבמוח בכנס\"י הוא למעלה גם מבחי' [מדות] דמח' שבתינוק הנ\"ל אלא כתינוק שיודע לקרות אבא ואימא בדיבור ע\"פ הכרה ודעת שבמוח כו'. ולדמיון ועשי' שבמוח<sup data-n=\"6284\">791</sup> יש כלי בפ\"ע (שהרי הקלקול בכלי המוח או בשינה נסתלקו פנימי' ואמצעי' דמח' וגם יוכל להתקלקל גם כח הדמיון כמו הבלבול וכה\"ג<sup data-n=\"6285\">792</sup>. וכמו\"כ יש ג' כלים פנימי ואמצעי וחיצון לדבור, והיינו מחשבה שבדבור וכח הדבור הנחלק בה' מוצאות ואותיות וקול הדבור ממש שמלובש[ים] בה' מוצאות הנ\"ל<sup data-n=\"6286\">793</sup> ממש [כו'], וראי' מתינוק שאין יכול לדבר אעפ\"י שהנפש נק' רוח ממללא<sup data-n=\"6287\">794</sup> מצד העדר הכלים, כי בנפש עצמה יש ג' אורות דדיבור כמו בג' אורות דמח' ומתלבשים בג' כלים פנימי ואמצעי וחיצון, אבל בכלל[ות] כח הדבור הוא נמשך מחיצוני' הנפש יותר מן כח המח' כו'. ולבוש הג' הוא כח המעשה שיש [בו] מחשבה שחושב באופן המעשה וכח המעשה עצמה וגילוי עצם הפעולה והמעשה כו', ויש לזה ג' כלים רת\"ס עד כלי החיצון יותר דעשי' [דעשי'] כפעולת היד כו' והוא בכללות לבוש היותר חיצוני מן הנפש כו'. וכמו\"כ יש במדות אהוי\"ר ג' כלים רת\"ס פא\"ח<sup data-n=\"6288\">795</sup> לנגד ג' אורות דחב\"ד חג\"ת נה\"י מוחי' ויניקה ועיבור כידוע. וכך הוא בחו\"ב עד נצח דחסד דאו\"א בכלי החיצון שבו, וכך הוא גם ברצון שהוא פנימי' הרצון בפנימי' השכל וטעם לרצון וזה מלובש בכלי פנימי המיוחד לזה, ובחי' [כלי] אמצעי למדות שברצון, וכלי חיצוני לנה\"י שברצון עד חיצוני' דחיצוני' דעשי' שברצון שהוא רק הרצון למעשה בפו\"מ לבד בלי שום פנימי' דשכל ומדות [ו]נצחון וכה\"ג כלל וכלל כו' (וכך הוא בענין אוי\"ר דקטנות במוח הנ\"ל בכנס\"י הוא מחשבה טובה שברצון רק לענין מעשה עכ\"פ להיות סו\"מ וע\"ט כל היום בלי פנימי' כלל וכלל כו'). ולפי\"ז יובן שגם",[["6281","788","<b>מחדו\"מ</b>: ביד: מח' דמח'."],["6282","789","<b>לבד</b>: שם: לכח."],["6283","790","<b>היונק</b>: ביד: הגם."],["6284","791","<b>שבמוח</b>: ב: שבמח'. יד: דמח'."],["6285","792","<b>וכה\"ג</b>: אוצ\"ל: וכה\"ג)."],["6286","793","<b>הנ\"ל</b>: ביד: ליתא."],["6287","794","<b>שהנפש נק' רוח ממללא</b>: ת\"א לבראשית ב, ז."],["6288","795","<b>פא\"ח</b>: ב: פנימי אמצעי חיצון."]]],[2300540965,"בבחי' רצה\"ע שנק' א\"א יש פנים ואחור עד חיצוני' דחיצוני' דעשי' לבד כו', וכך הוא בבחי' ז\"א שהן המדות שנולדים מבינה שבמוח כנ\"ל ששרש המדות האלה למעלה מן השכל והוא ברצון ותענוג עצמו כמא' דז\"א בע\"י אחיד<sup data-n=\"6289\">796</sup> כו' יש במדות אלה ג\"כ בחי' פנימי אמצעי חיצון דג' כלים לג' אורות וכמא' אחור וקדם צרתני<sup data-n=\"6290\">797</sup> [רק] שה[ו]א תכלית הקיצור ממדות דא\"א, ועכ\"פ כאשר המדות דשכל בקטנות כנ\"ל מוכרח שבשרשם בא\"א שהן מדות שברצון ג\"כ בקטנות שהוא באחוריי' וחיצוני' הרצון כמו רצון הנמשך [ב]דרך אגב וטפל גם שאינו רק למעשה בחיצוני' וכמו כי פנו אלי עורף כנ\"ל וד\"ל.\n<b>אך</b> מ\"ש ואנכי תרגלתי לאפרים קחם על זרועותיו<sup data-n=\"6291\">798</sup> כננס ע\"ג הענק<sup data-n=\"6292\">*799</sup> שרואה למרחוק כו' זהו בחי' עלי' המדות דשכל דבינה מבחי' הקטנות לתכלית דגדלות דמדות שברצון כמו שהן למעלה גם מחו\"ב שברצון ותענוג והן הנק' ב' זרועות דא\"א כמו שהידים נגבהים למעלה מן המוחי' שבראש כו', כך כתי' וינטלם וינשאם<sup data-n=\"6293\">799</sup> כו' והוא מ\"ש קחם על זרועותיו כאדם שמגביה לבנו הילד הקטן <span data-k=\"pg\">קסד</span> ּ ונושאו על זרועותיו לקרבו למעלה גם מפניו כו' והוא כאשר נופל בידי זר יוציאנו משם ביד חזקה לקחתו על זרועותיו הגבה למעלה כו'. וכך ביצ\"מ כתיב ויוציאנו ה' משם ביד חזקה דהיינו מחיצוני' העורף דפרעה שבאחוריים דכת\"ר המונע הלידה דמדות דאוי\"ר שבהעלם בבינה שנק' מ\"ם סתומה שז\"ש בצאת ישראל ממצרים<sup data-n=\"6294\">800</sup> כנ\"ל, והוא ע\"י ב' זרועות כנ\"ל דא\"א שהוא יד החזקה וזרוע נטויה עי\"ז הי' הסיבה לבחי' לידה זו שיצאו המדות דאוי\"ר שבמוח בינה מההעלם לגילוי וכמו ענין קחם על זרועותיו הנ\"ל. וזהו עבדים היינו אנחנו בנ\"י בני ז\"א דאצי' שהיא בבחי' עיבור [ב]מיצר מ\"י דבינה ויוציאנו ה' אלקינו שהוא או\"א כידוע ע\"י יד חזקה וזרוע נטויה שהן בחי' ב' זרועות דא\"א שלמעלה גם מבחי' פנים דא\"א כנ\"ל והוא ע\"י מה שנעשה ההבדלה בין פנימי' [הרצון] וחיצוני' הרצון דעורף כנ\"ל באריכות וד\"ל.\n<b>אך</b> הנה<sup data-n=\"6295\">801</sup> מ\"ש ויוציאנו ה' אלקינו משם וידוע בפי' ה' אלקינו שהוא בחי' חו\"ב דאצי' וביד חזקה כו' והן בחי' ב' זרועות דא\"א כנ\"ל (ולמעלה מזה כמ\"ש קחם על זרועותיו כננס ע\"ג הענק כו' ), והענין הוא כידוע בע\"ח דאו\"א מלבישים לזרועות דא\"א<sup data-n=\"6296\">802</sup> ופי' הלבשה זאת הגם שבא בדרך לבוש לבד שהוא בבחי' חיצוני' עכ\"ז הר\"ז בא בבחי' קירוב גמור מאחר שמלובש ונתפס ממש (וראי' לזה ממ\"ש וירא ישראל<sup data-n=\"6297\">803</sup> את היד הגדולה בבחי' ראיה מקרוב ממש בזה הי' בקי\"ס וכך הי' ביצ\"מ ביד חזקה [ו]זרוע נטוי' שהי' בגילוי גמור ולא בדרך דילוג בהעלם",[["6289","796","<b>דז\"א בע\"י אחיד</b>: ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370090\" data-slug=\"torah-or\" data-id=\"3901370090\">תו\"א תולדות יט, ב</a>: בר\"מ. ראה זהר (אד\"ז) האזינו רצב, א. לקמן פ' בשלח רמח, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670312\" data-slug=\"torat-chaim\" data-id=\"2300670312\">תו\"ח בראשית יא, ד</a> ובהערה 7. שה\"א קו, ב ובהערה 11."],["6290","797","<b>אחור וקדם צרתני</b>: תהלים קלט, ה."],["6291","798","<b>ואנכי. . על זרועותיו [יד: אנכי. . זרועותי]</b>: נסמן לעיל פט, ב."],["6292","*799","<b>כננס ע\"ג הענק</b>: ראה שבולי הלקט בתחלתו הובא בהקדמת מגלת אסתר — לר\"י דילאון — לסה\"מ להרמב\"ם. לקמן פ' ויקהל תכג, ג. מאמרי אדה\"א ויקרא ח\"א ע' שלא."],["6293","799","<b>וינטלם וינשאם</b>: ישעי' סג, ט."],["6294","800","<b>בצאת ישראל ממצרים</b>: תהלים קיד, א."],["6295","801","<b>הנה</b>: ב: עדיין י\"ל."],["6296","802","<b>דאו\"א מלבישים לזרועות דא\"א</b>: ראה גם לעיל פט, ב. וש\"נ."],["6297","803","<b>וירא ישראל</b>: בשלח יד, לא."]]],[2300540971,"כו'). ויובן זה עד\"מ שאנו רואים בשכל המטה כלפי חסד או דין בלתי נמשך עדיין בטעם והשגה דהיינו חו\"ג דאבא וממילא יבא לכלל טעם והשגה דבינה שזהו בא רק מצד הטיית הרצון לחסד או לדין שחפץ ורוצה בכך ע\"כ ממילא ישכיל בשכל שמטה [כלפי חסד] וימצא טוב טעם לזכות וחסד כו', [כ]ענין השוחד שיעור עיני חכמים<sup data-n=\"6298\">804</sup> שע\"פ השוחד [יטה] רצונו לחסד ואז ממילא יטה שכלו לזכות וכמו בעובדא דר\"י שהביא לו כלכלה דפרי א' אי בעי טעין הכי<sup data-n=\"6299\">805</sup> כו', וכמו\"כ באהבה לאוהבו<sup data-n=\"6300\">806</sup> יטה רצונו עליו לחסד וכאב על בנו וממילא יטה שכלו לחסד ולהיפוך על שונאו יטה רצונו על דין וממילא יטה שכלו לדין כו'. ונמצא שבחי' המדות דחו\"ג דרצון מלובשים בקירוב גדול בשכל המטה כלפי חסד או דין, ואעפ\"י שהשכל והטעם לרצון הגלוי אינו רק בחי' לבוש להלביש מהות הרצון בעצם כמו שהוא באמת למעלה מן הטעם וכח<sup data-n=\"6301\">807</sup> זו הבאה בגילוי (שהרי גם אם [י]ב[ו]טל הטעם לא יבוטל הרצון), עכ\"ז הרי אנו רואים שמתאחדים כא' ממש שמיד שיטה רצונו לחסד יטה שכלו כך בהכרח והוא מפני שהרצון מתלבש בשכל זה ושכל זה הנוטה לחסד ודאי יש לו מקור מוצא, וכמ\"ש והחכ' מאי\"ן תמצא מאי\"ן דכת\"ר<sup data-n=\"6302\">808</sup> שהוא הרצון וכמו התהוות ההתחכמות שכלולים<sup data-n=\"6303\">809</sup> במו\"מ מפני שחפצו ורצונו להרויח למצוא טרף לנפשו וכה\"ג, הענין הוא דכאשר יגביר הרצון והחפץ ע\"ד מה אז <span data-k=\"pg\">330</span> ּ ממילא ימשיך מכח המשכיל ההיולי להשכיל שכליי' והמצאות הנק' התחכמות להוציא טעם ושכל לרצונו, והוא בחי' המשכה מן ההעלם לגילוי שבא ע\"י הטיי' הרצון לבד ואם ירצה להיפוך ימשיך מכח השכל להשכיל שכל וטעם להיפוך, כמו בענין המבול שא' וירא ה'<sup data-n=\"6304\">810</sup> כי רבה רעת האדם כו' ואח\"ז נתהפך מטעם [זה] עצמו לחסד בא' כי יצר לב האדם<sup data-n=\"6305\">811</sup> כו'. והיינו לפי שהשכל הוא רק כמו לבוש שפושטו [ו]לובשו והעיקר הוא הרצון שמלובש בו מפני שמטה את הכח השכלי להשכיל כפי שירצה ע\"כ יכול לפשוט מלבוש שכ\"ז<sup data-n=\"6306\">812</sup> להיפוכו כו' וד\"ל.\n<b>אך</b> הנה עדיין י\"ל<sup data-n=\"6307\">813</sup> בזה דהלא ידוע שמדות חו\"ג שברצון הוא למטה מן החו\"ב שברצון שנק' טעם כמוס לרצון דהיינו <sup data-n=\"6308\">814</sup>כמו דמה שהרצון נוטה לחסד או לדין הוא מצד טעם כמוס שבלתי אפשר שיבא לגילוי שכל כלל כענין שתוק כך עלה במח'<sup data-n=\"6309\">815</sup> לפני כמ\"ש במ\"א (פי'<sup data-n=\"6310\">816</sup> כך עלה ברצונו בלא טעם לדבר כלל כענין החוקה שהיא<sup data-n=\"6311\">817</sup> גזירת המלך), והוא בחי' ד\"ע שנק' דעת המטה לרצון כך ולא כך כו', וא\"כ מה שיומשך ממילא מכח השכל להשכיל בגילוי טעם ושכל לרצון זהו למטה מן בחי' הטעם כמוס [הנ\"ל] (הנק' ח\"ס) שא\"א שיבא בגילוי שכל כלל, ועכ\"ז הרי חו\"ג דרצון אעפ\"י שנמשכים מבחי' הטעם הכמוס",[["6298","804","<b>השוחד שיעור עיני חכמים</b>: פ' שופטים טז, כ. ראה גם לקמן קצט, ג. וש\"נ."],["6299","805","<b>אי בעי טעין הכי</b>: כתובות קה, ב."],["6300","806","<b>באהבה לאוהבו</b>: ביד: באהבת אוהב לאהובו."],["6301","807","<b>וכח</b>: ביד: וחכמה."],["6302","808","<b>והחכ' מאי\"ן. . דכת\"ר</b>: נסמן לעיל קא, ג."],["6303","809","<b>שכלולים</b>: ביד: שכליי'."],["6304","810","<b>וירא ה'</b>: בראשית ו, ה."],["6305","811","<b>כי יצר לב האדם </b>[ב ניתוסף: רע מנעוריו]: נח ח, כא. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670408\" data-slug=\"torat-chaim\" data-id=\"2300670408\">תו\"ח בראשית יד, א</a> ובהערה 3. לקמן פ' בשלח ר, ב."],["6306","812","<b>שכ\"ז</b>: ביד: שכל זה."],["6307","813","<b>עדיין י\"ל</b>: ביד: ליתא."],["6308","814","<b>כמו</b>: שם: ליתא."],["6309","815","<b>שתוק כך עלה במח'</b>: נסמן לעיל פט, ד."],["6310","816","<b>פי'</b>: ב: ופי' לפני."],["6311","817","<b>החוקה שהיא</b>: ב: ליתא."]]]]});
